window.MT_DATA['tr'] = [{"id":1,"name":"Niveau 1","freeLessonsPerModule":{"1":10,"2":0,"3":0},"modules":[{"id":1,"name":"Le quotidien","desc":"La vie de tous les jours en Turquie, en route et à la maison.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"L'appartement à Kadıköy","phrases":[{"fr":"La maison est grande.","tgt":"Ev büyük.","lit":"maison · grand"},{"fr":"L'appartement est petit mais joli.","tgt":"Daire küçük ama güzel.","lit":"appartement · petit · mais · joli"},{"fr":"Kadıköy est un beau quartier.","tgt":"Kadıköy güzel bir semt.","lit":"Kadıköy · beau · [un] · quartier"},{"fr":"La cuisine est toute propre.","tgt":"Mutfak tertemiz.","lit":"cuisine · tout-propre"},{"fr":"Le balcon est très beau.","tgt":"Balkon çok güzel.","lit":"balcon · très · beau"},{"fr":"La fenêtre est ouverte.","tgt":"Pencere açık.","lit":"fenêtre · ouvert"},{"fr":"Le salon est lumineux.","tgt":"Salon aydınlık.","lit":"salon · lumineux"},{"fr":"C'est une vieille maison.","tgt":"Bu eski bir ev.","lit":"ceci · vieux · [un] · maison"},{"fr":"La rue est calme.","tgt":"Sokak sakin.","lit":"rue · calme"},{"fr":"Le quartier est vivant.","tgt":"Mahalle canlı.","lit":"quartier · vivant"}],"tip":{"title":"Pas de genre ni d'article : « ev », la maison","example":"La maison est grande. — <b>Ev</b> büyük.","body":"Bonne nouvelle pour commencer : le turc n'a ni masculin ni féminin, et pas d'article « le » ou « la ». Le mot « ev » veut dire à la fois la maison, une maison, ou simplement maison. Pour dire « la maison est grande », on dit juste « ev büyük », mot à mot maison grand. Vous remarquez qu'il n'y a même pas de verbe être au milieu : on pose les deux mots côte à côte, et c'est une phrase complète. Si vous voulez insister sur « un », vous pouvez ajouter « bir », qui veut dire un : « eski bir ev », une vieille maison. Autres exemples : « sokak sakin », la rue est calme, et « daire küçük », l'appartement est petit. Astuce pour retenir : en turc, on dit l'essentiel, sans petits mots inutiles, comme dans un télégramme.","lit":"maison · grand","say":{"ev":"ev","ev büyük":"ev büyük","bir":"bir","eski bir ev":"eski bir ev","sokak sakin":"sokak sakin","daire küçük":"daire küçük"}}},{"title":"Le simit du matin","phrases":[{"fr":"Un simit, s'il vous plaît.","tgt":"Bir simit, lütfen.","lit":"un · simit · s'il-vous-plaît"},{"fr":"Le simit est encore chaud.","tgt":"Simit hâlâ sıcak.","lit":"simit · encore · chaud"},{"fr":"Pour moi, un thé sans sucre.","tgt":"Bana şekersiz bir çay.","lit":"moi-à · sucre-sans · [un] · thé"},{"fr":"Ce fromage est vraiment savoureux.","tgt":"Peynir çok lezzetli.","lit":"fromage · très · savoureux"},{"fr":"Un simit au fromage, s'il vous plaît.","tgt":"Peynirli simit, lütfen.","lit":"fromage-avec · simit · s'il-vous-plaît"},{"fr":"Le café au lait est bien chaud.","tgt":"Sütlü kahve çok sıcak.","lit":"lait-avec · café · très · chaud"},{"fr":"Un café sans lait, s'il vous plaît.","tgt":"Sütsüz bir kahve, lütfen.","lit":"lait-sans · [un] · café · s'il-vous-plaît"},{"fr":"Le simit au sésame est délicieux.","tgt":"Susamlı simit çok lezzetli.","lit":"sésame-avec · simit · très · savoureux"},{"fr":"Le matin, un simit et un thé.","tgt":"Sabah, bir simit ve bir çay.","lit":"matin · un · simit · et · un · thé"},{"fr":"Le petit-déjeuner turc est copieux.","tgt":"Türk kahvaltısı çok zengin.","lit":"turc · petit-déjeuner-son · très · riche"}],"tip":{"title":"L'harmonie vocalique : la langue qui chante juste","example":"Un simit au fromage, s'il vous plaît. — <b>Peynirli</b> simit, lütfen.","body":"Le turc colle des petites terminaisons à la fin des mots, et ces terminaisons changent de voyelle pour rester en accord avec le mot. C'est ce qu'on appelle l'harmonie vocalique. Prenons la terminaison qui veut dire « avec » : après « peynir », le fromage, on dit « peynirli », au fromage. Mais après « susam », le sésame, on dit « susamlı », avec un son plus sourd, car la voyelle du mot est un « a ». De même, « sans » se dit « şekersiz », sans sucre, mais « sütsüz », sans lait, avec un « u » arrondi comme dans « süt ». Les voyelles claires appellent des voyelles claires, les voyelles sourdes appellent des voyelles sourdes. Astuce : ne réfléchissez pas trop, écoutez la musique du mot et laissez la bouche garder la même position du début à la fin.","lit":"fromage-avec · simit · s'il-vous-plaît","say":{"peynir":"peynir","peynirli":"peynirli","susam":"susam","susamlı":"susamlı","şekersiz":"şekersiz","sütsüz":"sütsüz","süt":"süt"}}},{"title":"Bonjour aux voisins","phrases":[{"fr":"Bonjour, madame Ayşe.","tgt":"Merhaba, Ayşe Hanım.","lit":"bonjour · Ayşe · madame"},{"fr":"Comment allez-vous ?","tgt":"Nasılsınız?","lit":"comment-vous-êtes"},{"fr":"Je vais bien, merci.","tgt":"İyiyim, teşekkürler.","lit":"bien-je-suis · merci"},{"fr":"Et vous, comment allez-vous ?","tgt":"Siz nasılsınız?","lit":"vous · comment-vous-êtes"},{"fr":"Bonjour à tout le monde !","tgt":"Herkese günaydın!","lit":"tout-le-monde-à · bonjour-du-matin"},{"fr":"Bonsoir, chers voisins !","tgt":"İyi akşamlar, komşular!","lit":"bon · soirs · voisins"},{"fr":"Très bien, merci beaucoup.","tgt":"Çok iyiyim, çok teşekkürler.","lit":"très · bien-je-suis · très · merci"},{"fr":"Comment va votre famille ?","tgt":"Aileniz nasıl?","lit":"famille-votre · comment"},{"fr":"Au revoir, bonne journée !","tgt":"Hoşça kalın, iyi günler!","lit":"agréablement · restez · bons · jours"},{"fr":"Bonne nuit à vous.","tgt":"Size iyi geceler.","lit":"vous-à · bonnes · nuits"}],"tip":{"title":"« Merhaba » et « nasılsınız » : saluer","example":"Comment allez-vous ? — <b>Nasılsınız</b>?","body":"Pour saluer quelqu'un en Turquie, le mot passe-partout est « merhaba », bonjour, qu'on peut dire à toute heure. Le matin, on entend aussi « günaydın », qui veut dire bonne matinée. Ensuite vient la question « nasılsınız », comment allez-vous. Décomposons-la : « nasıl » veut dire comment, et « sınız » veut dire vous êtes, collé à la fin. Mot à mot, c'est donc comment-vous-êtes, en un seul mot. Pour répondre, on dit « iyiyim », je vais bien, puis « teşekkürler », merci. Le soir, on dit « iyi akşamlar », bonsoir, et pour partir, « hoşça kalın », au revoir. Astuce : « merhaba » se prononce avec un petit souffle sur le « h », comme un soupir de contentement.","lit":"comment-vous-êtes","say":{"Merhaba":"Merhaba","nasılsınız":"nasılsınız","merhaba":"merhaba","günaydın":"günaydın","nasıl":"nasıl","iyiyim":"iyiyim","teşekkürler":"teşekkürler","iyi akşamlar":"iyi akşamlar","hoşça kalın":"hoşça kalın"}}},{"title":"Les collègues de bureau","phrases":[{"fr":"Moi, je suis étudiant.","tgt":"Ben öğrenciyim.","lit":"moi · étudiant-je-suis"},{"fr":"Toi, tu es vraiment gentil.","tgt":"Sen çok naziksin.","lit":"toi · très · gentil-tu-es"},{"fr":"Lui, il est ingénieur.","tgt":"O mühendis.","lit":"lui · ingénieur"},{"fr":"Elle est à la maison aujourd'hui.","tgt":"O bugün evde.","lit":"elle · aujourd'hui · maison-à"},{"fr":"Nous sommes collègues.","tgt":"Biz meslektaşız.","lit":"nous · collègue-nous-sommes"},{"fr":"Vous êtes très aimable.","tgt":"Siz çok naziksiniz.","lit":"vous · très · gentil-vous-êtes"},{"fr":"Ils sont au bureau.","tgt":"Onlar ofiste.","lit":"eux · bureau-à"},{"fr":"Je suis fatigué aujourd'hui.","tgt":"Bugün yorgunum.","lit":"aujourd'hui · fatigué-je-suis"},{"fr":"Il est très occupé ce matin.","tgt":"O bu sabah çok meşgul.","lit":"lui · ce · matin · très · occupé"},{"fr":"Nous sommes contents.","tgt":"Mutluyuz.","lit":"heureux-nous-sommes"}],"tip":{"title":"« Ben », « sen », « o » : les pronoms, souvent sous-entendus","example":"Toi, tu es vraiment gentil. — <b>Sen</b> çok naziksin.","body":"Les pronoms turcs sont courts et faciles : « ben », moi, « sen », toi, « o », lui ou elle, « biz », nous, « siz », vous, et « onlar », eux. Remarquez que « o » sert à la fois pour il et pour elle, sans aucune différence. Mais le plus étonnant, c'est qu'on les dit rarement ! La fin du mot indique déjà qui parle. Dans « yorgunum », je suis fatigué, la terminaison « um » veut dire je suis, donc « ben » n'est pas nécessaire. On ajoute le pronom seulement pour insister, un peu comme quand on dit en français « moi, je suis fatigué ». Autre exemple : « mutluyuz », nous sommes contents, se suffit à lui-même. Astuce : quand vous parlez, commencez sans pronom, et gardez-le pour les moments où vous voulez souligner la personne.","lit":"toi · très · gentil-tu-es","say":{"Ben":"Ben","sen":"sen","o":"o","ben":"ben","biz":"biz","siz":"siz","onlar":"onlar","yorgunum":"yorgunum","mutluyuz":"mutluyuz"}}},{"title":"Se présenter","phrases":[{"fr":"Moi, je suis française.","tgt":"Ben Fransızım.","lit":"moi · Française-je-suis"},{"fr":"Je suis de Lyon.","tgt":"Lyonluyum.","lit":"Lyon-de-je-suis"},{"fr":"Je suis enseignant.","tgt":"Öğretmenim.","lit":"enseignant-je-suis"},{"fr":"Vous, vous êtes turc.","tgt":"Siz Türksünüz.","lit":"vous · Turc-vous-êtes"},{"fr":"Je suis nouveau dans le quartier.","tgt":"Mahallede yeniyim.","lit":"quartier-dans · nouveau-je-suis"},{"fr":"Nous sommes français tous les deux.","tgt":"İkimiz de Fransızız.","lit":"deux-de-nous · aussi · Français-nous-sommes"},{"fr":"Je suis très content d'être là.","tgt":"Çok mutluyum.","lit":"très · heureux-je-suis"},{"fr":"Mon mari est turc.","tgt":"Kocam Türk.","lit":"mari-mon · Turc"},{"fr":"Je suis mariée.","tgt":"Evliyim.","lit":"marié-je-suis"},{"fr":"Nous sommes voisins de palier.","tgt":"Kapı komşusuyuz.","lit":"porte · voisin-son-nous-sommes"}],"tip":{"title":"Être en suffixe : « Fransızım », je suis français","example":"Moi, je suis française. — Ben <b>Fransızım</b>.","body":"En turc, le verbe être n'est pas un mot séparé : c'est une petite terminaison collée à la fin. « Fransız » veut dire français, et « Fransızım » veut dire je suis français. Le « ım » final, c'est le je suis. Pour nous sommes, on ajoute « ız » : « Fransızız », nous sommes français. Et pour vous êtes, on ajoute « sınız » : « Türksünüz », vous êtes turc. Ces terminaisons suivent l'harmonie des voyelles : on dit « öğretmenim », je suis enseignant, mais « mutluyum », je suis content. À la troisième personne, rien du tout : « kocam Türk », mon mari est turc. Astuce : pensez à ces terminaisons comme à une petite signature que vous ajoutez à la fin du mot pour dire qui vous êtes.","lit":"moi · Française-je-suis","say":{"Fransızım":"Fransızım","Fransız":"Fransız","Fransızız":"Fransızız","Türksünüz":"Türksünüz","öğretmenim":"öğretmenim","mutluyum":"mutluyum","kocam Türk":"kocam Türk"}}},{"title":"Au café du coin","phrases":[{"fr":"Je ne suis pas turc.","tgt":"Ben Türk değilim.","lit":"moi · Turc · [ne… pas]-je-suis"},{"fr":"Ce n'est pas mon verre.","tgt":"Bu benim bardağım değil.","lit":"ceci · de-moi · verre-mon · [ne… pas]"},{"fr":"Le thé n'est pas chaud.","tgt":"Çay sıcak değil.","lit":"thé · chaud · [ne… pas]"},{"fr":"Je ne suis pas fatigué du tout.","tgt":"Hiç yorgun değilim.","lit":"du-tout · fatigué · [ne… pas]-je-suis"},{"fr":"Ce n'est pas cher ici.","tgt":"Burası pahalı değil.","lit":"cet-endroit · cher · [ne… pas]"},{"fr":"Nous ne sommes pas d'ici.","tgt":"Biz buralı değiliz.","lit":"nous · d'ici · [ne… pas]-nous-sommes"},{"fr":"Le café n'est pas loin.","tgt":"Kafe uzak değil.","lit":"café · loin · [ne… pas]"},{"fr":"Le thé est bon, pas trop fort.","tgt":"Çay güzel, çok koyu değil.","lit":"thé · bon · très · foncé · [ne… pas]"},{"fr":"Le serveur est très chaleureux.","tgt":"Garson çok sıcakkanlı.","lit":"serveur · très · chaleureux"},{"fr":"Ce n'est pas un problème.","tgt":"Sorun değil.","lit":"problème · [ne… pas]"}],"tip":{"title":"« Değil » : ne pas être","example":"Je ne suis pas turc. — Ben Türk <b>değilim</b>.","body":"Pour dire « ne pas être », le turc utilise un seul petit mot : « değil ». Il se place après l'adjectif ou le nom, tout à la fin de la phrase. « Çay sıcak », le thé est chaud, devient « çay sıcak değil », le thé n'est pas chaud. Et c'est sur « değil » qu'on colle la terminaison de la personne. Ainsi, « değilim » veut dire je ne suis pas, et « değiliz », nous ne sommes pas. Décomposons « Ben Türk değilim » : moi, turc, pas-je-suis. Une expression très utile au quotidien est « sorun değil », ce n'est pas un problème, qu'on entend partout à Istanbul. Astuce : « değil » se prononce presque « dé-il », le « ğ » est à peine audible, il allonge juste la voyelle.","lit":"moi · Turc · [ne… pas]-je-suis","say":{"Değil":"Değil","değil":"değil","Çay sıcak":"Çay sıcak","çay sıcak değil":"çay sıcak değil","değilim":"değilim","değiliz":"değiliz","Ben Türk değilim":"Ben Türk değilim","sorun değil":"sorun değil"}}},{"title":"Sur le ferry","phrases":[{"fr":"Je monte sur le ferry.","tgt":"Vapura biniyorum.","lit":"ferry-à · monte-je"},{"fr":"Je lis le journal du matin.","tgt":"Sabah gazetesini okuyorum.","lit":"matin · journal-son-le · lis-je"},{"fr":"Ahmet boit du thé.","tgt":"Ahmet çay içiyor.","lit":"Ahmet · thé · boit"},{"fr":"Je regarde la mer.","tgt":"Denize bakıyorum.","lit":"mer-vers · regarde-je"},{"fr":"Le ferry traverse le Bosphore.","tgt":"Vapur Boğaz'ı geçiyor.","lit":"ferry · Bosphore-le · traverse"},{"fr":"Je vais à Eminönü.","tgt":"Eminönü'ne gidiyorum.","lit":"Eminönü-à · vais-je"},{"fr":"Je lance du simit aux mouettes.","tgt":"Martılara simit atıyorum.","lit":"mouettes-aux · simit · lance-je"},{"fr":"Le ferry part à huit heures.","tgt":"Vapur saat sekizde kalkıyor.","lit":"ferry · heure · huit-à · part"},{"fr":"J'achète un thé à bord.","tgt":"Vapurda çay alıyorum.","lit":"ferry-sur · thé · achète-je"},{"fr":"La traversée dure vingt minutes.","tgt":"Yolculuk yirmi dakika sürüyor.","lit":"trajet · vingt · minute · dure"}],"tip":{"title":"Le verbe à la fin : sujet, objet, verbe","example":"Ahmet boit du thé. — Ahmet çay <b>içiyor</b>.","body":"En français, on dit sujet, verbe, puis objet : Ahmet boit du thé. En turc, le verbe part toujours à la fin de la phrase : « Ahmet çay içiyor », mot à mot Ahmet thé boit. C'est un peu comme si on gardait l'action pour la chute. Tout ce qui précise la phrase, le lieu, l'heure, l'objet, se place avant le verbe. Par exemple, « denize bakıyorum », je regarde la mer, se dit vers-la-mer je-regarde. Et « vapurda çay alıyorum », j'achète un thé à bord, se dit sur-le-ferry thé j'achète. Au début, cela demande un petit effort, car il faut tenir le verbe en réserve. Astuce : préparez d'abord les noms dans votre tête, puis terminez par le verbe, comme on pose le dernier mot d'une devinette.","lit":"Ahmet · thé · boit","say":{"Ahmet çay içiyor":"Ahmet çay içiyor","denize bakıyorum":"denize bakıyorum","vapurda çay alıyorum":"vapurda çay alıyorum"}}},{"title":"À l'épicerie du quartier","phrases":[{"fr":"Vous avez du pain ?","tgt":"Ekmek var mı?","lit":"pain · il-y-a · [question]"},{"fr":"Le pain est frais ?","tgt":"Ekmek taze mi?","lit":"pain · frais · [question]"},{"fr":"C'est cher, ça ?","tgt":"Pahalı mı?","lit":"cher · [question]"},{"fr":"C'est vous, l'épicier ?","tgt":"Bakkal siz misiniz?","lit":"épicier · vous · [question]-vous-êtes"},{"fr":"Ces tomates sont bonnes ?","tgt":"Bu domatesler iyi mi?","lit":"ces · tomates · bon · [question]"},{"fr":"La boutique est ouverte ?","tgt":"Dükkân açık mı?","lit":"boutique · ouvert · [question]"},{"fr":"Du fromage blanc, s'il vous plaît.","tgt":"Beyaz peynir, lütfen.","lit":"blanc · fromage · s'il-vous-plaît"},{"fr":"Vous êtes français, vous aussi ?","tgt":"Siz de Fransız mısınız?","lit":"vous · aussi · Français · [question]-vous-êtes"},{"fr":"C'est du lait de vache ?","tgt":"İnek sütü mü?","lit":"vache · lait-son · [question]"},{"fr":"Merci, à demain !","tgt":"Teşekkürler, yarın görüşürüz!","lit":"merci · demain · nous-nous-voyons"}],"tip":{"title":"« Mi » : la petite question","example":"C'est cher, ça ? — Pahalı <b>mı</b>?","body":"Pour poser une question fermée en turc, celle à laquelle on répond par oui ou non, il suffit d'ajouter un petit mot : « mi ». Il se place juste après le mot sur lequel porte la question. « Pahalı », cher, devient « pahalı mı », est-ce que c'est cher ? Ce petit mot suit l'harmonie des voyelles, et peut donc sonner « mi », « mı », « mu » ou « mü ». Ainsi, on dit « taze mi », c'est frais ?, mais « sütü mü », c'est du lait ? Si on parle à quelqu'un, on colle la personne dessus : « Fransız mısınız », êtes-vous français ? C'est l'équivalent de notre « est-ce que », mais placé à la fin. Astuce : à l'oral, la voix monte juste avant « mi », sur le mot important, puis redescend doucement.","lit":"cher · [question]","say":{"Mi":"Mi","mi":"mi","Pahalı":"Pahalı","pahalı mı":"pahalı mı","mı":"mı","mu":"mu","mü":"mü","taze mi":"taze mi","sütü mü":"sütü mü","Fransız mısınız":"Fransız mısınız"}}},{"title":"Dans la cuisine","phrases":[{"fr":"Il y a du thé dans la cuisine.","tgt":"Mutfakta çay var.","lit":"cuisine-dans · thé · il-y-a"},{"fr":"Il n'y a pas de lait.","tgt":"Süt yok.","lit":"lait · il-n'y-a-pas"},{"fr":"Il y a des œufs dans le frigo.","tgt":"Buzdolabında yumurta var.","lit":"frigo-son-dans · œuf · il-y-a"},{"fr":"Il n'y a pas du tout de pain.","tgt":"Hiç ekmek yok.","lit":"aucun · pain · il-n'y-a-pas"},{"fr":"Il y a un souci ?","tgt":"Bir sorun mu var?","lit":"un · problème · [question] · il-y-a"},{"fr":"Non, aucun souci.","tgt":"Hayır, sorun yok.","lit":"non · problème · il-n'y-a-pas"},{"fr":"Il y a une épicerie au coin de la rue.","tgt":"Köşede bir bakkal var.","lit":"coin-à · une · épicerie · il-y-a"},{"fr":"Il y a des olives ?","tgt":"Zeytin var mı?","lit":"olive · il-y-a · [question]"},{"fr":"Il n'y a pas de sucre à la maison.","tgt":"Evde şeker yok.","lit":"maison-à · sucre · il-n'y-a-pas"},{"fr":"Il y a du fromage et des tomates.","tgt":"Peynir ve domates var.","lit":"fromage · et · tomate · il-y-a"}],"tip":{"title":"« Var » et « yok » : il y a, il n'y a pas","example":"Il y a du thé dans la cuisine. — Mutfakta çay <b>var</b>.","body":"Voici deux des mots les plus utiles du turc : « var », il y a, et « yok », il n'y a pas. Ils se placent à la fin de la phrase, comme un verbe. « Çay var », il y a du thé, et « süt yok », il n'y a pas de lait. Décomposons « mutfakta çay var » : dans-la-cuisine, thé, il-y-a. On n'a besoin ni d'article, ni de « du » ou « des ». Pour poser la question, on ajoute « mı » : « zeytin var mı », il y a des olives ? C'est d'ailleurs la façon la plus simple de demander quelque chose dans une boutique. Et la réponse la plus rassurante du pays est « sorun yok », pas de souci. Astuce : « var » est court et ouvert comme un oui, « yok » est court et fermé comme une porte qui se referme.","lit":"cuisine-dans · thé · il-y-a","say":{"Var":"Var","yok":"yok","var":"var","Çay var":"Çay var","süt yok":"süt yok","mutfakta çay var":"mutfakta çay var","mı":"mı","zeytin var mı":"zeytin var mı","sorun yok":"sorun yok"}}},{"title":"Au marché de Kadıköy","phrases":[{"fr":"Pardon, c'est quoi, ça ?","tgt":"Pardon, bu ne?","lit":"pardon · ceci · quoi"},{"fr":"Celui-ci est très frais.","tgt":"Bu çok taze.","lit":"ceci · très · frais"},{"fr":"Et ce melon-là ?","tgt":"Ya şu kavun?","lit":"et · ce-là · melon"},{"fr":"Cette pomme est sucrée.","tgt":"Bu elma tatlı.","lit":"cette · pomme · sucré"},{"fr":"Ce poisson-là est cher.","tgt":"Şu balık pahalı.","lit":"ce-là · poisson · cher"},{"fr":"La boutique là-bas est fermée.","tgt":"O dükkân kapalı.","lit":"ce-là-bas · boutique · fermé"},{"fr":"Je prends celle-ci.","tgt":"Bunu alıyorum.","lit":"ceci-le · prends-je"},{"fr":"Donnez-moi celles-là, s'il vous plaît.","tgt":"Şunları verin, lütfen.","lit":"cela-les · donnez · s'il-vous-plaît"},{"fr":"Ces figues sont magnifiques.","tgt":"Bu incirler harika.","lit":"ces · figues · magnifique"},{"fr":"Le marché du mardi est bondé.","tgt":"Salı pazarı çok kalabalık.","lit":"mardi · marché-son · très · bondé"}],"tip":{"title":"« Bu », « şu », « o » : ceci et cela","example":"Ce poisson-là est cher. — <b>Şu</b> balık pahalı.","body":"Le turc a trois mots pour montrer les choses, selon leur distance. « Bu » désigne ce qui est tout près de vous, ceci. « Şu » désigne ce qui est un peu plus loin, ce qu'on montre du doigt, cela. Et « o » désigne ce qui est loin, là-bas, et c'est aussi le mot pour il ou elle. On les place devant le nom, sans rien changer : « bu elma », cette pomme, « şu balık », ce poisson-là. Ils peuvent aussi être seuls : « bu ne », c'est quoi, ça ? Au marché, c'est parfait pour acheter sans connaître le nom des produits : on montre et on dit « bunu alıyorum », je prends celui-ci. Astuce : imaginez trois pas, « bu » sous votre main, « şu » à portée du doigt, « o » au bout de la rue.","lit":"ce-là · poisson · cher","say":{"Bu":"Bu","şu":"şu","o":"o","Şu":"Şu","bu elma":"bu elma","şu balık":"şu balık","bu ne":"bu ne","bunu alıyorum":"bunu alıyorum","bu":"bu"}}},{"title":"Compter ses courses","phrases":[{"fr":"Deux simits, s'il vous plaît.","tgt":"İki simit, lütfen.","lit":"deux · simit · s'il-vous-plaît"},{"fr":"Trois verres de thé.","tgt":"Üç bardak çay.","lit":"trois · verre · thé"},{"fr":"Je voudrais quatre tomates.","tgt":"Dört domates istiyorum.","lit":"quatre · tomate · veux-je"},{"fr":"Cinq pommes, s'il vous plaît.","tgt":"Beş elma, lütfen.","lit":"cinq · pomme · s'il-vous-plaît"},{"fr":"Six œufs, ça suffit.","tgt":"Altı yumurta yeter.","lit":"six · œuf · suffit"},{"fr":"Une semaine compte sept jours.","tgt":"Bir haftada yedi gün var.","lit":"une · semaine-dans · sept · jour · il-y-a"},{"fr":"Nous sommes huit à table.","tgt":"Masada sekiz kişiyiz.","lit":"table-à · huit · personne-nous-sommes"},{"fr":"Mon fils a neuf ans.","tgt":"Oğlum dokuz yaşında.","lit":"fils-mon · neuf · âge-son-dans"},{"fr":"Dix minutes à pied.","tgt":"Yürüyerek on dakika.","lit":"en-marchant · dix · minute"},{"fr":"Un, deux, trois, c'est parti !","tgt":"Bir, iki, üç, haydi!","lit":"un · deux · trois · allez"}],"tip":{"title":"Compter de un à dix : « bir, iki, üç »","example":"Trois verres de thé. — <b>Üç</b> bardak çay.","body":"Les nombres turcs de un à dix sont courts et réguliers : « bir », un, « iki », deux, « üç », trois, « dört », quatre, « beş », cinq, « altı », six, « yedi », sept, « sekiz », huit, « dokuz », neuf, et « on », dix. Une excellente nouvelle : après un nombre, le nom reste au singulier. On dit « üç bardak çay », mot à mot trois verre thé, et jamais trois verres. C'est logique : le nombre dit déjà qu'il y en a plusieurs. De même, « iki simit », deux simits, et « beş elma », cinq pommes. Le mot « bir » sert aussi d'article, un ou une. Astuce : récitez les nombres par paires rythmées, « bir iki », « üç dört », « beş altı », comme une petite comptine en montant l'escalier de votre immeuble.","lit":"trois · verre · thé","say":{"bir, iki, üç":"bir, iki, üç","bir":"bir","iki":"iki","üç":"üç","dört":"dört","beş":"beş","altı":"altı","yedi":"yedi","sekiz":"sekiz","dokuz":"dokuz","on":"on","üç bardak çay":"üç bardak çay","iki simit":"iki simit","beş elma":"beş elma","bir iki":"bir iki","üç dört":"üç dört","beş altı":"beş altı"}}},{"title":"Les chats d'Istanbul","phrases":[{"fr":"Les enfants jouent dans la rue.","tgt":"Çocuklar sokakta oynuyor.","lit":"enfant-s · rue-dans · joue"},{"fr":"Les voisins sont très gentils.","tgt":"Komşular çok nazik.","lit":"voisin-s · très · gentil"},{"fr":"Les chats dorment au soleil.","tgt":"Kediler güneşte uyuyor.","lit":"chat-s · soleil-au · dort"},{"fr":"Les rues de Kadıköy sont animées.","tgt":"Kadıköy'ün sokakları canlı.","lit":"Kadıköy-de · rue-s-ses · vivant"},{"fr":"Les livres sont sur la table.","tgt":"Kitaplar masada.","lit":"livre-s · table-sur"},{"fr":"Toutes les fenêtres sont ouvertes.","tgt":"Bütün pencereler açık.","lit":"toutes · fenêtre-s · ouvert"},{"fr":"Les maisons sont très colorées.","tgt":"Evler rengârenk.","lit":"maison-s · coloré"},{"fr":"Les simits sont encore chauds.","tgt":"Simitler hâlâ sıcak.","lit":"simit-s · encore · chaud"},{"fr":"Le matin, les ferries sont pleins.","tgt":"Sabahları vapurlar dolu.","lit":"matin-s-les · ferry-s · plein"},{"fr":"Il y a beaucoup de chats ici.","tgt":"Burada çok kedi var.","lit":"ici · beaucoup · chat · il-y-a"}],"tip":{"title":"Le pluriel en « -ler » et « -lar »","example":"Les chats dorment au soleil. — <b>Kediler</b> güneşte uyuyor.","body":"Pour mettre un mot au pluriel en turc, on ajoute une terminaison qui sonne « ler » ou « lar ». Le choix dépend de l'harmonie des voyelles. Si le mot a des voyelles claires, comme « kedi », le chat, on dit « kediler », les chats. Si le mot a des voyelles sourdes, comme « kitap », le livre, on dit « kitaplar », les livres. De même, « ev » donne « evler », les maisons, et « çocuk » donne « çocuklar », les enfants. Mais attention : après « çok », beaucoup, ou après un nombre, on garde le singulier. On dit donc « çok kedi », beaucoup de chats, et non beaucoup de chat-s. Astuce : à Istanbul, les chats sont partout, alors répétez « kedi, kediler » chaque fois que vous en croisez un, et le pluriel viendra tout seul.","lit":"chat-s · soleil-au · dort","say":{"kedi":"kedi","kediler":"kediler","kitap":"kitap","kitaplar":"kitaplar","ev":"ev","evler":"evler","çocuk":"çocuk","çocuklar":"çocuklar","çok":"çok","çok kedi":"çok kedi","kedi, kediler":"kedi, kediler"}}},{"title":"Où est la clé ?","phrases":[{"fr":"Où est la clé ?","tgt":"Anahtar nerede?","lit":"clé · où"},{"fr":"La clé est sur la table basse.","tgt":"Anahtar sehpada.","lit":"clé · table-basse-sur"},{"fr":"Où êtes-vous en ce moment ?","tgt":"Şu an neredesiniz?","lit":"ce · moment · où-vous-êtes"},{"fr":"Je suis à la maison.","tgt":"Evdeyim.","lit":"maison-à-je-suis"},{"fr":"Mon frère est à Kadıköy.","tgt":"Kardeşim Kadıköy'de.","lit":"frère-mon · Kadıköy-à"},{"fr":"Où se trouve l'arrêt de bus ?","tgt":"Otobüs durağı nerede?","lit":"bus · arrêt-son · où"},{"fr":"Le chat est dans le jardin.","tgt":"Kedi bahçede.","lit":"chat · jardin-dans"},{"fr":"Nous sommes sur le ferry.","tgt":"Vapurdayız.","lit":"ferry-sur-nous-sommes"},{"fr":"Le téléphone est dans le sac.","tgt":"Telefon çantada.","lit":"téléphone · sac-dans"},{"fr":"Où sont les toilettes, s'il vous plaît ?","tgt":"Tuvalet nerede, lütfen?","lit":"toilette · où · s'il-vous-plaît"}],"tip":{"title":"« Nerede » et le suffixe « -de » : où, à, dans","example":"Je suis à la maison. — <b>Evdeyim</b>.","body":"Pour demander où se trouve quelque chose, on dit « nerede », qui veut dire où, et on le place à la fin : « anahtar nerede », où est la clé ? Pour répondre, le turc n'utilise pas de petits mots comme à, dans ou sur. Il colle simplement « de » ou « da » à la fin du nom. « Masa », la table, devient « masada », sur la table. « Ev », la maison, devient « evde », à la maison. Et on peut même ajouter la personne derrière : « evdeyim », mot à mot maison-à-je-suis, donc je suis à la maison. Après certaines consonnes dures, le son devient « te » ou « ta », comme dans « ofiste », au bureau. Astuce : pensez à « de » comme à une petite épingle qui fixe un objet à un endroit.","lit":"maison-à-je-suis","say":{"Nerede":"Nerede","nerede":"nerede","anahtar nerede":"anahtar nerede","Masa":"Masa","masada":"masada","Ev":"Ev","evde":"evde","evdeyim":"evdeyim","ofiste":"ofiste"}}},{"title":"La routine du matin","phrases":[{"fr":"Je me réveille à sept heures.","tgt":"Saat yedide uyanıyorum.","lit":"heure · sept-à · réveille-je"},{"fr":"Je bois un thé.","tgt":"Çay içiyorum.","lit":"thé · bois-je"},{"fr":"Je mange un simit au petit-déjeuner.","tgt":"Kahvaltıda simit yiyorum.","lit":"petit-déjeuner-au · simit · mange-je"},{"fr":"Je prends vite une douche.","tgt":"Hızlıca duş alıyorum.","lit":"rapidement · douche · prends-je"},{"fr":"Ensuite, je m'habille.","tgt":"Sonra giyiniyorum.","lit":"ensuite · m'habille-je"},{"fr":"Ma femme lit les nouvelles.","tgt":"Eşim haberleri okuyor.","lit":"épouse-ma · nouvelles-les · lit"},{"fr":"Les petits dorment encore.","tgt":"Küçükler hâlâ uyuyor.","lit":"petit-s · encore · dort"},{"fr":"Qu'est-ce que vous faites ?","tgt":"Ne yapıyorsunuz?","lit":"quoi · faites-vous"},{"fr":"Je pars au travail.","tgt":"İşe gidiyorum.","lit":"travail-au · vais-je"},{"fr":"Nous attendons le ferry.","tgt":"Vapuru bekliyoruz.","lit":"ferry-le · attendons-nous"}],"tip":{"title":"Le présent en « -iyor » : ce que je fais","example":"Je bois un thé. — Çay <b>içiyorum</b>.","body":"Pour dire ce que l'on fait en ce moment, ou ce que l'on fait d'habitude, le turc utilise une terminaison qui sonne « iyor ». On part du verbe, par exemple « iç », boire, on ajoute « iyor », puis la personne : « içiyorum », je bois. Décomposons : « iç », boire, « iyor », en train de, et « um », je. Avec « gel », venir, on dit « geliyorum », je viens, et avec « oku », lire, on dit « okuyorum », je lis. Pour nous, on termine par « uz » : « bekliyoruz », nous attendons. Pour il ou elle, on s'arrête juste après « iyor » : « okuyor », elle lit. Bonne nouvelle, ce temps est très régulier, presque sans exception. Astuce : le son « yor » revient sans cesse dans les conversations, comme un petit tic-tac qui dit maintenant.","lit":"thé · bois-je","say":{"iç":"iç","içiyorum":"içiyorum","gel":"gel","geliyorum":"geliyorum","oku":"oku","okuyorum":"okuyorum","bekliyoruz":"bekliyoruz","okuyor":"okuyor"}}},{"title":"Un jour de repos","phrases":[{"fr":"Je ne viens pas ce soir.","tgt":"Bu akşam gelmiyorum.","lit":"ce · soir · venir-[ne… pas]-je"},{"fr":"Je ne travaille pas le dimanche.","tgt":"Pazar günleri çalışmıyorum.","lit":"dimanche · jour-s-les · travailler-[ne… pas]-je"},{"fr":"Il ne pleut pas.","tgt":"Yağmur yağmıyor.","lit":"pluie · tomber-[ne… pas]"},{"fr":"Je ne bois pas de café.","tgt":"Kahve içmiyorum.","lit":"café · boire-[ne… pas]-je"},{"fr":"Les enfants ne dorment pas.","tgt":"Çocuklar uyumuyor.","lit":"enfant-s · dormir-[ne… pas]"},{"fr":"Désolé, je ne comprends pas.","tgt":"Kusura bakmayın, anlamıyorum.","lit":"faute-à · ne-regardez-pas · comprendre-[ne… pas]-je"},{"fr":"Le ferry ne part pas.","tgt":"Vapur kalkmıyor.","lit":"ferry · partir-[ne… pas]"},{"fr":"Nous ne sortons pas ce soir.","tgt":"Bu akşam dışarı çıkmıyoruz.","lit":"ce · soir · dehors · sortir-[ne… pas]-nous"},{"fr":"Vous ne mangez pas ?","tgt":"Yemiyor musunuz?","lit":"manger-[ne… pas] · [question]-vous"},{"fr":"Je reste à la maison.","tgt":"Evde kalıyorum.","lit":"maison-à · reste-je"}],"tip":{"title":"« Gelmiyorum » : la négation du verbe","example":"Je ne viens pas ce soir. — Bu akşam <b>gelmiyorum</b>.","body":"En français, la négation entoure le verbe avec ne et pas. En turc, elle se glisse à l'intérieur du verbe, sous la forme d'un petit son « m ». « Geliyorum », je viens, devient « gelmiyorum », je ne viens pas. Décomposons : « gel », venir, « mi », ne pas, puis « yor », en train de, et enfin « um », je. Avec « çalış », travailler, on obtient « çalışmıyorum », je ne travaille pas. Et avec « anla », comprendre, on obtient « anlamıyorum », je ne comprends pas, une phrase précieuse pour un débutant. La voyelle du petit « mi » suit l'harmonie, d'où « uyumuyor », il ne dort pas. Astuce : écoutez le « m » caché au milieu du verbe, c'est lui qui dit non.","lit":"ce · soir · venir-[ne… pas]-je","say":{"Gelmiyorum":"Gelmiyorum","Geliyorum":"Geliyorum","gelmiyorum":"gelmiyorum","gel":"gel","çalış":"çalış","çalışmıyorum":"çalışmıyorum","anla":"anla","anlamıyorum":"anlamıyorum","uyumuyor":"uyumuyor"}}},{"title":"Une nouvelle collègue","phrases":[{"fr":"Qui est-ce ?","tgt":"Bu kim?","lit":"ceci · qui"},{"fr":"Que buvez-vous ?","tgt":"Ne içiyorsunuz?","lit":"quoi · buvez-vous"},{"fr":"Quel est votre nom ?","tgt":"Adınız ne?","lit":"nom-votre · quoi"},{"fr":"Comment est le nouveau bureau ?","tgt":"Yeni ofis nasıl?","lit":"nouveau · bureau · comment"},{"fr":"Combien de collègues avez-vous ?","tgt":"Kaç iş arkadaşınız var?","lit":"combien · travail · ami-votre · il-y-a"},{"fr":"Ça fait combien de livres ?","tgt":"Kaç lira?","lit":"combien · livre"},{"fr":"Qui est votre chef ?","tgt":"Müdürünüz kim?","lit":"directeur-votre · qui"},{"fr":"Que faites-vous ce soir ?","tgt":"Bu akşam ne yapıyorsunuz?","lit":"ce · soir · quoi · faites-vous"},{"fr":"Comment allez-vous au travail ?","tgt":"İşe nasıl gidiyorsunuz?","lit":"travail-au · comment · allez-vous"},{"fr":"Quel âge avez-vous ?","tgt":"Kaç yaşındasınız?","lit":"combien · âge-son-dans-vous-êtes"}],"tip":{"title":"Les mots interrogatifs : « ne », « kim », « nasıl », « kaç »","example":"Qui est votre chef ? — Müdürünüz <b>kim</b>?","body":"Voici quatre petits mots pour poser presque toutes les questions : « ne », quoi, « kim », qui, « nasıl », comment, et « kaç », combien. La grande différence avec le français, c'est leur place : ils ne vont pas au début, mais à l'endroit où se trouverait la réponse. « Müdürünüz kim », mot à mot votre-chef qui, veut dire qui est votre chef. Et la réponse prendra la même place : votre chef, c'est Ayşe. De même, « adınız ne », votre nom quoi, veut dire comment vous appelez-vous. Avec un verbe, le mot interrogatif se place juste avant lui : « ne içiyorsunuz », que buvez-vous ? Et « kaç lira », combien de livres, vous servira dans chaque boutique. Astuce : construisez d'abord la réponse dans votre tête, puis remplacez le mot inconnu par le mot interrogatif.","lit":"directeur-votre · qui","say":{"ne":"ne","kim":"kim","nasıl":"nasıl","kaç":"kaç","Müdürünüz kim":"Müdürünüz kim","adınız ne":"adınız ne","ne içiyorsunuz":"ne içiyorsunuz","kaç lira":"kaç lira"}}},{"title":"Les horaires du ferry","phrases":[{"fr":"Il est quelle heure maintenant ?","tgt":"Şu an saat kaç?","lit":"ce · moment · heure · combien"},{"fr":"Il est exactement huit heures.","tgt":"Saat tam sekiz.","lit":"heure · pile · huit"},{"fr":"Il est seulement neuf heures et demie.","tgt":"Saat daha dokuz buçuk.","lit":"heure · encore · neuf · demi"},{"fr":"À quelle heure part le ferry ?","tgt":"Vapur saat kaçta kalkıyor?","lit":"ferry · heure · combien-à · part"},{"fr":"Le ferry part à dix heures.","tgt":"Vapur saat onda kalkıyor.","lit":"ferry · heure · dix-à · part"},{"fr":"Au bureau, je commence à neuf heures.","tgt":"Ofiste saat dokuzda başlıyorum.","lit":"bureau-au · heure · neuf-à · commence-je"},{"fr":"Il est déjà midi.","tgt":"Saat on iki oldu bile.","lit":"heure · dix · deux · devenu-[passé] · même"},{"fr":"Il est trois heures et quart.","tgt":"Saat üçü çeyrek geçiyor.","lit":"heure · trois-le · quart · passe"},{"fr":"Je rentre à la maison à six heures.","tgt":"Saat altıda eve dönüyorum.","lit":"heure · six-à · maison-à · rentre-je"},{"fr":"On se retrouve à l'embarcadère à sept heures ?","tgt":"Saat yedide iskelede buluşalım mı?","lit":"heure · sept-à · embarcadère-à · retrouvons-nous · [question]"}],"tip":{"title":"« Saat kaç ? » : demander et dire l'heure","example":"Il est quelle heure maintenant ? — Şu an <b>saat kaç</b>?","body":"Pour demander l'heure, on dit simplement « saat kaç », mot à mot heure combien. C'est court, et tout le monde le comprend. Pour répondre, on garde « saat » et on ajoute le nombre : « saat sekiz », il est huit heures. Pour la demie, on ajoute « buçuk » : « saat dokuz buçuk », neuf heures et demie. Pour dire à quelle heure, on colle « de » ou « da » au nombre, le même suffixe que pour un lieu : « saat onda », à dix heures, ou « saat yedide », à sept heures. Et la question devient « saat kaçta », à quelle heure ? Le quart se dit « çeyrek », un mot qu'on retrouve dans « üçü çeyrek geçiyor », trois heures et quart. Astuce : entraînez-vous chaque matin en regardant l'horloge et en disant l'heure à voix haute.","lit":"ce · moment · heure · combien","say":{"Saat kaç ?":"Saat kaç?","saat kaç":"saat kaç","saat":"saat","saat sekiz":"saat sekiz","buçuk":"buçuk","saat dokuz buçuk":"saat dokuz buçuk","saat onda":"saat onda","saat yedide":"saat yedide","saat kaçta":"saat kaçta","çeyrek":"çeyrek","üçü çeyrek geçiyor":"üçü çeyrek geçiyor"}}},{"title":"La famille et la maison","phrases":[{"fr":"J'ai un chat tigré.","tgt":"Tekir bir kedim var.","lit":"tigré · [un] · chat-mon · il-y-a"},{"fr":"J'ai deux enfants.","tgt":"İki çocuğum var.","lit":"deux · enfant-mon · il-y-a"},{"fr":"Avez-vous un chat ?","tgt":"Kediniz var mı?","lit":"chat-votre · il-y-a · [question]"},{"fr":"Je n'ai pas le temps ce matin.","tgt":"Bu sabah vaktim yok.","lit":"ce · matin · temps-mon · il-n'y-a-pas"},{"fr":"Nous avons un petit balcon.","tgt":"Küçük bir balkonumuz var.","lit":"petit · [un] · balcon-notre · il-y-a"},{"fr":"Mon frère a un bateau.","tgt":"Kardeşimin bir teknesi var.","lit":"frère-mon-de · un · bateau-son · il-y-a"},{"fr":"J'ai une petite question.","tgt":"Küçük bir sorum var.","lit":"petite · [une] · question-ma · il-y-a"},{"fr":"Avez-vous des frères et sœurs ?","tgt":"Kardeşiniz var mı?","lit":"frère-ou-sœur-votre · il-y-a · [question]"},{"fr":"Je n'ai pas d'argent sur moi.","tgt":"Üstümde param yok.","lit":"dessus-mon-sur · argent-mon · il-n'y-a-pas"},{"fr":"J'ai un rendez-vous demain.","tgt":"Yarın bir randevum var.","lit":"demain · un · rendez-vous-mon · il-y-a"}],"tip":{"title":"« Kedim var » : avoir, avec le possessif","example":"J'ai un chat tigré. — Tekir bir <b>kedim var</b>.","body":"Surprise : le turc n'a pas de verbe avoir ! Pour dire j'ai un chat, on dit en fait « il y a mon chat ». On prend « kedi », le chat, on ajoute « m », qui veut dire mon ou ma, et on obtient « kedim », mon chat. Puis on ajoute « var », il y a : « kedim var », j'ai un chat. Pour je n'ai pas, on remplace simplement « var » par « yok » : « param yok », je n'ai pas d'argent. Avec vous, la terminaison devient « niz » ou « iniz » : « kediniz var mı », avez-vous un chat ? Et avec nous, on dit « balkonumuz var », nous avons un balcon. Astuce : chaque fois que vous voulez dire j'ai, pensez à « il y a mon », et la phrase turque se construit toute seule.","lit":"tigré · [un] · chat-mon · il-y-a","say":{"Kedim var":"Kedim var","kedi":"kedi","kedim":"kedim","var":"var","kedim var":"kedim var","yok":"yok","param yok":"param yok","kediniz var mı":"kediniz var mı","balkonumuz var":"balkonumuz var"}}},{"title":"Une soirée à la maison","phrases":[{"fr":"Je veux un thé bien chaud.","tgt":"Sıcacık bir çay istiyorum.","lit":"tout-chaud · [un] · thé · veux-je"},{"fr":"Je voudrais regarder un film.","tgt":"Film izlemek istiyorum.","lit":"film · regarder · veux-je"},{"fr":"Que voulez-vous manger ?","tgt":"Ne yemek istiyorsunuz?","lit":"quoi · manger · voulez-vous"},{"fr":"Je voudrais une soupe de lentilles.","tgt":"Mercimek çorbası istiyorum.","lit":"lentille · soupe-sa · veux-je"},{"fr":"Les enfants veulent jouer.","tgt":"Çocuklar oynamak istiyor.","lit":"enfant-s · jouer · veut"},{"fr":"Je ne veux pas sortir ce soir.","tgt":"Bu akşam dışarı çıkmak istemiyorum.","lit":"ce · soir · dehors · sortir · vouloir-[ne… pas]-je"},{"fr":"Voulez-vous un dessert ?","tgt":"Tatlı istiyor musunuz?","lit":"dessert · voulez · [question]-vous"},{"fr":"Je veux juste me reposer.","tgt":"Sadece dinlenmek istiyorum.","lit":"seulement · se-reposer · veux-je"},{"fr":"Nous voulons commander une pide.","tgt":"Bir pide sipariş etmek istiyoruz.","lit":"une · pide · commande · faire · voulons-nous"},{"fr":"Je voudrais un peu de musique.","tgt":"Biraz müzik istiyorum.","lit":"un-peu · musique · veux-je"}],"tip":{"title":"« İstiyorum » : je veux, je voudrais","example":"Je voudrais une soupe de lentilles. — Mercimek çorbası <b>istiyorum</b>.","body":"Le verbe vouloir se dit « iste », et au présent, « istiyorum », je veux. En turc, ce même mot sert aussi pour je voudrais, et ce n'est pas impoli : le ton et un « lütfen », s'il vous plaît, suffisent à adoucir la demande. Comme tous les verbes, il se place à la fin : « çay istiyorum », mot à mot thé je-veux. Pour dire vouloir faire quelque chose, on met le verbe à l'infinitif, qui finit par « mek » ou « mak », juste avant : « film izlemek istiyorum », je voudrais regarder un film. La négation suit la règle habituelle : « istemiyorum », je ne veux pas. Et pour proposer, on dit « istiyor musunuz », voulez-vous ? Astuce : avec « istiyorum » et le nom d'un plat, vous pouvez déjà commander partout en Turquie.","lit":"lentille · soupe-sa · veux-je","say":{"İstiyorum":"İstiyorum","iste":"iste","istiyorum":"istiyorum","lütfen":"lütfen","çay istiyorum":"çay istiyorum","film izlemek istiyorum":"film izlemek istiyorum","istemiyorum":"istemiyorum","istiyor musunuz":"istiyor musunuz"}}},{"title":"Fin du module : un bilan","phrases":[{"fr":"Voilà, ce premier module se termine.","tgt":"İşte, ilk modül bitiyor.","lit":"voilà · premier · module · finit"},{"fr":"Merci beaucoup pour votre patience.","tgt":"Sabrınız için çok teşekkürler.","lit":"patience-votre · pour · très · merci"},{"fr":"Le turc devient plus facile.","tgt":"Türkçe daha kolay oluyor.","lit":"turc · plus · facile · devient"},{"fr":"Pardon, vous pouvez répéter ?","tgt":"Pardon, tekrar eder misiniz?","lit":"pardon · répétition · faire · [question]-vous"},{"fr":"Un peu plus lentement, s'il vous plaît.","tgt":"Biraz daha yavaş, lütfen.","lit":"un-peu · plus · lent · s'il-vous-plaît"},{"fr":"Je vous en prie, c'est normal.","tgt":"Rica ederim, ne demek.","lit":"demande · fais-je · quoi · dire"},{"fr":"Je parle déjà un peu turc.","tgt":"Biraz Türkçe konuşuyorum bile.","lit":"un-peu · turc · parle-je · déjà"},{"fr":"Le prochain module nous emmène en voyage.","tgt":"Sonraki modülde yolculuğa çıkıyoruz.","lit":"prochain · module-dans · voyage-au · partons-nous"},{"fr":"Bravo, continuez comme ça !","tgt":"Bravo, böyle devam edin!","lit":"bravo · ainsi · suite · faites"},{"fr":"Merci et à très bientôt !","tgt":"Teşekkürler, görüşmek üzere!","lit":"merci · se-voir · sur-le-point-de"}],"tip":{"title":"Les formules magiques : « teşekkürler », « lütfen », « pardon », « rica ederim »","example":"Je vous en prie, c'est normal. — <b>Rica ederim</b>, ne demek.","body":"Pour terminer ce module, voici les formules qui ouvrent toutes les portes. « Teşekkürler » veut dire merci, et on peut le renforcer avec « çok », très : « çok teşekkürler », merci beaucoup. « Lütfen » veut dire s'il vous plaît, et se place souvent à la fin de la demande. « Pardon » existe aussi en turc, avec le même sens, pour s'excuser ou attirer l'attention. Quand on vous remercie, répondez « rica ederim », je vous en prie, mot à mot je fais une demande. Les Turcs ajoutent volontiers « ne demek », qui veut dire en somme c'est bien normal. Bravo, vous avez déjà de quoi vivre une journée entière à Istanbul. Astuce : utilisez ces formules sans compter, la politesse est très appréciée en Turquie.","lit":"demande · fais-je · quoi · dire","say":{"teşekkürler":"teşekkürler","lütfen":"lütfen","pardon":"pardon","rica ederim":"rica ederim","Teşekkürler":"Teşekkürler","çok":"çok","çok teşekkürler":"çok teşekkürler","Lütfen":"Lütfen","Pardon":"Pardon","ne demek":"ne demek"}}}]},{"id":2,"name":"En voyage","desc":"Se déplacer, découvrir et gérer les imprévus en Turquie.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Arrivée à l'aéroport d'Izmir","phrases":[{"fr":"Bonjour, tenez, mon passeport.","tgt":"Merhaba, buyurun pasaportum.","lit":"bonjour · [voici] · passeport-mon"},{"fr":"Vous êtes français ?","tgt":"Fransız mısınız?","lit":"Français · [question]-vous-êtes"},{"fr":"Oui, je suis bien français.","tgt":"Evet, Fransızım.","lit":"oui · Français-je-suis"},{"fr":"Je suis ici pour les vacances.","tgt":"Tatil için buradayım.","lit":"vacances · pour · ici-je-suis"},{"fr":"Les valises, elles sont où ?","tgt":"Valizler nerede?","lit":"valise-s · où"},{"fr":"Ma valise est là-bas.","tgt":"Valizim orada.","lit":"valise-ma · là-bas"},{"fr":"Il y a un bus pour le centre ?","tgt":"Merkeze otobüs var mı?","lit":"centre-vers · bus · il-y-a · [question]"},{"fr":"Oui, juste devant la porte.","tgt":"Evet, kapının hemen önünde.","lit":"oui · porte-de · juste · devant-son-à"},{"fr":"Où se trouve la sortie ?","tgt":"Çıkış nerede?","lit":"sortie · où"},{"fr":"Bienvenue à Izmir !","tgt":"İzmir'e hoş geldiniz!","lit":"Izmir-à · agréable · venir-[passé]-vous"}]},{"title":"Aujourd'hui, demain, hier","phrases":[{"fr":"Aujourd'hui, le temps est vraiment beau.","tgt":"Bugün hava çok güzel.","lit":"aujourd'hui · temps · très · beau"},{"fr":"Demain, nous allons à Éphèse.","tgt":"Yarın Efes'e gidiyoruz.","lit":"demain · Éphèse-à · aller-[présent]-nous"},{"fr":"Hier, je suis arrivé à Izmir.","tgt":"Dün İzmir'e geldim.","lit":"hier · Izmir-à · venir-[passé]-je"},{"fr":"Aujourd'hui, nous restons à l'hôtel.","tgt":"Bugün otelde kalıyoruz.","lit":"aujourd'hui · hôtel-dans · rester-[présent]-nous"},{"fr":"Demain matin, le bus part à huit heures.","tgt":"Yarın sabah otobüs saat sekizde kalkıyor.","lit":"demain · matin · bus · heure · huit-à · partir-[présent]"},{"fr":"Hier, il faisait très chaud.","tgt":"Dün hava çok sıcaktı.","lit":"hier · temps · très · chaud-[passé]"},{"fr":"Qu'est-ce qu'on fait aujourd'hui ?","tgt":"Bugün ne yapıyoruz?","lit":"aujourd'hui · quoi · faire-[présent]-nous"},{"fr":"Aujourd'hui, on va à la plage.","tgt":"Bugün plaja gidiyoruz.","lit":"aujourd'hui · plage-à · aller-[présent]-nous"},{"fr":"Et demain, alors ?","tgt":"Ya yarın?","lit":"et · demain"},{"fr":"Demain, on verra bien.","tgt":"Yarın bakarız.","lit":"demain · regarder-[on verra]-nous"}],"tip":{"title":"« Bugün », « yarın », « dün » : aujourd'hui, demain, hier","example":"Demain, nous allons à Éphèse. — <b>Yarın</b> Efes'e gidiyoruz.","body":"Trois petits mots suffisent pour se situer dans le temps : « bugün », aujourd'hui, « yarın », demain, et « dün », hier. « Bugün » se décompose joliment : « bu », ce, et « gün », jour, donc littéralement « ce jour ». En turc, on place ces mots tout au début de la phrase, exactement comme en français, et le verbe arrive toujours à la fin. Prenons « Yarın Efes'e gidiyoruz » : demain, Éphèse-à, nous allons. Avec « yarın », on garde souvent le présent en « -iyor », comme en français quand on dit « demain, on part ». Avec « dün », le verbe passe au passé : « Dün geldim », hier je suis venu. Petits exemples : « Bugün plaja gidiyoruz », aujourd'hui on va à la plage, et « Dün hava sıcaktı », hier il faisait chaud. Pour retenir, pensez que « dün » est court et sec, comme une journée déjà finie.","lit":"demain · Éphèse-à · aller-[présent]-nous","say":{"Bugün":"Bugün","yarın":"yarın","dün":"dün","bugün":"bugün","Yarın Efes'e gidiyoruz":"Yarın Efes'e gidiyoruz","Dün geldim":"Dün geldim","Bugün plaja gidiyoruz":"Bugün plaja gidiyoruz","Dün hava sıcaktı":"Dün hava sıcaktı"}}},{"title":"À l'hôtel, face à la mer","phrases":[{"fr":"Bonsoir, j'ai une réservation.","tgt":"İyi akşamlar, rezervasyonum var.","lit":"bon · soirs · réservation-ma · il-y-a"},{"fr":"C'est à quel nom, s'il vous plaît ?","tgt":"Hangi isimle, lütfen?","lit":"quel · nom-avec · s'il-vous-plaît"},{"fr":"Je m'appelle Paul Martin.","tgt":"Adım Paul Martin.","lit":"nom-mon · Paul Martin"},{"fr":"Une chambre pour trois nuits.","tgt":"Üç gece için bir oda.","lit":"trois · nuit · pour · une · chambre"},{"fr":"Votre chambre est au deuxième étage.","tgt":"Odanız ikinci katta.","lit":"chambre-votre · deuxième · étage-à"},{"fr":"Voici votre clé, bon séjour.","tgt":"Buyurun anahtarınız, iyi tatiller.","lit":"[voici] · clé-votre · bonnes · vacances"},{"fr":"À quelle heure sert-on le petit-déjeuner ?","tgt":"Kahvaltı saat kaçta?","lit":"petit-déjeuner · heure · combien-à"},{"fr":"Le matin, à sept heures.","tgt":"Sabah saat yedide.","lit":"matin · heure · sept-à"},{"fr":"La clim de la chambre ne marche pas.","tgt":"Odadaki klima çalışmıyor.","lit":"chambre-dans-qui-est · climatisation · marcher-[ne… pas]-[présent]"},{"fr":"La chambre a vue sur la mer ?","tgt":"Odanın deniz manzarası var mı?","lit":"chambre-de · mer · vue-sa · il-y-a · [question]"}]},{"title":"Où allez-vous ?","phrases":[{"fr":"Où allez-vous ?","tgt":"Nereye gidiyorsunuz?","lit":"où-vers · aller-[présent]-vous"},{"fr":"Je vais à Izmir.","tgt":"İzmir'e gidiyorum.","lit":"Izmir-à · aller-[présent]-je"},{"fr":"Nous allons à la mer.","tgt":"Denize gidiyoruz.","lit":"mer-à · aller-[présent]-nous"},{"fr":"Ce bus va à Çeşme ?","tgt":"Bu otobüs Çeşme'ye gidiyor mu?","lit":"ce · bus · Çeşme-à · aller-[présent] · [question]"},{"fr":"Non, il va à l'aéroport.","tgt":"Hayır, havalimanına gidiyor.","lit":"non · aéroport-à · aller-[présent]"},{"fr":"Je vais à l'hôtel maintenant.","tgt":"Şimdi otele gidiyorum.","lit":"maintenant · hôtel-à · aller-[présent]-je"},{"fr":"Vous venez au marché ?","tgt":"Pazara geliyor musunuz?","lit":"marché-à · venir-[présent] · [question]-vous"},{"fr":"Mon amie va à la plage.","tgt":"Arkadaşım plaja gidiyor.","lit":"amie-mon · plage-à · aller-[présent]"},{"fr":"Ce soir, on va au port.","tgt":"Bu akşam limana gidiyoruz.","lit":"ce · soir · port-à · aller-[présent]-nous"},{"fr":"Bon voyage à vous !","tgt":"İyi yolculuklar!","lit":"bons · voyages"}],"tip":{"title":"« -e » et « -a » : la direction, aller à Izmir","example":"Je vais à Izmir. — <b>İzmir'e</b> gidiyorum.","body":"En français, on dit « à » ou « vers » devant le lieu. En turc, on colle simplement un petit son à la fin du lieu : « e » ou « a ». On dit « İzmir'e », à Izmir, et « plaja », à la plage. Le choix dépend de la dernière voyelle du mot : après « i » ou « e », on dit « e », après « a » ou « o », on dit « a ». C'est l'harmonie vocalique, la musique du turc. Décomposons « Denize gidiyoruz » : « deniz », la mer, plus « e », vers, puis « gidiyoruz », nous allons. Quand le mot finit déjà par une voyelle, on glisse un « y » pour que ça sonne bien : « Çeşme'ye », à Çeşme. Autres exemples : « otele », à l'hôtel, « limana », au port, « pazara », au marché. Astuce : imaginez une petite flèche collée au bout du lieu, c'est elle qui indique où vous allez.","lit":"Izmir-à · aller-[présent]-je","say":{"İzmir'e":"İzmir'e","plaja":"plaja","Denize gidiyoruz":"Denize gidiyoruz","deniz":"deniz","gidiyoruz":"gidiyoruz","Çeşme'ye":"Çeşme'ye","otele":"otele","limana":"limana","pazara":"pazara"}}},{"title":"Changer de l'argent","phrases":[{"fr":"Où est le bureau de change ?","tgt":"Döviz bürosu nerede?","lit":"devise · bureau-son · où"},{"fr":"Je voudrais changer un peu d'argent.","tgt":"Biraz para bozdurmak istiyorum.","lit":"un-peu · argent · faire-changer · vouloir-[présent]-je"},{"fr":"Le distributeur est à côté de la banque.","tgt":"ATM bankanın yanında.","lit":"distributeur · banque-de · côté-son-à"},{"fr":"Ma carte ne marche pas.","tgt":"Kartım çalışmıyor.","lit":"carte-ma · marcher-[ne… pas]-[présent]"},{"fr":"Je vais payer en liquide.","tgt":"Nakit ödüyorum.","lit":"espèces · payer-[présent]-je"},{"fr":"J'ai seulement des livres turques.","tgt":"Sadece Türk liram var.","lit":"seulement · turque · livre-ma · il-y-a"},{"fr":"Je n'ai pas du tout de monnaie.","tgt":"Hiç bozuk param yok.","lit":"pas-du-tout · petite · monnaie-ma · il-n'y-a-pas"},{"fr":"Vous avez la monnaie sur cent livres ?","tgt":"Yüz liranın bozuğu var mı?","lit":"cent · livre-de · monnaie-sa · il-y-a · [question]"},{"fr":"Voici votre argent.","tgt":"Buyurun, paranız.","lit":"[voici] · argent-votre"},{"fr":"Merci beaucoup, au revoir.","tgt":"Çok teşekkürler, hoşça kalın.","lit":"beaucoup · merci-s · agréablement · restez"}]},{"title":"Au bazar de Kemeraltı","phrases":[{"fr":"Combien coûtent ces figues ?","tgt":"Bu incirler kaç lira?","lit":"ce · figue-s · combien · livre"},{"fr":"Le kilo est à quatre-vingts livres.","tgt":"Kilosu seksen lira.","lit":"kilo-son · quatre-vingts · livre"},{"fr":"Et ce foulard, il coûte combien ?","tgt":"Bu şal kaç lira?","lit":"ce · foulard · combien · livre"},{"fr":"Deux cents livres.","tgt":"İki yüz lira.","lit":"deux · cent · livre"},{"fr":"C'est un peu cher pour moi.","tgt":"Bana biraz pahalı.","lit":"moi-à · un-peu · cher"},{"fr":"Cent cinquante livres, ça vous va ?","tgt":"Yüz elli lira, olur mu?","lit":"cent · cinquante · livre · ça-va · [question]"},{"fr":"D'accord, cent soixante-dix.","tgt":"Tamam, yüz yetmiş.","lit":"d'accord · cent · soixante-dix"},{"fr":"Et les olives, c'est combien ?","tgt":"Zeytinler kaç lira?","lit":"olive-s · combien · livre"},{"fr":"Alors, je vous dois combien ?","tgt":"Borcum ne kadar?","lit":"dette-ma · quoi · autant"},{"fr":"Ça fait trois cents livres en tout.","tgt":"Toplam üç yüz lira.","lit":"total · trois · cent · livre"}],"tip":{"title":"« Kaç lira ? » : demander un prix","example":"Combien coûtent ces figues ? — Bu incirler <b>kaç</b> <b>lira</b>?","body":"Au marché, une seule question vous sauve : « Kaç lira ? », combien de livres. « Kaç » veut dire combien, et « lira » la livre turque. Il suffit de montrer l'objet et de dire « Bu kaç lira ? », ceci combien de livres. Remarquez que le verbe coûter n'existe même pas dans la phrase : le turc va droit au but. Autre surprise, après un nombre, le mot reste au singulier : on dit « iki yüz lira », deux cent livre, jamais livres. Décomposons « Bu incirler kaç lira ? » : « bu », ces, « incirler », figues, « kaç », combien, « lira », livre. Pour payer à la fin, on demande « Borcum ne kadar ? », combien je vous dois. Et si c'est trop cher, un sourire et « biraz pahalı », un peu cher, ouvrent la discussion. Pour retenir, pensez que « kaç » claque comme une pièce sur le comptoir.","lit":"ce · figue-s · combien · livre","say":{"Kaç lira ?":"Kaç lira?","Kaç":"Kaç","lira":"lira","Bu kaç lira ?":"Bu kaç lira?","iki yüz lira":"iki yüz lira","Bu incirler kaç lira ?":"Bu incirler kaç lira?","bu":"bu","incirler":"incirler","kaç":"kaç","Borcum ne kadar ?":"Borcum ne kadar?","biraz pahalı":"biraz pahalı"}}},{"title":"Le marché aux poissons","phrases":[{"fr":"Ce poisson est bien frais ?","tgt":"Bu balık taze mi?","lit":"ce · poisson · frais · [question]"},{"fr":"Oui, il est arrivé ce matin.","tgt":"Evet, bu sabah geldi.","lit":"oui · ce · matin · venir-[passé]"},{"fr":"C'est quel poisson, celui-là ?","tgt":"Bu hangi balık?","lit":"ce · quel · poisson"},{"fr":"C'est une daurade.","tgt":"Bu çipura.","lit":"ce · daurade"},{"fr":"Je voudrais un kilo de sardines.","tgt":"Bir kilo sardalya istiyorum.","lit":"un · kilo · sardine · vouloir-[présent]-je"},{"fr":"Vous pouvez le nettoyer ?","tgt":"Temizler misiniz?","lit":"nettoyer-[aoriste] · [question]-vous"},{"fr":"Il y a aussi des moules farcies.","tgt":"Midye dolma da var.","lit":"moule · farcie · aussi · il-y-a"},{"fr":"Ici, les moules sont délicieuses.","tgt":"Burada midyeler çok lezzetli.","lit":"ici · moule-s · très · délicieux"},{"fr":"Ce soir, on mange du poisson.","tgt":"Bu akşam balık yiyoruz.","lit":"ce · soir · poisson · manger-[présent]-nous"},{"fr":"Le marché ferme à quelle heure ?","tgt":"Pazar saat kaçta kapanıyor?","lit":"marché · heure · combien-à · fermer-[présent]"}]},{"title":"Le bus pour Éphèse","phrases":[{"fr":"Le bus part de la grande gare routière.","tgt":"Otobüs büyük otogardan kalkıyor.","lit":"bus · grande · gare-routière-de · partir-[présent]"},{"fr":"D'Izmir jusqu'à Selçuk, il faut une heure.","tgt":"İzmir'den Selçuk'a kadar bir saat sürüyor.","lit":"Izmir-de · Selçuk-à · jusque · une · heure · durer-[présent]"},{"fr":"Je vais en taxi de l'hôtel jusqu'à la gare routière.","tgt":"Otelden otogara kadar taksiyle gidiyorum.","lit":"hôtel-de · gare-routière-à · jusque · taxi-avec · aller-[présent]-je"},{"fr":"Un billet pour Selçuk, s'il vous plaît.","tgt":"Selçuk'a bir bilet, lütfen.","lit":"Selçuk-à · un · billet · s'il-vous-plaît"},{"fr":"Le bus va jusqu'à Éphèse ?","tgt":"Otobüs Efes'e kadar gidiyor mu?","lit":"bus · Éphèse-à · jusque · aller-[présent] · [question]"},{"fr":"Non, seulement jusqu'à Selçuk.","tgt":"Hayır, sadece Selçuk'a kadar.","lit":"non · seulement · Selçuk-à · jusque"},{"fr":"Nous venons de Lyon.","tgt":"Lyon'dan geliyoruz.","lit":"Lyon-de · venir-[présent]-nous"},{"fr":"Le site est ouvert de huit heures à dix-neuf heures.","tgt":"Ören yeri saat sekizden on dokuza kadar açık.","lit":"ruines · lieu-son · heure · huit-de · dix · neuf-à · jusque · ouvert"},{"fr":"Vous attendez jusqu'à quelle heure ?","tgt":"Saat kaça kadar bekliyorsunuz?","lit":"heure · combien-à · jusque · attendre-[présent]-vous"},{"fr":"On attend ici jusqu'à midi.","tgt":"Öğlene kadar burada bekliyoruz.","lit":"midi-à · jusque · ici · attendre-[présent]-nous"}],"tip":{"title":"« -den » et « -e kadar » : de... jusqu'à...","example":"D'Izmir jusqu'à Selçuk, il faut une heure. — <b>İzmir'den</b> <b>Selçuk'a</b> <b>kadar</b> bir saat sürüyor.","body":"Pour dire d'où l'on part, le turc colle « den » ou « dan » à la fin du lieu : « İzmir'den », d'Izmir, « otogardan », de la gare routière. Comme pour la direction, la voyelle suit la musique du mot : « den » après « e » ou « i », « dan » après « a » ou « o ». Pour dire jusqu'où l'on va, on prend la direction, « e » ou « a », et on ajoute le petit mot « kadar », jusque. Décomposons « İzmir'den Selçuk'a kadar » : Izmir-de, Selçuk-à, jusque. L'ordre est le même qu'en français, simplement les petits mots sont placés après le lieu au lieu d'avant. Cela marche aussi pour les heures : « sekizden on dokuza kadar », de huit heures à dix-neuf heures, ou « öğlene kadar », jusqu'à midi. Astuce : « den », c'est le point de départ, et « kadar », c'est la ligne d'arrivée.","lit":"Izmir-de · Selçuk-à · jusque · une · heure · durer-[présent]","say":{"İzmir'den":"İzmir'den","otogardan":"otogardan","kadar":"kadar","İzmir'den Selçuk'a kadar":"İzmir'den Selçuk'a kadar","sekizden on dokuza kadar":"sekizden on dokuza kadar","öğlene kadar":"öğlene kadar"}}},{"title":"Visiter Éphèse","phrases":[{"fr":"L'entrée coûte combien ?","tgt":"Giriş kaç lira?","lit":"entrée · combien · livre"},{"fr":"Voici deux billets.","tgt":"Buyurun, iki bilet.","lit":"[voici] · deux · billet"},{"fr":"Le site est immense.","tgt":"Ören yeri çok büyük.","lit":"ruines · lieu-son · très · grand"},{"fr":"Regardez cette bibliothèque !","tgt":"Şu kütüphaneye bakın!","lit":"ce · bibliothèque-à · regardez"},{"fr":"C'est la bibliothèque de Celsus.","tgt":"Bu, Celsus Kütüphanesi.","lit":"ce · Celsus · bibliothèque-sa"},{"fr":"Il y a foule aujourd'hui.","tgt":"Bugün çok kalabalık.","lit":"aujourd'hui · très · bondé"},{"fr":"Il fait chaud, vous avez de l'eau ?","tgt":"Hava sıcak, suyunuz var mı?","lit":"temps · chaud · eau-votre · il-y-a · [question]"},{"fr":"Le grand théâtre est magnifique.","tgt":"Büyük tiyatro harika.","lit":"grand · théâtre · magnifique"},{"fr":"Je prends une photo.","tgt":"Bir fotoğraf çekiyorum.","lit":"une · photo · tirer-[présent]-je"},{"fr":"Éphèse est vraiment impressionnante.","tgt":"Efes gerçekten etkileyici.","lit":"Éphèse · vraiment · impressionnant"}]},{"title":"En bus ou en ferry ?","phrases":[{"fr":"On va à Karşıyaka en ferry.","tgt":"Karşıyaka'ya vapurla gidiyoruz.","lit":"Karşıyaka-à · ferry-avec · aller-[présent]-nous"},{"fr":"Le ferry, c'est vraiment agréable.","tgt":"Vapur çok keyifli.","lit":"ferry · très · agréable"},{"fr":"Je vais à Çeşme en bus.","tgt":"Çeşme'ye otobüsle gidiyorum.","lit":"Çeşme-à · bus-avec · aller-[présent]-je"},{"fr":"Vous venez avec nous ?","tgt":"Bizimle geliyor musunuz?","lit":"nous-avec · venir-[présent] · [question]-vous"},{"fr":"Je voyage avec ma femme.","tgt":"Eşimle seyahat ediyorum.","lit":"épouse-ma-avec · voyage · faire-[présent]-je"},{"fr":"Je paie par carte.","tgt":"Kartla ödüyorum.","lit":"carte-avec · payer-[présent]-je"},{"fr":"On traverse la baie en ferry.","tgt":"Körfezi vapurla geçiyoruz.","lit":"baie-[objet] · ferry-avec · traverser-[présent]-nous"},{"fr":"Le ferry part toutes les vingt minutes.","tgt":"Vapur yirmi dakikada bir kalkıyor.","lit":"ferry · vingt · minute-dans · un · partir-[présent]"},{"fr":"Les mouettes suivent le ferry.","tgt":"Martılar vapuru takip ediyor.","lit":"mouette-s · ferry-[objet] · suivi · faire-[présent]"},{"fr":"Et vous, vous voyagez en voiture ?","tgt":"Ya siz, arabayla mı geziyorsunuz?","lit":"et · vous · voiture-avec · [question] · voyager-[présent]-vous"}],"tip":{"title":"« -le » : avec, et voyager en bus ou en ferry","example":"Je vais à Çeşme en bus. — Çeşme'ye <b>otobüsle</b> gidiyorum.","body":"Le turc n'a pas de mot séparé pour dire « avec » : il colle « le » ou « la » à la fin du mot. « Otobüsle » veut dire avec le bus, donc en bus, et « vapurla », avec le ferry, donc en ferry. Là où le français change de petit mot, en bus, à pied, par carte, le turc garde toujours le même son. On choisit « le » après « e », « i », « ö » ou « ü », et « la » après « a », « ı », « o » ou « u ». Décomposons « Çeşme'ye otobüsle gidiyorum » : Çeşme-à, bus-avec, je vais. Le même son sert aussi pour les personnes : « eşimle », avec ma femme, « bizimle », avec nous. Et pour payer, on dit « kartla », par carte. Si le mot finit par une voyelle, on glisse un « y » : « taksiyle », en taxi. Astuce : retenez « vapurla » en pensant au bruit tranquille du ferry qui glisse sur la baie.","lit":"Çeşme-à · bus-avec · aller-[présent]-je","say":{"Otobüsle":"Otobüsle","vapurla":"vapurla","Çeşme'ye otobüsle gidiyorum":"Çeşme'ye otobüsle gidiyorum","eşimle":"eşimle","bizimle":"bizimle","kartla":"kartla","taksiyle":"taksiyle"}}},{"title":"Un dîner de poisson au bord de l'eau","phrases":[{"fr":"Vous avez une table près de la mer ?","tgt":"Denize yakın bir masa var mı?","lit":"mer-à · proche · une · table · il-y-a · [question]"},{"fr":"Oui, en terrasse.","tgt":"Evet, terasta.","lit":"oui · terrasse-sur"},{"fr":"Vous pouvez m'apporter la carte ?","tgt":"Menüyü getirir misiniz?","lit":"menu-[objet] · apporter-[aoriste] · [question]-vous"},{"fr":"Que nous conseillez-vous ce soir ?","tgt":"Bu akşam ne tavsiye edersiniz?","lit":"ce · soir · quoi · conseil · faire-[aoriste]-vous"},{"fr":"Le bar grillé est excellent.","tgt":"Izgara levrek çok güzel.","lit":"grillé · bar · très · bon"},{"fr":"Nous prenons d'abord des mezzés.","tgt":"Önce meze alıyoruz.","lit":"d'abord · mezzé · prendre-[présent]-nous"},{"fr":"Et une salade aussi, s'il vous plaît.","tgt":"Bir de salata, lütfen.","lit":"un · aussi · salade · s'il-vous-plaît"},{"fr":"Le poisson est délicieux.","tgt":"Balık çok lezzetli.","lit":"poisson · très · délicieux"},{"fr":"L'addition, s'il vous plaît.","tgt":"Hesap, lütfen.","lit":"addition · s'il-vous-plaît"},{"fr":"Le coucher de soleil est splendide.","tgt":"Gün batımı harika.","lit":"jour · coucher-son · magnifique"}]},{"title":"On fait quoi ce soir ?","phrases":[{"fr":"Allons-y !","tgt":"Gidelim!","lit":"allons"},{"fr":"Allons au port ce soir.","tgt":"Bu akşam limana gidelim.","lit":"ce · soir · port-à · allons"},{"fr":"Prenons un thé.","tgt":"Bir çay içelim.","lit":"un · thé · buvons"},{"fr":"Mangeons ici.","tgt":"Burada yiyelim.","lit":"ici · mangeons"},{"fr":"Promenons-nous sur le Kordon.","tgt":"Kordon'da yürüyelim.","lit":"Kordon-sur · marchons"},{"fr":"Très bonne idée, allons-y.","tgt":"Çok iyi fikir, gidelim.","lit":"très · bonne · idée · allons"},{"fr":"On prend un taxi ?","tgt":"Taksiye binelim mi?","lit":"taxi-à · montons · [question]"},{"fr":"Non, marchons, c'est tout près.","tgt":"Hayır, yürüyelim, çok yakın.","lit":"non · marchons · très · près"},{"fr":"Attendons un peu.","tgt":"Biraz bekleyelim.","lit":"un-peu · attendons"},{"fr":"Demain, allons à Çeşme !","tgt":"Yarın Çeşme'ye gidelim!","lit":"demain · Çeşme-à · allons"}],"tip":{"title":"« Gidelim » : allons-y, faire une proposition","example":"Allons au port ce soir. — Bu akşam limana <b>gidelim</b>.","body":"Pour proposer quelque chose à quelqu'un, le turc a une forme très pratique : on ajoute « elim » ou « alım » au verbe. « Gidelim » veut dire allons-y, « yiyelim », mangeons, « bekleyelim », attendons. C'est l'équivalent exact de notre forme en « ons », comme dans « allons » ou « mangeons ». Décomposons « Bu akşam limana gidelim » : « bu akşam », ce soir, « limana », au port, et « gidelim », allons. Comme toujours en turc, le verbe arrive à la fin, c'est lui qui conclut la proposition. Pour demander l'avis de l'autre, on ajoute simplement « mi » : « Taksiye binelim mi ? », on prend un taxi ? Autres exemples : « Bir çay içelim », prenons un thé, et « Kordon'da yürüyelim », promenons-nous sur le Kordon. Astuce : « gidelim » se dit avec entrain, presque en chantant, c'est le mot des bonnes idées.","lit":"ce · soir · port-à · allons","say":{"Gidelim":"Gidelim","yiyelim":"yiyelim","bekleyelim":"bekleyelim","Bu akşam limana gidelim":"Bu akşam limana gidelim","bu akşam":"bu akşam","limana":"limana","gidelim":"gidelim","mi":"mi","Taksiye binelim mi ?":"Taksiye binelim mi?","Bir çay içelim":"Bir çay içelim","Kordon'da yürüyelim":"Kordon'da yürüyelim"}}},{"title":"Les plages près de Çeşme","phrases":[{"fr":"La mer est très claire.","tgt":"Deniz çok berrak.","lit":"mer · très · limpide"},{"fr":"Elle est froide, l'eau ?","tgt":"Su soğuk mu?","lit":"eau · froid · [question]"},{"fr":"Non, elle est tiède.","tgt":"Hayır, ılık.","lit":"non · tiède"},{"fr":"On loue deux transats ?","tgt":"İki şezlong kiralayalım mı?","lit":"deux · transat · louons · [question]"},{"fr":"Le parasol coûte combien ?","tgt":"Şemsiye kaç lira?","lit":"parasol · combien · livre"},{"fr":"Il y a beaucoup de vent aujourd'hui.","tgt":"Bugün çok rüzgâr var.","lit":"aujourd'hui · beaucoup · vent · il-y-a"},{"fr":"Alaçatı est célèbre pour son vent.","tgt":"Alaçatı rüzgârıyla ünlü.","lit":"Alaçatı · vent-son-avec · célèbre"},{"fr":"Je vais nager un petit moment.","tgt":"Biraz yüzüyorum.","lit":"un-peu · nager-[présent]-je"},{"fr":"N'oubliez pas la crème solaire.","tgt":"Güneş kremini unutmayın.","lit":"soleil · crème-sa-[objet] · oubliez-[ne… pas]"},{"fr":"Cette plage est un vrai paradis.","tgt":"Bu plaj gerçek bir cennet.","lit":"cette · plage · vrai · un · paradis"}]},{"title":"C'est loin ?","phrases":[{"fr":"La plage est loin ?","tgt":"Plaj uzak mı?","lit":"plage · loin · [question]"},{"fr":"Non, elle est juste à côté.","tgt":"Hayır, hemen yakında.","lit":"non · juste · près-dans"},{"fr":"L'aéroport est loin d'ici ?","tgt":"Havalimanı buraya uzak mı?","lit":"aéroport · ici-à · loin · [question]"},{"fr":"Oui, c'est assez loin.","tgt":"Evet, oldukça uzak.","lit":"oui · assez · loin"},{"fr":"C'est à dix minutes à pied.","tgt":"Yürüyerek on dakika.","lit":"en-marchant · dix · minute"},{"fr":"La pharmacie est près de l'hôtel ?","tgt":"Eczane otele yakın mı?","lit":"pharmacie · hôtel-à · près · [question]"},{"fr":"C'est loin ou c'est près ?","tgt":"Uzak mı, yakın mı?","lit":"loin · [question] · près · [question]"},{"fr":"Non, ce n'est pas loin.","tgt":"Hayır, uzak değil.","lit":"non · loin · [ne… pas]"},{"fr":"Le marché est près du port.","tgt":"Pazar limana yakın.","lit":"marché · port-à · près"},{"fr":"Il y a un café près d'ici ?","tgt":"Yakında bir kafe var mı?","lit":"près-dans · un · café · il-y-a · [question]"}],"tip":{"title":"« Uzak mı, yakın mı ? » : loin ou près","example":"C'est loin ou c'est près ? — <b>Uzak</b> <b>mı</b>, <b>yakın</b> <b>mı</b>?","body":"Deux mots pour s'orienter : « uzak », loin, et « yakın », près. Pour poser la question, on ajoute juste derrière le petit mot « mı », qui transforme la phrase en question, un peu comme notre « est-ce que », mais placé à la fin. « Plaj uzak mı ? », la plage, loin, question ? Pour hésiter entre les deux, on répète simplement : « Uzak mı, yakın mı ? », loin ou près ? Pour dire près de quelque chose, on utilise la direction : « otele yakın », littéralement près vers l'hôtel. Décomposons « Eczane otele yakın mı ? » : pharmacie, hôtel-à, près, question. Et pour répondre non, on ajoute « değil » : « uzak değil », ce n'est pas loin. Astuce : « yakın » sonne doux et court, comme un lieu qu'on atteint vite, alors que « uzak » s'étire comme une longue route.","lit":"loin · [question] · près · [question]","say":{"Uzak mı, yakın mı ?":"Uzak mı, yakın mı?","uzak":"uzak","yakın":"yakın","mı":"mı","Plaj uzak mı ?":"Plaj uzak mı?","otele yakın":"otele yakın","Eczane otele yakın mı ?":"Eczane otele yakın mı?","değil":"değil","uzak değil":"uzak değil"}}},{"title":"En taxi dans Izmir","phrases":[{"fr":"Taxi ! Vous êtes libre ?","tgt":"Taksi! Boş musunuz?","lit":"taxi · libre · [question]-vous-êtes"},{"fr":"À la gare routière, s'il vous plaît.","tgt":"Otogara, lütfen.","lit":"gare-routière-à · s'il-vous-plaît"},{"fr":"Vous mettez le compteur ?","tgt":"Taksimetreyi açar mısınız?","lit":"compteur-[objet] · ouvrir-[aoriste] · [question]-vous"},{"fr":"Il faut combien de temps ?","tgt":"Ne kadar sürer?","lit":"quoi · autant · durer-[aoriste]"},{"fr":"Environ vingt minutes.","tgt":"Yaklaşık yirmi dakika.","lit":"environ · vingt · minute"},{"fr":"La circulation est très dense.","tgt":"Trafik çok yoğun.","lit":"circulation · très · dense"},{"fr":"Vous pouvez rouler un peu moins vite ?","tgt":"Biraz yavaş gider misiniz?","lit":"un-peu · lentement · aller-[aoriste] · [question]-vous"},{"fr":"Arrêtez-vous ici, s'il vous plaît.","tgt":"Burada durun, lütfen.","lit":"ici · arrêtez · s'il-vous-plaît"},{"fr":"Ça fait combien ?","tgt":"Ne kadar tuttu?","lit":"quoi · autant · tenir-[passé]"},{"fr":"Gardez la monnaie, merci.","tgt":"Üstü kalsın, teşekkürler.","lit":"reste-son · qu'il-reste · merci-s"}]},{"title":"Le petit-déjeuner turc","phrases":[{"fr":"Je bois le thé sans sucre.","tgt":"Çayı şekersiz içiyorum.","lit":"thé-[objet] · sucre-sans · boire-[présent]-je"},{"fr":"Vous aimez le petit-déjeuner turc ?","tgt":"Türk kahvaltısını seviyor musunuz?","lit":"turc · petit-déjeuner-son-[objet] · aimer-[présent] · [question]-vous"},{"fr":"J'adore ce fromage.","tgt":"Bu peyniri çok seviyorum.","lit":"ce · fromage-[objet] · beaucoup · aimer-[présent]-je"},{"fr":"Vous me passez le pain ?","tgt":"Ekmeği uzatır mısınız?","lit":"pain-[objet] · tendre-[aoriste] · [question]-vous"},{"fr":"Je prends les olives noires.","tgt":"Siyah zeytinleri alıyorum.","lit":"noir · olive-s-[objet] · prendre-[présent]-je"},{"fr":"Je ne connais pas ce plat.","tgt":"Bu yemeği bilmiyorum.","lit":"ce · plat-[objet] · savoir-[ne… pas]-[présent]-je"},{"fr":"C'est du menemen, des œufs aux tomates.","tgt":"Bu menemen, domatesli yumurta.","lit":"ce · menemen · tomate-avec · œuf"},{"fr":"Le menemen, c'est génial.","tgt":"Menemen harika.","lit":"menemen · génial"},{"fr":"Un autre thé, s'il vous plaît.","tgt":"Bir çay daha, lütfen.","lit":"un · thé · encore · s'il-vous-plaît"},{"fr":"Je mange le simit avec du fromage.","tgt":"Simidi peynirle yiyorum.","lit":"simit-[objet] · fromage-avec · manger-[présent]-je"}],"tip":{"title":"« -i » : l'objet précis, je bois le thé","example":"Je bois le thé sans sucre. — <b>Çayı</b> şekersiz içiyorum.","body":"Le turc n'a pas de mot pour « le » ou « la ». Mais quand on parle d'un objet précis, celui qu'on a sous les yeux, on ajoute un petit « i » à la fin du mot. « Bir çay içiyorum », c'est je bois un thé, n'importe lequel. « Çayı içiyorum », c'est je bois le thé, celui-ci, sur la table. Ce petit son change selon la musique du mot : « i », « ı », « u » ou « ü ». On dit « peyniri », le fromage, « çayı », le thé. Si le mot finit par une voyelle, on glisse un « y » : « taksimetreyi », le compteur. Décomposons « Bu peyniri çok seviyorum » : ce, fromage-le, beaucoup, j'aime. Et pour « simit », on entend « simidi », car le « t » s'adoucit en « d ». Astuce : ce petit « i » est comme un doigt pointé vers l'objet, il dit : celui-là, précisément.","lit":"thé-[objet] · sucre-sans · boire-[présent]-je","say":{"Bir çay içiyorum":"Bir çay içiyorum","Çayı içiyorum":"Çayı içiyorum","peyniri":"peyniri","çayı":"çayı","taksimetreyi":"taksimetreyi","Bu peyniri çok seviyorum":"Bu peyniri çok seviyorum","simit":"simit","simidi":"simidi"}}},{"title":"Un petit souci de santé","phrases":[{"fr":"La pharmacie la plus proche, c'est où ?","tgt":"En yakın eczane nerede?","lit":"le-plus · proche · pharmacie · où"},{"fr":"J'ai pris un coup de soleil hier.","tgt":"Dün güneşte yandım.","lit":"hier · soleil-dans · brûler-[passé]-je"},{"fr":"J'ai un peu mal au ventre.","tgt":"Karnım biraz ağrıyor.","lit":"ventre-mon · un-peu · faire-mal-[présent]"},{"fr":"Vous avez une crème pour ça ?","tgt":"Bunun için bir krem var mı?","lit":"cela-de · pour · une · crème · il-y-a · [question]"},{"fr":"Mettez-la deux fois par jour.","tgt":"Günde iki kez sürün.","lit":"jour-dans · deux · fois · étalez"},{"fr":"La nuit, les moustiques me piquent.","tgt":"Geceleri sivrisinekler beni ısırıyor.","lit":"nuit-s · moustique-s · moi-[objet] · piquer-[présent]"},{"fr":"Ce spray est très efficace.","tgt":"Bu sprey çok etkili.","lit":"ce · spray · très · efficace"},{"fr":"Buvez de l'eau en abondance.","tgt":"Bol su için.","lit":"abondant · eau · buvez"},{"fr":"Aujourd'hui, reposez-vous à l'ombre.","tgt":"Bugün gölgede dinlenin.","lit":"aujourd'hui · ombre-dans · reposez-vous"},{"fr":"Merci, vous êtes très gentil.","tgt":"Teşekkürler, çok naziksiniz.","lit":"merci-s · très · gentil-vous-êtes"}]},{"title":"Demander son chemin","phrases":[{"fr":"Pardon, où est la tour de l'Horloge ?","tgt":"Affedersiniz, Saat Kulesi nerede?","lit":"pardon · horloge · tour-sa · où"},{"fr":"Continuez simplement tout droit.","tgt":"Düz devam edin.","lit":"droit · continuation · faites"},{"fr":"Puis tournez à droite.","tgt":"Sonra sağa dönün.","lit":"ensuite · droite-à · tournez"},{"fr":"Au feu, tournez à gauche.","tgt":"Işıklardan sola dönün.","lit":"feux-de · gauche-à · tournez"},{"fr":"C'est à droite ou à gauche ?","tgt":"Sağda mı, solda mı?","lit":"droite-à · [question] · gauche-à · [question]"},{"fr":"C'est sur votre gauche.","tgt":"Solunuzda.","lit":"gauche-votre-à"},{"fr":"La deuxième rue à droite.","tgt":"Sağdan ikinci sokak.","lit":"droite-de · deuxième · rue"},{"fr":"Le marché est juste en face de vous.","tgt":"Pazar tam karşınızda.","lit":"marché · juste · en-face-votre-à"},{"fr":"Tout droit, puis à gauche, c'est bien ça ?","tgt":"Düz, sonra sola, değil mi?","lit":"droit · ensuite · gauche-à · n'est-ce-pas"},{"fr":"Oui, c'est très facile.","tgt":"Evet, çok kolay.","lit":"oui · très · facile"}],"tip":{"title":"« Sağ », « sol », « düz » : à droite, à gauche, tout droit","example":"Puis tournez à droite. — Sonra <b>sağa</b> dönün.","body":"Pour suivre un chemin, trois mots suffisent : « sağ », la droite, « sol », la gauche, et « düz », tout droit. On leur colle la direction pour dire où tourner : « sağa », vers la droite, « sola », vers la gauche. Et pour dire où se trouve quelque chose, on ajoute « da » : « sağda », à droite, « solda », à gauche. Le verbe tourner, « dönün », arrive à la fin, comme toujours. Décomposons « Sonra sağa dönün » : ensuite, droite-vers, tournez. Pour aller tout droit, on dit simplement « Düz devam edin », continuez tout droit. Quand on vous explique le chemin, répétez les étapes avec « değil mi ? », n'est-ce pas : « Düz, sonra sola, değil mi ? ». Astuce : levez la main droite en disant « sağ », la gauche en disant « sol », puis pointez devant vous pour « düz » : le geste fixe le mot.","lit":"ensuite · droite-à · tournez","say":{"Sağ":"Sağ","sol":"sol","düz":"düz","sağ":"sağ","sağa":"sağa","sola":"sola","sağda":"sağda","solda":"solda","dönün":"dönün","Sonra sağa dönün":"Sonra sağa dönün","Düz devam edin":"Düz devam edin","değil mi ?":"değil mi?","Düz, sonra sola, değil mi ?":"Düz, sonra sola, değil mi?"}}},{"title":"Des souvenirs à rapporter","phrases":[{"fr":"Je cherche des petits souvenirs.","tgt":"Hediyelik eşya arıyorum.","lit":"cadeau-pour · objet · chercher-[présent]-je"},{"fr":"Ces bols en céramique sont jolis.","tgt":"Bu seramik kâseler çok güzel.","lit":"ces · céramique · bol-s · très · joli"},{"fr":"Ce savon à l'huile d'olive sent bon.","tgt":"Bu zeytinyağlı sabun güzel kokuyor.","lit":"ce · huile-d'olive-avec · savon · bon · sentir-[présent]"},{"fr":"Je prends trois perles bleues contre le mauvais œil.","tgt":"Üç nazar boncuğu alıyorum.","lit":"trois · mauvais-œil · perle-sa · prendre-[présent]-je"},{"fr":"C'est pour ma mère.","tgt":"Annem için.","lit":"mère-ma · pour"},{"fr":"Vous pouvez faire un paquet cadeau ?","tgt":"Hediye paketi yapar mısınız?","lit":"cadeau · paquet-son · faire-[aoriste] · [question]-vous"},{"fr":"J'achète aussi du café turc.","tgt":"Türk kahvesi de alıyorum.","lit":"turc · café-son · aussi · prendre-[présent]-je"},{"fr":"Il n'y a plus de place dans ma valise !","tgt":"Valizimde yer yok!","lit":"valise-ma-dans · place · il-n'y-a-pas"},{"fr":"Ce tapis est superbe, mais trop cher.","tgt":"Bu halı çok güzel ama çok pahalı.","lit":"ce · tapis · très · beau · mais · très · cher"},{"fr":"Je reviens demain.","tgt":"Yarın tekrar geliyorum.","lit":"demain · encore · venir-[présent]-je"}]},{"title":"Fin du module : un bilan","phrases":[{"fr":"Pour voyager, il faut un peu de turc.","tgt":"Seyahat için biraz Türkçe lazım.","lit":"voyage · pour · un-peu · turc · nécessaire"},{"fr":"Maintenant, je sais demander un prix.","tgt":"Artık fiyat sormayı biliyorum.","lit":"désormais · prix · demander-[objet] · savoir-[présent]-je"},{"fr":"Je sais aussi demander mon chemin.","tgt":"Yol sormayı da biliyorum.","lit":"chemin · demander-[objet] · aussi · savoir-[présent]-je"},{"fr":"Il me faut encore un peu de pratique.","tgt":"Biraz daha pratik lazım.","lit":"un-peu · plus · pratique · nécessaire"},{"fr":"Il faut parler turc tous les jours.","tgt":"Her gün Türkçe konuşmak gerek.","lit":"chaque · jour · turc · parler · nécessaire"},{"fr":"Je n'ai plus besoin de dictionnaire.","tgt":"Artık sözlüğe gerek yok.","lit":"désormais · dictionnaire-à · besoin · il-n'y-a-pas"},{"fr":"Le turc devient plus facile pour moi.","tgt":"Türkçe benim için kolaylaşıyor.","lit":"turc · moi-de · pour · facile-devenir-[présent]"},{"fr":"J'ai besoin d'une petite pause.","tgt":"Bana kısa bir mola lazım.","lit":"moi-à · courte · une · pause · nécessaire"},{"fr":"Le prochain module, c'est la conversation.","tgt":"Sonraki modülde sohbet var.","lit":"suivant · module-dans · conversation · il-y-a"},{"fr":"À très vite pour la suite !","tgt":"Yakında görüşürüz!","lit":"bientôt · se-voir-[aoriste]-nous"}],"tip":{"title":"« Lazım » et « gerek » : il faut, j'ai besoin de","example":"Pour voyager, il faut un peu de turc. — Seyahat için biraz Türkçe <b>lazım</b>.","body":"Pour dire il faut ou j'ai besoin de, le turc utilise deux mots presque jumeaux : « lazım » et « gerek ». Les deux veulent dire nécessaire, et on les place tout à la fin, là où le français mettrait le verbe au début. Il n'y a rien à conjuguer, c'est un vrai cadeau pour débuter. Décomposons « Seyahat için biraz Türkçe lazım » : voyage, pour, un peu, turc, nécessaire. Pour préciser à qui c'est nécessaire, on dit « bana », à moi : « Bana bir mola lazım », il me faut une pause. On peut aussi mettre un verbe devant : « konuşmak gerek », il faut parler. Pour dire qu'on n'a pas besoin, on utilise « gerek yok », pas besoin, une formule que vous entendrez partout. Astuce : « lazım » sonne comme une liste de courses, et « gerek yok » comme un geste de la main qui dit : laissez, ça va.","lit":"voyage · pour · un-peu · turc · nécessaire","say":{"Lazım":"Lazım","gerek":"gerek","lazım":"lazım","Seyahat için biraz Türkçe lazım":"Seyahat için biraz Türkçe lazım","bana":"bana","Bana bir mola lazım":"Bana bir mola lazım","konuşmak gerek":"konuşmak gerek","gerek yok":"gerek yok"}}}]},{"id":3,"name":"Conversation sociale","desc":"Faire connaissance, se présenter, échanger avec aisance.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Les nouveaux voisins","phrases":[{"fr":"Bonjour, je suis votre nouvelle voisine.","tgt":"Merhaba, ben yeni komşunuzum.","lit":"bonjour · moi · nouveau · voisin-votre-je-suis"},{"fr":"Je viens d'arriver à Ankara.","tgt":"Ankara'ya yeni geldim.","lit":"Ankara-à · nouvellement · venir-[passé]-je"},{"fr":"Bienvenue dans l'immeuble !","tgt":"Apartmana hoş geldiniz!","lit":"immeuble-à · agréable · venir-[passé]-vous"},{"fr":"Merci, vous êtes très gentille.","tgt":"Teşekkür ederim, çok naziksiniz.","lit":"remerciement · faire-je · très · gentil-vous-êtes"},{"fr":"Moi, j'habite juste au-dessus, au troisième.","tgt":"Ben hemen üstte, üçüncü kattayım.","lit":"moi · juste · dessus-à · troisième · étage-à-je-suis"},{"fr":"Nous sommes au deuxième, juste en dessous.","tgt":"Biz ikinci kattayız, hemen altınızda.","lit":"nous · deuxième · étage-à-nous-sommes · juste · dessous-votre-à"},{"fr":"Vous habitez ici depuis longtemps ?","tgt":"Burada uzun zamandır mı oturuyorsunuz?","lit":"ici · long · temps-depuis · [question] · habiter-[présent]-vous"},{"fr":"Oui, depuis dix ans déjà.","tgt":"Evet, on yıldır.","lit":"oui · dix · an-depuis"},{"fr":"Le quartier est très calme.","tgt":"Mahalle çok sakin.","lit":"quartier · très · calme"},{"fr":"Les voisins ici sont très gentils.","tgt":"Buradaki komşular çok iyi.","lit":"ici-qui-est · voisin-s · très · bon"}]},{"title":"Se présenter","phrases":[{"fr":"Tu t'appelles comment, toi ?","tgt":"Senin adın ne?","lit":"ton · nom-ton · quoi"},{"fr":"Je m'appelle Camille.","tgt":"Adım Camille.","lit":"nom-mon · Camille"},{"fr":"Moi, c'est Mert, enchanté.","tgt":"Benim adım Mert, memnun oldum.","lit":"mon · nom-mon · Mert · content · devenir-[passé]-je"},{"fr":"Et ton ami, comment il s'appelle ?","tgt":"Arkadaşının adı ne?","lit":"ami-ton-de · nom-son · quoi"},{"fr":"Il s'appelle Can.","tgt":"Onun adı Can.","lit":"lui-de · nom-son · Can"},{"fr":"Je suis française, de Lyon.","tgt":"Fransızım, Lyonluyum.","lit":"Français-je-suis · Lyon-de-je-suis"},{"fr":"Très heureuse de te connaître.","tgt":"Çok memnun oldum.","lit":"très · content · devenir-[passé]-je"},{"fr":"Mon prénom est difficile à dire ?","tgt":"Adım zor mu?","lit":"nom-mon · difficile · [question]"},{"fr":"Non, ton prénom est très joli.","tgt":"Hayır, adın çok güzel.","lit":"non · nom-ton · très · beau"},{"fr":"Tout le monde m'appelle Cami.","tgt":"Herkes bana Cami diyor.","lit":"tout-le-monde · moi-à · Cami · dire-[présent]-il"}],"tip":{"title":"Se présenter : « adım », je m'appelle","example":"Je m'appelle Camille. — <b>Adım</b> Camille.","body":"Pour dire comment on s'appelle, le turc n'a pas besoin de verbe : on dit simplement « mon nom », puis le prénom. « Ad » veut dire nom, et la petite terminaison « ım » veut dire mon : « adım », mon nom. « Adım Camille », c'est donc mot à mot mon nom Camille, et cela fait une phrase complète. Pour demander, on dit « adın ne ? », mot à mot ton nom quoi ? La terminaison change selon la personne : « adım », mon nom, « adın », ton nom, « adı », son nom. On peut ajouter « benim » devant pour insister : « benim adım Mert », moi, mon nom, c'est Mert. Juste après, on dit souvent « memnun oldum », enchanté. Pour retenir, pensez à une carte de visite : un nom, et pas besoin de verbe.","lit":"nom-mon · Camille","say":{"adım":"adım","Ad":"Ad","Adım Camille":"Adım Camille","adın ne ?":"adın ne?","adın":"adın","adı":"adı","benim":"benim","benim adım Mert":"benim adım Mert","memnun oldum":"memnun oldum"}}},{"title":"Parler de son travail","phrases":[{"fr":"Mert, qu'est-ce que tu fais dans la vie ?","tgt":"Mert, ne iş yapıyorsun?","lit":"Mert · quel · travail · faire-[présent]-tu"},{"fr":"Je suis professeure de français.","tgt":"Fransızca öğretmeniyim.","lit":"français · professeur-je-suis"},{"fr":"Je travaille dans une école à Kızılay.","tgt":"Kızılay'da bir okulda çalışıyorum.","lit":"Kızılay-à · une · école-dans · travailler-[présent]-je"},{"fr":"Et toi, tu travailles où ?","tgt":"Sen nerede çalışıyorsun?","lit":"toi · où · travailler-[présent]-tu"},{"fr":"Je suis ingénieur dans une grande entreprise.","tgt":"Büyük bir şirkette mühendisim.","lit":"grand · une · entreprise-dans · ingénieur-je-suis"},{"fr":"Et ton travail, il est intéressant ?","tgt":"İşin ilginç mi?","lit":"travail-ton · intéressant · [question]"},{"fr":"Oui, mais je travaille beaucoup.","tgt":"Evet, ama çok çalışıyorum.","lit":"oui · mais · beaucoup · travailler-[présent]-je"},{"fr":"Je suis étudiante à l'université.","tgt":"Üniversitede öğrenciyim.","lit":"université-à · étudiant-je-suis"},{"fr":"Tu parles très bien français !","tgt":"Çok iyi Fransızca konuşuyorsun!","lit":"très · bien · français · parler-[présent]-tu"},{"fr":"J'apprends le turc depuis deux mois.","tgt":"İki aydır Türkçe öğreniyorum.","lit":"deux · mois-depuis · turc · apprendre-[présent]-je"}]},{"title":"Ce que j'aime","phrases":[{"fr":"J'aime Ankara.","tgt":"Ankara'yı seviyorum.","lit":"Ankara-[objet] · aimer-[présent]-je"},{"fr":"J'adore le thé turc.","tgt":"Türk çayını çok seviyorum.","lit":"turc · thé-son-[objet] · beaucoup · aimer-[présent]-je"},{"fr":"Tu aimes le café ?","tgt":"Kahveyi seviyor musun?","lit":"café-[objet] · aimer-[présent] · [question]-tu"},{"fr":"Non, je n'aime pas trop le café.","tgt":"Hayır, kahveyi pek sevmiyorum.","lit":"non · café-[objet] · guère · aimer-[ne… pas]-[présent]-je"},{"fr":"J'aime beaucoup cuisiner.","tgt":"Yemek yapmayı çok seviyorum.","lit":"repas · faire-[action]-[objet] · beaucoup · aimer-[présent]-je"},{"fr":"Mert aime le football.","tgt":"Mert futbolu seviyor.","lit":"Mert · football-[objet] · aimer-[présent]-il"},{"fr":"Nous aimons la musique turque.","tgt":"Türk müziğini seviyoruz.","lit":"turc · musique-sa-[objet] · aimer-[présent]-nous"},{"fr":"Qu'est-ce que tu aimes faire le soir ?","tgt":"Akşamları ne yapmayı seviyorsun?","lit":"soir-les · quoi · faire-[action]-[objet] · aimer-[présent]-tu"},{"fr":"J'aime lire et marcher.","tgt":"Kitap okumayı ve yürümeyi seviyorum.","lit":"livre · lire-[action]-[objet] · et · marcher-[action]-[objet] · aimer-[présent]-je"},{"fr":"Moi, j'adore les chats.","tgt":"Ben kedileri çok seviyorum.","lit":"moi · chat-s-[objet] · beaucoup · aimer-[présent]-je"}],"tip":{"title":"« Seviyorum » : aimer, et « çok seviyorum »","example":"J'adore le thé turc. — Türk çayını <b>çok seviyorum</b>.","body":"« Seviyorum » veut dire j'aime. Il se construit en trois morceaux : « sev », la racine d'aimer, « iyor », la marque du présent, et « um », je. Pour dire j'adore, on ne change pas de verbe : on ajoute simplement « çok », beaucoup, devant : « çok seviyorum ». Ce qu'on aime se place avant le verbe, avec une petite voyelle au bout : « çayı seviyorum », mot à mot le thé, j'aime. Pour la négation, on glisse « me » dans le verbe : « sevmiyorum », je n'aime pas. Pour poser la question à un ami, on dit « seviyor musun ? », tu aimes ? On peut aussi aimer une activité : « okumayı seviyorum », j'aime lire. Retenez la formule « çok seviyorum » : avec elle, vous ferez plaisir à tous vos hôtes.","lit":"turc · thé-son-[objet] · beaucoup · aimer-[présent]-je","say":{"Seviyorum":"Seviyorum","çok seviyorum":"çok seviyorum","çok":"çok","çayı seviyorum":"çayı seviyorum","sevmiyorum":"sevmiyorum","seviyor musun ?":"seviyor musun?","okumayı seviyorum":"okumayı seviyorum"}}},{"title":"Un thé chez les voisins","phrases":[{"fr":"Entrez, je vous en prie !","tgt":"Buyurun, içeri gelin!","lit":"je-vous-en-prie · intérieur · venez"},{"fr":"Vous voulez du thé ?","tgt":"Çay ister misiniz?","lit":"thé · vouloir-[habituel] · [question]-vous"},{"fr":"Oui, avec grand plaisir.","tgt":"Evet, memnuniyetle.","lit":"oui · plaisir-avec"},{"fr":"Le thé est très chaud, attention.","tgt":"Çay çok sıcak, dikkat edin.","lit":"thé · très · chaud · attention · faites"},{"fr":"Vous prenez du sucre ?","tgt":"Şeker alır mısınız?","lit":"sucre · prendre-[habituel] · [question]-vous"},{"fr":"Un sucre, s'il vous plaît.","tgt":"Bir şeker, lütfen.","lit":"un · sucre · s'il-vous-plaît"},{"fr":"Ces petits gâteaux sont faits maison ?","tgt":"Bu kurabiyeler ev yapımı mı?","lit":"ce · biscuit-s · maison · fabrication-sa · [question]"},{"fr":"Oui, c'est ma fille qui les prépare.","tgt":"Evet, kızım yapıyor.","lit":"oui · fille-ma · faire-[présent]-elle"},{"fr":"C'est vraiment délicieux.","tgt":"Gerçekten çok lezzetli.","lit":"vraiment · très · délicieux"},{"fr":"Encore un verre de thé ?","tgt":"Bir bardak çay daha?","lit":"un · verre · thé · encore"}]},{"title":"Parler de sa famille","phrases":[{"fr":"Tu as des frères et sœurs, Elif ?","tgt":"Elif, kardeşin var mı?","lit":"Elif · frère-ou-sœur-ton · il-y-a · [question]"},{"fr":"Oui, j'ai un frère et une grande sœur.","tgt":"Evet, bir erkek kardeşim ve bir ablam var.","lit":"oui · un · garçon · frère-mon · et · une · grande-sœur-ma · il-y-a"},{"fr":"Ma grande sœur habite à Paris.","tgt":"Ablam Paris'te oturuyor.","lit":"grande-sœur-ma · Paris-à · habiter-[présent]-elle"},{"fr":"Mon petit frère est encore étudiant.","tgt":"Erkek kardeşim hâlâ öğrenci.","lit":"garçon · frère-mon · encore · étudiant"},{"fr":"Ma mère s'appelle Sophie.","tgt":"Annemin adı Sophie.","lit":"mère-ma-de · nom-son · Sophie"},{"fr":"Mon père est médecin à Lyon.","tgt":"Babam Lyon'da doktor.","lit":"père-mon · Lyon-à · médecin"},{"fr":"Tes parents habitent où ?","tgt":"Annen baban nerede oturuyor?","lit":"mère-ta · père-ton · où · habiter-[présent]-ils"},{"fr":"Ils vivent près de Bordeaux.","tgt":"Bordeaux yakınında oturuyorlar.","lit":"Bordeaux · près-son-à · habiter-[présent]-ils"},{"fr":"Mert est enfant unique.","tgt":"Mert tek çocuk.","lit":"Mert · seul · enfant"},{"fr":"Elif a deux frères.","tgt":"Elif'in iki erkek kardeşi var.","lit":"Elif-de · deux · garçon · frère-son · il-y-a"}],"tip":{"title":"La famille : « anne », « baba », « kardeş », « abla »","example":"Ma grande sœur habite à Paris. — <b>Ablam</b> Paris'te oturuyor.","body":"Les mots de la famille sont courts et faciles à dire. « Anne », c'est la mère, et « baba », le père ; on dit « annem », ma mère, et « babam », mon père. « Kardeş » désigne un frère ou une sœur, sans distinction. Pour préciser, on dit « erkek kardeş », mot à mot garçon de la fratrie, donc frère, et « kız kardeş », fille de la fratrie, donc sœur. La grande sœur a un mot à elle : « abla », et le grand frère se dit « abi ». C'est une vraie différence avec le français : en turc, l'âge compte, et on appelle même une amie un peu plus âgée « abla », par affection. Pour dire qu'on a un frère, on utilise « var », il y a : « kardeşim var », mot à mot mon frère existe. Astuce : « anne » et « baba » ressemblent aux premiers mots des bébés.","lit":"grande-sœur-ma · Paris-à · habiter-[présent]-elle","say":{"anne":"anne","baba":"baba","kardeş":"kardeş","abla":"abla","Anne":"Anne","annem":"annem","babam":"babam","Kardeş":"Kardeş","erkek kardeş":"erkek kardeş","kız kardeş":"kız kardeş","abi":"abi","var":"var","kardeşim var":"kardeşim var"}}},{"title":"Les photos de famille","phrases":[{"fr":"Regarde, voici ma famille.","tgt":"Bak, bu benim ailem.","lit":"regarde · ceci · mon · famille-ma"},{"fr":"Qui est cette petite fille ?","tgt":"Bu küçük kız kim?","lit":"ce · petit · fille · qui"},{"fr":"C'est ma nièce, elle a cinq ans.","tgt":"Yeğenim, beş yaşında.","lit":"nièce-ma · cinq · âge-son-à"},{"fr":"Elle est trop mignonne !","tgt":"Çok tatlı!","lit":"très · mignon"},{"fr":"Et ce monsieur, c'est ton grand-père ?","tgt":"Bu bey deden mi?","lit":"ce · monsieur · grand-père-ton · [question]"},{"fr":"Oui, il a quatre-vingts ans.","tgt":"Evet, seksen yaşında.","lit":"oui · quatre-vingts · âge-son-à"},{"fr":"Ma grand-mère cuisine très bien.","tgt":"Babaannem çok güzel yemek yapıyor.","lit":"grand-mère-ma · très · beau · repas · faire-[présent]-elle"},{"fr":"Et toi, tu as des enfants ?","tgt":"Senin çocuğun var mı?","lit":"ton · enfant-ton · il-y-a · [question]"},{"fr":"Non, pas encore.","tgt":"Hayır, henüz yok.","lit":"non · encore · il-n'y-a-pas"},{"fr":"Ma famille me manque un peu.","tgt":"Ailemi biraz özlüyorum.","lit":"famille-ma-[objet] · un-peu · regretter-[présent]-je"}]},{"title":"Tutoyer ses nouveaux amis","phrases":[{"fr":"On se tutoie ?","tgt":"Birbirimize sen diyelim mi?","lit":"l'un-l'autre-à · tu · disons · [question]"},{"fr":"Bien sûr, dis-moi « tu » !","tgt":"Tabii, bana sen de!","lit":"bien-sûr · moi-à · tu · dis"},{"fr":"Et toi, comment vas-tu ?","tgt":"Sen nasılsın?","lit":"toi · comment-tu-es"},{"fr":"Comment allez-vous, madame ?","tgt":"Nasılsınız, hanımefendi?","lit":"comment-vous-êtes · madame"},{"fr":"Tu es d'où ?","tgt":"Nerelisin?","lit":"où-de-tu-es"},{"fr":"Vous êtes d'où, monsieur ?","tgt":"Nerelisiniz, beyefendi?","lit":"où-de-vous-êtes · monsieur"},{"fr":"À tante Ayşe, la voisine, je dis « vous ».","tgt":"Ayşe Teyze'ye siz diyorum.","lit":"Ayşe · tante-à · vous · dire-[présent]-je"},{"fr":"À Mert, je dis « tu ».","tgt":"Mert'e sen diyorum.","lit":"Mert-à · tu · dire-[présent]-je"},{"fr":"Tu es libre ce soir, Mert ?","tgt":"Bu akşam boş musun, Mert?","lit":"ce · soir · libre · [question]-tu · Mert"},{"fr":"Vous êtes libre ce soir, madame ?","tgt":"Bu akşam boş musunuz, hanımefendi?","lit":"ce · soir · libre · [question]-vous · madame"}],"tip":{"title":"« Sen » ou « siz » : tutoyer ou vouvoyer","example":"Et toi, comment vas-tu ? — Sen <b>nasılsın</b>?","body":"Comme en français, le turc a deux façons de s'adresser à quelqu'un. « Sen », c'est tu, pour les amis, la famille et les enfants. « Siz », c'est vous, pour les inconnus, les personnes âgées et les situations polies. On l'entend surtout à la fin des verbes : « nasılsın ? », comment vas-tu, devient « nasılsınız ? », comment allez-vous. La terminaison « sın » devient « sınız » : il suffit d'ajouter « ız ». Pour proposer de se tutoyer, on dit « sen diyelim mi ? », mot à mot tu disons-nous ? Avec une voisine plus âgée, on garde « siz », même si on l'appelle affectueusement « teyze », tante. Dans le doute, commencez par « siz » : personne ne vous en voudra d'être trop poli.","lit":"toi · comment-tu-es","say":{"Sen":"Sen","siz":"siz","Siz":"Siz","nasılsın ?":"nasılsın?","nasılsınız ?":"nasılsınız?","sen diyelim mi ?":"sen diyelim mi?","teyze":"teyze"}}},{"title":"Une invitation à dîner","phrases":[{"fr":"Viens dîner chez nous samedi !","tgt":"Cumartesi akşam yemeğine bize gel!","lit":"samedi · soir · repas-son-à · nous-à · viens"},{"fr":"Avec plaisir ! Vers quelle heure ?","tgt":"Memnuniyetle! Saat kaç gibi?","lit":"plaisir-avec · heure · combien · vers"},{"fr":"Vers huit heures, ça te va ?","tgt":"Sekiz gibi, uygun mu?","lit":"huit · vers · convenable · [question]"},{"fr":"Parfait, j'apporte quelque chose ?","tgt":"Harika, bir şey getireyim mi?","lit":"génial · une · chose · apporter-que-je · [question]"},{"fr":"Non, viens simplement, c'est tout.","tgt":"Hayır, sadece sen gel.","lit":"non · seulement · toi · viens"},{"fr":"Mon mari prépare des kebabs.","tgt":"Eşim kebap yapıyor.","lit":"époux-mon · kebab · faire-[présent]-il"},{"fr":"Notre maison est près du parc Kuğulu.","tgt":"Evimiz Kuğulu Park'a yakın.","lit":"maison-notre · Kuğulu · parc-à · proche"},{"fr":"Tu as notre numéro de téléphone ?","tgt":"Telefon numaramız sende var mı?","lit":"téléphone · numéro-notre · toi-chez · il-y-a · [question]"},{"fr":"Oui, je l'ai.","tgt":"Evet, var.","lit":"oui · il-y-a"},{"fr":"À samedi, alors !","tgt":"O zaman cumartesi görüşürüz!","lit":"ce · temps · samedi · on-se-voit"}]},{"title":"Le dîner de kebab","phrases":[{"fr":"Ce kebab est délicieux !","tgt":"Bu kebap çok lezzetli!","lit":"ce · kebab · très · délicieux"},{"fr":"Le kebab d'Adana est plus épicé.","tgt":"Adana kebabı daha acı.","lit":"Adana · kebab-son · plus · piquant"},{"fr":"Le kebab d'Urfa est moins piquant.","tgt":"Urfa kebabı daha az acı.","lit":"Urfa · kebab-son · plus · peu · piquant"},{"fr":"Quel est ton plat préféré ?","tgt":"En sevdiğin yemek ne?","lit":"le-plus · aimé-ton · plat · quoi"},{"fr":"Le plat le plus connu, c'est le kebab.","tgt":"En ünlü yemek kebap.","lit":"le-plus · célèbre · plat · kebab"},{"fr":"Ta cuisine est meilleure que celle du restaurant.","tgt":"Senin yemeğin restorandan daha güzel.","lit":"ton · plat-ton · restaurant-que · plus · bon"},{"fr":"C'est le meilleur dîner de ma vie !","tgt":"Hayatımın en güzel akşam yemeği!","lit":"vie-ma-de · le-plus · beau · soir · repas-son"},{"fr":"Encore un peu de riz ?","tgt":"Biraz daha pilav?","lit":"un-peu · plus · riz"},{"fr":"Merci, je n'ai plus faim.","tgt":"Teşekkürler, artık tokum.","lit":"merci · désormais · rassasié-je-suis"},{"fr":"Avec le kebab, le meilleur, c'est l'ayran.","tgt":"Kebabın yanında en iyisi ayran.","lit":"kebab-de · côté-son-à · le-plus · bon-son · ayran"}],"tip":{"title":"Comparer : « daha » et « en », plus et le plus","example":"Le kebab d'Adana est plus épicé. — Adana kebabı <b>daha</b> acı.","body":"Pour comparer, le turc est très simple : on met « daha », plus, devant l'adjectif. « Acı » veut dire piquant, et « daha acı », plus piquant. Ce à quoi on compare prend la terminaison « dan » ou « den », qui joue le rôle de notre que : « restorandan daha güzel », mot à mot restaurant-que plus bon. Pour le superlatif, on remplace « daha » par « en », le plus : « en güzel », le plus beau, « en iyi », le meilleur. Et pour dire moins, on dit « daha az », mot à mot plus peu. L'adjectif lui-même ne change jamais, il n'y a ni masculin ni féminin. Astuce : « en » est le mot du premier, comme celui qui est en tête de la course.","lit":"Adana · kebab-son · plus · piquant","say":{"daha":"daha","en":"en","Acı":"Acı","daha acı":"daha acı","restorandan daha güzel":"restorandan daha güzel","en güzel":"en güzel","en iyi":"en iyi","daha az":"daha az"}}},{"title":"Le baklava du dessert","phrases":[{"fr":"Voici le dessert : du baklava !","tgt":"İşte tatlı: baklava!","lit":"voici · dessert · baklava"},{"fr":"Ce baklava vient de Gaziantep.","tgt":"Bu baklava Gaziantep'ten.","lit":"ce · baklava · Gaziantep-de"},{"fr":"Il est à la pistache.","tgt":"Fıstıklı.","lit":"pistache-avec"},{"fr":"C'est très sucré, mais c'est bon.","tgt":"Çok tatlı ama güzel.","lit":"très · sucré · mais · bon"},{"fr":"Tu en veux encore un morceau ?","tgt":"Bir dilim daha ister misin?","lit":"une · tranche · encore · vouloir-[habituel] · [question]-tu"},{"fr":"Juste un petit morceau.","tgt":"Sadece küçük bir dilim.","lit":"seulement · petit · une · tranche"},{"fr":"Avec un café turc, c'est parfait.","tgt":"Türk kahvesiyle mükemmel.","lit":"turc · café-son-avec · parfait"},{"fr":"Je ne bois pas de café le soir.","tgt":"Akşamları kahve içmiyorum.","lit":"soir-les · café · boire-[ne… pas]-[présent]-je"},{"fr":"Alors un thé ?","tgt":"O zaman çay?","lit":"ce · temps · thé"},{"fr":"Tu fais vraiment très bien la cuisine.","tgt":"Gerçekten çok iyi yemek yapıyorsun.","lit":"vraiment · très · bien · repas · faire-[présent]-tu"}]},{"title":"Les loisirs","phrases":[{"fr":"Qu'est-ce que tu fais le week-end, d'habitude ?","tgt":"Hafta sonları genelde ne yapıyorsun?","lit":"semaine · fin-s-son · en-général · quoi · faire-[présent]-tu"},{"fr":"Je fais de la randonnée, parce que j'aime la nature.","tgt":"Yürüyüş yapıyorum, çünkü doğayı seviyorum.","lit":"marche · faire-[présent]-je · parce-que · nature-[objet] · aimer-[présent]-je"},{"fr":"Je ne regarde pas la télé, parce que c'est ennuyeux.","tgt":"Televizyon izlemiyorum, çünkü sıkıcı.","lit":"télévision · regarder-[ne… pas]-[présent]-je · parce-que · ennuyeux"},{"fr":"Pourquoi tu apprends le turc ?","tgt":"Neden Türkçe öğreniyorsun?","lit":"pourquoi · turc · apprendre-[présent]-tu"},{"fr":"Parce que j'habite à Ankara.","tgt":"Çünkü Ankara'da oturuyorum.","lit":"parce-que · Ankara-à · habiter-[présent]-je"},{"fr":"Je joue de la guitare.","tgt":"Gitar çalıyorum.","lit":"guitare · jouer-[présent]-je"},{"fr":"Je fais du yoga le matin, parce que c'est calme.","tgt":"Sabahları yoga yapıyorum, çünkü ortalık sakin.","lit":"matin-les · yoga · faire-[présent]-je · parce-que · alentours · calme"},{"fr":"Tu lis beaucoup ?","tgt":"Çok kitap okuyor musun?","lit":"beaucoup · livre · lire-[présent] · [question]-tu"},{"fr":"Oui, surtout dans le bus, parce que le trajet est long.","tgt":"Evet, özellikle otobüste, çünkü yol uzun.","lit":"oui · surtout · bus-dans · parce-que · trajet · long"},{"fr":"J'aime la cuisine turque, parce qu'elle est variée.","tgt":"Türk mutfağını seviyorum, çünkü çok çeşitli.","lit":"turc · cuisine-sa-[objet] · aimer-[présent]-je · parce-que · très · varié"}],"tip":{"title":"« Çünkü » : parce que","example":"Je fais de la randonnée, parce que j'aime la nature. — Yürüyüş yapıyorum, <b>çünkü</b> doğayı seviyorum.","body":"« Çünkü » veut dire parce que, et il fonctionne presque comme en français. On dit d'abord le fait, puis « çünkü », puis la raison : « yürüyüş yapıyorum, çünkü doğayı seviyorum », je fais de la marche, parce que j'aime la nature. Pour poser la question, on utilise « neden ? », pourquoi ? On peut répondre directement en commençant par « çünkü » : « çünkü Ankara'da oturuyorum », parce que j'habite à Ankara. C'est un mot très pratique pour un débutant, parce que la phrase qui suit reste une phrase normale, sans rien changer. Faites juste une petite pause avant de le dire, comme une virgule. Pour retenir, associez « neden ? » et « çünkü » : la question et la réponse vont toujours ensemble.","lit":"marche · faire-[présent]-je · parce-que · nature-[objet] · aimer-[présent]-je","say":{"Çünkü":"Çünkü","çünkü":"çünkü","yürüyüş yapıyorum, çünkü doğayı seviyorum":"yürüyüş yapıyorum, çünkü doğayı seviyorum","neden ?":"neden?","çünkü Ankara'da oturuyorum":"çünkü Ankara'da oturuyorum"}}},{"title":"Sport et musique","phrases":[{"fr":"Tu fais du sport ?","tgt":"Spor yapıyor musun?","lit":"sport · faire-[présent] · [question]-tu"},{"fr":"Je nage deux fois par semaine.","tgt":"Haftada iki kez yüzüyorum.","lit":"semaine-dans · deux · fois · nager-[présent]-je"},{"fr":"Mert joue au basket avec ses amis.","tgt":"Mert arkadaşlarıyla basketbol oynuyor.","lit":"Mert · ami-s-ses-avec · basket · jouer-[présent]-il"},{"fr":"Il y a un match ce soir.","tgt":"Bu akşam maç var.","lit":"ce · soir · match · il-y-a"},{"fr":"On le regarde ensemble ?","tgt":"Birlikte izleyelim mi?","lit":"ensemble · regardons · [question]"},{"fr":"Quelle musique tu écoutes ?","tgt":"Ne tür müzik dinliyorsun?","lit":"quel · genre · musique · écouter-[présent]-tu"},{"fr":"J'écoute beaucoup de pop turque.","tgt":"Çok Türkçe pop dinliyorum.","lit":"beaucoup · turc · pop · écouter-[présent]-je"},{"fr":"Tu connais le saz ?","tgt":"Sazı biliyor musun?","lit":"saz-[objet] · savoir-[présent] · [question]-tu"},{"fr":"C'est un instrument traditionnel turc.","tgt":"Geleneksel bir Türk çalgısı.","lit":"traditionnel · un · turc · instrument-son"},{"fr":"Mon voisin en joue tous les soirs.","tgt":"Komşum her akşam saz çalıyor.","lit":"voisin-mon · chaque · soir · saz · jouer-[présent]-il"}]},{"title":"Le week-end au parc","phrases":[{"fr":"Samedi, on va au parc Gençlik.","tgt":"Cumartesi Gençlik Parkı'na gidiyoruz.","lit":"samedi · Gençlik · parc-son-à · aller-[présent]-nous"},{"fr":"Elif vient aussi.","tgt":"Elif de geliyor.","lit":"Elif · aussi · venir-[présent]-elle"},{"fr":"J'apporte du pain et du fromage.","tgt":"Ekmek ve peynir getiriyorum.","lit":"pain · et · fromage · apporter-[présent]-je"},{"fr":"Moi aussi, j'apporte des fruits.","tgt":"Ben de meyve getiriyorum.","lit":"moi · aussi · fruit · apporter-[présent]-je"},{"fr":"Il fait beau, mais il y a du vent.","tgt":"Hava güzel ama rüzgâr var.","lit":"temps · beau · mais · vent · il-y-a"},{"fr":"Le parc est grand et très vert.","tgt":"Park büyük ve çok yeşil.","lit":"parc · grand · et · très · vert"},{"fr":"Il y a un lac et des barques.","tgt":"Bir göl ve kayıklar var.","lit":"un · lac · et · barque-s · il-y-a"},{"fr":"J'aime ce parc, mais il y a beaucoup de monde.","tgt":"Bu parkı seviyorum ama çok kalabalık.","lit":"ce · parc-[objet] · aimer-[présent]-je · mais · très · bondé"},{"fr":"Can vient aussi, mais un peu plus tard.","tgt":"Can da geliyor ama biraz geç.","lit":"Can · aussi · venir-[présent]-il · mais · un-peu · tard"},{"fr":"On revient aussi dimanche ?","tgt":"Pazar günü de gelelim mi?","lit":"dimanche · jour-son · aussi · venons · [question]"}],"tip":{"title":"« Ve », « ama », « de » : et, mais, aussi","example":"Moi aussi, j'apporte des fruits. — Ben <b>de</b> meyve getiriyorum.","body":"Trois petits mots suffisent pour enchaîner les idées. « Ve » veut dire et : « ekmek ve peynir », du pain et du fromage. « Ama » veut dire mais : « hava güzel ama rüzgâr var », il fait beau mais il y a du vent. Le plus étonnant, c'est « de », aussi : il se place juste après le mot concerné, jamais avant. « Ben de », c'est moi aussi, et « Elif de geliyor », Elif aussi vient. Ce « de » change de son pour suivre la voyelle du mot : on dit « Can da », Can aussi, avec un a. À l'oral, on fait une petite pause avant « ama », comme en français avant mais. Retenez « ben de » : c'est la réponse parfaite quand un ami dit qu'il a faim.","lit":"moi · aussi · fruit · apporter-[présent]-je","say":{"Ve":"Ve","ama":"ama","de":"de","ekmek ve peynir":"ekmek ve peynir","Ama":"Ama","hava güzel ama rüzgâr var":"hava güzel ama rüzgâr var","Ben de":"Ben de","Elif de geliyor":"Elif de geliyor","Can da":"Can da","ben de":"ben de"}}},{"title":"Un pique-nique au lac Eymir","phrases":[{"fr":"Ouf, il fait chaud aujourd'hui !","tgt":"Of, bugün hava çok sıcak!","lit":"ouf · aujourd'hui · temps · très · chaud"},{"fr":"Asseyons-nous sous cet arbre.","tgt":"Şu ağacın altına oturalım.","lit":"ce-là · arbre-de · dessous-son-à · asseyons-nous"},{"fr":"Le lac Eymir est magnifique.","tgt":"Eymir Gölü çok güzel.","lit":"Eymir · lac-son · très · beau"},{"fr":"Qui veut de la salade ?","tgt":"Kim salata istiyor?","lit":"qui · salade · vouloir-[présent]-il"},{"fr":"Moi, s'il te plaît !","tgt":"Ben, lütfen!","lit":"moi · s'il-te-plaît"},{"fr":"Où sont les verres ?","tgt":"Bardaklar nerede?","lit":"verre-s · où"},{"fr":"Ils sont dans le sac bleu.","tgt":"Mavi çantada.","lit":"bleu · sac-dans"},{"fr":"Les enfants jouent au ballon.","tgt":"Çocuklar top oynuyor.","lit":"enfant-s · ballon · jouer-[présent]-ils"},{"fr":"Je fais une petite sieste.","tgt":"Biraz kestiriyorum.","lit":"un-peu · faire-la-sieste-[présent]-je"},{"fr":"Quelle belle journée au bord du lac !","tgt":"Göl kenarında ne güzel bir gün!","lit":"lac · bord-son-à · quel · beau · un · jour"}]},{"title":"Chez mon ami","phrases":[{"fr":"Ce soir, je vais chez mon ami Mert.","tgt":"Bu akşam arkadaşım Mert'e gidiyorum.","lit":"ce · soir · ami-mon · Mert-à · aller-[présent]-je"},{"fr":"La maison de mon ami est très belle.","tgt":"Arkadaşımın evi çok güzel.","lit":"ami-mon-de · maison-sa · très · beau"},{"fr":"La mère de Mert prépare le dîner.","tgt":"Mert'in annesi akşam yemeği hazırlıyor.","lit":"Mert-de · mère-sa · soir · repas-son · préparer-[présent]-elle"},{"fr":"Le chat de la voisine est sur le balcon.","tgt":"Komşunun kedisi balkonda.","lit":"voisin-de · chat-son · balcon-sur"},{"fr":"C'est le vélo de ton frère ?","tgt":"Bu kardeşinin bisikleti mi?","lit":"ceci · frère-ton-de · vélo-son · [question]"},{"fr":"La chambre d'Elif est toute petite.","tgt":"Elif'in odası çok küçük.","lit":"Elif-de · chambre-sa · très · petit"},{"fr":"La vue de l'appartement est superbe.","tgt":"Dairenin manzarası harika.","lit":"appartement-de · vue-sa · génial"},{"fr":"Le jardin du voisin est plein de fleurs.","tgt":"Komşunun bahçesi çiçek dolu.","lit":"voisin-de · jardin-son · fleur · plein"},{"fr":"Le nom de la rue, c'est quoi déjà ?","tgt":"Sokağın adı neydi?","lit":"rue-de · nom-son · quoi-était"},{"fr":"Les amis de Mert sont très drôles.","tgt":"Mert'in arkadaşları çok komik.","lit":"Mert-de · ami-s-ses · très · drôle"}],"tip":{"title":"Le complément du nom : « arkadaşımın evi », la maison de mon ami","example":"La maison de mon ami est très belle. — <b>Arkadaşımın evi</b> çok güzel.","body":"En français, on dit la maison de mon ami, avec la maison en premier. En turc, c'est l'inverse : le propriétaire vient d'abord, puis la chose. Les deux mots portent chacun une petite terminaison. Le propriétaire prend « ın », qui veut dire de : « arkadaşımın », de mon ami. La chose prend « i », qui veut dire sa : « evi », sa maison. Mot à mot, « arkadaşımın evi », c'est donc de mon ami, sa maison. Avec un prénom, c'est pareil : « Mert'in annesi », la mère de Mert, mot à mot de Mert, sa mère. On retrouve cette logique en français familier quand on dit Mert, sa mère. Pour retenir, pensez toujours : d'abord à qui, ensuite quoi.","lit":"ami-mon-de · maison-sa · très · beau","say":{"arkadaşımın evi":"arkadaşımın evi","arkadaşımın":"arkadaşımın","evi":"evi","Mert'in annesi":"Mert'in annesi"}}},{"title":"Faire un compliment","phrases":[{"fr":"Ta robe est vraiment très jolie.","tgt":"Elbisen gerçekten çok güzel.","lit":"robe-ta · vraiment · très · beau"},{"fr":"Merci, c'est un cadeau de ma mère.","tgt":"Teşekkürler, annemin hediyesi.","lit":"merci · mère-ma-de · cadeau-son"},{"fr":"Ton turc est déjà très bon !","tgt":"Türkçen artık çok iyi!","lit":"turc-ton · désormais · très · bon"},{"fr":"Tu es gentil, mais je fais encore des fautes.","tgt":"Çok naziksin ama hâlâ hata yapıyorum.","lit":"très · gentil-tu-es · mais · encore · erreur · faire-[présent]-je"},{"fr":"Tout le monde fait des fautes.","tgt":"Herkes hata yapıyor.","lit":"tout-le-monde · erreur · faire-[présent]-il"},{"fr":"Ta maison est très lumineuse.","tgt":"Evin çok aydınlık.","lit":"maison-ta · très · lumineux"},{"fr":"Ta nouvelle coiffure est très belle.","tgt":"Yeni saçın çok güzel.","lit":"nouveau · cheveu-ton · très · beau"},{"fr":"Tu souris toujours.","tgt":"Hep gülümsüyorsun.","lit":"toujours · sourire-[présent]-tu"},{"fr":"Ça me fait très plaisir.","tgt":"Çok sevindim.","lit":"très · se-réjouir-[passé]-je"},{"fr":"Tu es une vraie amie.","tgt":"Sen gerçek bir arkadaşsın.","lit":"toi · vrai · un · ami-tu-es"}]},{"title":"Parler un peu turc","phrases":[{"fr":"Tu parles turc ?","tgt":"Türkçe konuşuyor musun?","lit":"turc · parler-[présent] · [question]-tu"},{"fr":"Oui, un peu.","tgt":"Evet, biraz.","lit":"oui · un-peu"},{"fr":"Je comprends un peu, mais je parle lentement.","tgt":"Biraz anlıyorum ama yavaş konuşuyorum.","lit":"un-peu · comprendre-[présent]-je · mais · lent · parler-[présent]-je"},{"fr":"Tu parles très vite !","tgt":"Çok hızlı konuşuyorsun!","lit":"très · rapide · parler-[présent]-tu"},{"fr":"Elif, parle un peu plus lentement, s'il te plaît.","tgt":"Elif, biraz daha yavaş konuş, lütfen.","lit":"Elif · un-peu · plus · lent · parle · s'il-te-plaît"},{"fr":"Je travaille beaucoup mon turc.","tgt":"Türkçeye çok çalışıyorum.","lit":"turc-à · beaucoup · travailler-[présent]-je"},{"fr":"J'ai un peu faim.","tgt":"Biraz acıktım.","lit":"un-peu · avoir-faim-[passé]-je"},{"fr":"Il y a beaucoup de monde ici.","tgt":"Burası çok kalabalık.","lit":"ici-ce · très · bondé"},{"fr":"Attends un peu !","tgt":"Biraz bekle!","lit":"un-peu · attends"},{"fr":"Merci beaucoup pour ton aide.","tgt":"Yardımın için çok teşekkürler.","lit":"aide-ton · pour · beaucoup · merci"}],"tip":{"title":"« Çok » et « biraz » : beaucoup, un peu","example":"Je comprends un peu, mais je parle lentement. — <b>Biraz</b> anlıyorum ama yavaş konuşuyorum.","body":"« Çok » et « biraz » sont deux mots qu'on utilise sans arrêt. « Çok » veut dire beaucoup, mais aussi très : « çok güzel », très beau, et « çok konuşuyorsun », tu parles beaucoup. « Biraz » veut dire un peu, et il vient de « bir », un, collé à « az », peu. Ces deux mots se placent avant ce qu'ils modifient, jamais après. « Biraz » adoucit aussi les demandes : « biraz bekle », attends un peu, est plus gentil que « bekle » tout seul. Avec « daha », on obtient « biraz daha », un peu plus, idéal à table ou pour demander de parler moins vite. Quand on vous demande si vous parlez turc, répondez fièrement « evet, biraz », oui, un peu.","lit":"un-peu · comprendre-[présent]-je · mais · lent · parler-[présent]-je","say":{"Çok":"Çok","biraz":"biraz","çok güzel":"çok güzel","çok konuşuyorsun":"çok konuşuyorsun","Biraz":"Biraz","az":"az","biraz bekle":"biraz bekle","bekle":"bekle","daha":"daha","biraz daha":"biraz daha","evet, biraz":"evet, biraz"}}},{"title":"Se dire au revoir après une soirée","phrases":[{"fr":"Il est tard, je dois rentrer chez moi.","tgt":"Geç oldu, eve gitmem lazım.","lit":"tard · devenir-[passé] · maison-à · aller-[action]-mon · nécessaire"},{"fr":"Déjà ? Reste encore un peu !","tgt":"Şimdiden mi? Biraz daha kal!","lit":"dès-maintenant · [question] · un-peu · plus · reste"},{"fr":"Merci pour cette belle soirée.","tgt":"Bu güzel akşam için teşekkürler.","lit":"ce · beau · soir · pour · merci"},{"fr":"Je t'appelle demain.","tgt":"Yarın ararım.","lit":"demain · appeler-[habituel]-je"},{"fr":"Envoie-moi un message quand tu arrives chez toi.","tgt":"Eve varınca bana mesaj at.","lit":"maison-à · arriver-quand · moi-à · message · lance"},{"fr":"Bonne nuit, et à demain !","tgt":"İyi geceler, yarın görüşürüz!","lit":"bon · nuit-s · demain · on-se-voit"},{"fr":"Dis bonjour à ta famille de ma part.","tgt":"Ailene selam söyle.","lit":"famille-ta-à · salut · dis"},{"fr":"Prends soin de toi.","tgt":"Kendine iyi bak.","lit":"toi-même-à · bien · regarde"},{"fr":"À bientôt, mon ami !","tgt":"Görüşürüz, dostum!","lit":"on-se-voit · ami-mon"},{"fr":"Notre porte t'est toujours ouverte.","tgt":"Kapımız sana her zaman açık.","lit":"porte-notre · toi-à · chaque · temps · ouvert"}]},{"title":"Fin du module : un bilan","phrases":[{"fr":"D'accord, ce module est fini !","tgt":"Tamam, bu modül bitti!","lit":"d'accord · ce · module · finir-[passé]"},{"fr":"On sait se présenter en turc.","tgt":"Türkçe kendimizi tanıtmayı biliyoruz.","lit":"turc · nous-mêmes-[objet] · présenter-[action]-[objet] · savoir-[présent]-nous"},{"fr":"On parle de la famille et des loisirs.","tgt":"Aileden ve hobilerden konuşuyoruz.","lit":"famille-de · et · loisir-s-de · parler-[présent]-nous"},{"fr":"Bref, on a maintenant des amis à Ankara !","tgt":"Yani artık Ankara'da arkadaşlarımız var!","lit":"bref · désormais · Ankara-à · ami-s-nos · il-y-a"},{"fr":"Le turc est difficile, mais très beau.","tgt":"Türkçe zor ama çok güzel.","lit":"turc · difficile · mais · très · beau"},{"fr":"Allez, on continue ensemble !","tgt":"Hadi, birlikte devam edelim!","lit":"allez · ensemble · continuation · faisons"},{"fr":"Le niveau deux commence bientôt.","tgt":"İkinci seviye yakında başlıyor.","lit":"deuxième · niveau · bientôt · commencer-[présent]-il"},{"fr":"C'est-à-dire de nouvelles phrases et de nouveaux mots.","tgt":"Yani yeni cümleler, yeni kelimeler.","lit":"c'est-à-dire · nouveau · phrase-s · nouveau · mot-s"},{"fr":"D'accord, on se retrouve au prochain module !","tgt":"Tamam, bir sonraki modülde görüşürüz!","lit":"d'accord · un · suivant · module-dans · on-se-voit"},{"fr":"Allez, à très bientôt !","tgt":"Hadi, yakında görüşürüz!","lit":"allez · bientôt · on-se-voit"}],"tip":{"title":"Les petits mots de la conversation : « yani », « tamam », « hadi »","example":"Bref, on a maintenant des amis à Ankara ! — <b>Yani</b> artık Ankara'da arkadaşlarımız var!","body":"Ces trois petits mots rendent votre turc vivant. « Tamam » veut dire d'accord : on l'entend partout, pour accepter, pour conclure ou pour rassurer. « Yani » signifie c'est-à-dire, ou bref : il sert à expliquer, ou à gagner une seconde pour réfléchir, comme notre euh ou disons. « Yani artık arkadaşlarımız var », bref, maintenant on a des amis. « Hadi » veut dire allez : « hadi gidelim », allez, on y va. On les place en début de phrase, avec une petite pause juste après. Ils ne changent jamais de forme, donc aucun risque de se tromper. Glissez un « tamam » ou un « hadi » dans vos phrases, et vos amis d'Ankara auront l'impression que vous parlez turc depuis toujours.","lit":"bref · désormais · Ankara-à · ami-s-nos · il-y-a","say":{"yani":"yani","tamam":"tamam","hadi":"hadi","Tamam":"Tamam","Yani":"Yani","Yani artık arkadaşlarımız var":"Yani artık arkadaşlarımız var","Hadi":"Hadi","hadi gidelim":"hadi gidelim"}}}]}]},{"id":2,"name":"Niveau 2","freeLessonsPerModule":{"1":3,"2":0,"3":0},"modules":[{"id":1,"name":"Le quotidien","desc":"La vie de tous les jours, avec un vocabulaire plus riche.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"S'installer à Bursa","phrases":[{"fr":"Nous vivons à Bursa depuis trois mois.","tgt":"Üç aydır Bursa'da yaşıyoruz."},{"fr":"Notre appartement donne sur le mont Uludağ.","tgt":"Dairemiz Uludağ'a bakıyor."},{"fr":"Le quartier est calme et les voisins sont très gentils.","tgt":"Mahalle sakin, komşular da çok nazik."},{"fr":"Le marché couvert est à dix minutes à pied de chez nous.","tgt":"Kapalıçarşı bize yürüyerek on dakika."},{"fr":"Le matin, je vais au bureau en métro.","tgt":"Sabahları işe metroyla gidiyorum."},{"fr":"Les habitants de Bursa sont très accueillants.","tgt":"Bursalılar çok misafirperver."},{"fr":"Je commence peu à peu à connaître la ville.","tgt":"Şehri yavaş yavaş tanımaya başlıyorum."},{"fr":"Y a-t-il un bon marché près de chez vous ?","tgt":"Evinize yakın iyi bir pazar var mı?"},{"fr":"Oui, le marché du mardi est juste derrière notre rue.","tgt":"Evet, salı pazarı tam sokağımızın arkasında."},{"fr":"Chaque jour, j'aime Bursa un peu plus.","tgt":"Bursa'yı her gün biraz daha çok seviyorum."}]},{"title":"Hier au marché couvert","phrases":[{"fr":"Hier, je suis allé au marché couvert.","tgt":"Dün Kapalıçarşı'ya gittim."},{"fr":"J'ai acheté un foulard en soie pour ma mère.","tgt":"Annem için ipek bir eşarp aldım."},{"fr":"Ensuite, nous avons bu un thé au Koza Han.","tgt":"Sonra Koza Han'da çay içtik."},{"fr":"Le vendeur nous a fait une petite réduction.","tgt":"Satıcı bize biraz indirim yaptı."},{"fr":"Combien avez-vous payé ce plateau en cuivre ?","tgt":"Bu bakır tepsiye kaç para verdiniz?"},{"fr":"J'ai payé deux cents livres turques.","tgt":"İki yüz Türk lirası verdim."},{"fr":"Avez-vous aussi vu les boutiques de marrons glacés ?","tgt":"Kestane şekeri dükkânlarını da gördünüz mü?"},{"fr":"Oui, j'en ai acheté une petite boîte.","tgt":"Evet, küçük bir kutu aldım."},{"fr":"Nous sommes rentrés à la maison vers six heures.","tgt":"Saat altıya doğru eve döndük."},{"fr":"C'était une très belle journée au marché.","tgt":"Çarşıda çok güzel bir gün geçirdik."}],"tip":{"title":"Le passé en « -di » : « geldim », je suis venu","example":"Hier, je suis allé au marché couvert. — Dün Kapalıçarşı'ya <b>gittim</b>.","body":"Pour raconter ce qui s'est passé, le turc ajoute « di » à la racine du verbe, puis la personne : « gel », venir, devient « geldim », je suis venu, et « geldik », nous sommes venus. Ce petit « di » suit la musique du mot : « aldım », j'ai acheté, « oldu », c'est arrivé, « gördüm », j'ai vu. Après une consonne dure comme t, ç ou k, il durcit et devient « ti » : « içtik », nous avons bu, « gittim », je suis allé. Décomposons « gittim » : « git », aller, puis « ti », le passé, puis « m », je. Pour vouvoyer, on termine par « niz » : « gördünüz », vous avez vu. Pour retenir, pensez au français « c'est dit » : avec « di », c'est fait, c'est passé.","lit":"hier · marché-couvert-à · aller-[passé]-je","say":{"geldim":"geldim","geldik":"geldik","aldım":"aldım","oldu":"oldu","gördüm":"gördüm","içtik":"içtik","gittim":"gittim","gördünüz":"gördünüz"}}},{"title":"La boulangerie du coin","phrases":[{"fr":"Chaque matin, je passe à la boulangerie du coin.","tgt":"Her sabah köşedeki fırına uğruyorum."},{"fr":"Le pain sort du four vers sept heures.","tgt":"Ekmek saat yedi civarında fırından çıkıyor."},{"fr":"Bonjour, je peux avoir un pain bien cuit ?","tgt":"Günaydın, iyi pişmiş bir ekmek alabilir miyim?"},{"fr":"Vos pide au sésame ont l'air délicieuses.","tgt":"Susamlı pideleriniz çok lezzetli görünüyor."},{"fr":"Il ne reste plus de poğaça au fromage, désolé.","tgt":"Peynirli poğaça kalmadı, kusura bakmayın."},{"fr":"Revenez demain matin, il y en aura des fraîches.","tgt":"Yarın sabah yine gelin, taze çıkacak."},{"fr":"Alors je vais prendre deux simits à la place.","tgt":"O zaman onun yerine iki simit alayım."},{"fr":"Ça fait combien pour le tout ?","tgt":"Hepsi ne kadar?"},{"fr":"Ça fait trente-cinq livres turques.","tgt":"Otuz beş Türk lirası."},{"fr":"Le boulanger me reconnaît déjà, c'est agréable.","tgt":"Fırıncı beni artık tanıyor, bu çok hoş."}]},{"title":"L'iskender du midi","phrases":[{"fr":"À midi, nous allons manger un iskender entre collègues.","tgt":"Öğlen iş arkadaşlarımızla İskender yemeye gidiyoruz."},{"fr":"L'iskender kebab est né ici, à Bursa.","tgt":"İskender kebap burada, Bursa'da doğdu."},{"fr":"Une portion et demie pour moi, s'il vous plaît.","tgt":"Bana bir buçuk porsiyon lütfen."},{"fr":"Le serveur verse le beurre fondu directement à table.","tgt":"Garson eritilmiş tereyağını masada döküyor."},{"fr":"Attention, le beurre est brûlant !","tgt":"Dikkat, tereyağı çok sıcak!"},{"fr":"Vous voulez un ayran avec votre plat ?","tgt":"Yanında ayran ister misiniz?"},{"fr":"Oui, et encore un peu de yaourt, s'il vous plaît.","tgt":"Evet, biraz daha yoğurt lütfen."},{"fr":"Après ce plat, je n'ai plus faim jusqu'au soir.","tgt":"Bu yemekten sonra akşama kadar acıkmam."},{"fr":"En dessert, on prend un kemalpaşa ?","tgt":"Tatlı olarak kemalpaşa alalım mı?"},{"fr":"Aujourd'hui, l'addition est pour moi.","tgt":"Bugün hesap benden."}]},{"title":"Les projets de la semaine","phrases":[{"fr":"Cette semaine, je serai très occupé.","tgt":"Bu hafta çok meşgul olacağım."},{"fr":"Lundi, je ferai les courses au marché.","tgt":"Pazartesi pazardan alışveriş yapacağım."},{"fr":"Mardi soir, nous irons au cinéma.","tgt":"Salı akşamı sinemaya gideceğiz."},{"fr":"Mercredi, ma sœur viendra d'Izmir.","tgt":"Çarşamba kız kardeşim İzmir'den gelecek."},{"fr":"Que ferez-vous jeudi après le travail ?","tgt":"Perşembe işten sonra ne yapacaksınız?"},{"fr":"Je me reposerai sans doute à la maison.","tgt":"Herhalde evde dinleneceğim."},{"fr":"Vendredi soir, nous irons dîner chez des amis.","tgt":"Cuma akşamı arkadaşlarımıza yemeğe gideceğiz."},{"fr":"Et samedi, je n'oublierai pas le hammam !","tgt":"Cumartesi de hamamı unutmayacağım!"},{"fr":"Dimanche, il fera beau, d'après la météo.","tgt":"Hava durumuna göre pazar günü hava güzel olacak."},{"fr":"Ce sera une semaine bien remplie.","tgt":"Dolu dolu bir hafta olacak."}],"tip":{"title":"Le futur en « -ecek » : « yapacağım », je ferai","example":"Mardi soir, nous irons au cinéma. — Salı akşamı sinemaya <b>gideceğiz</b>.","body":"Pour parler de ce qui va arriver, on ajoute « ecek » ou « acak » à la racine, selon la musique du verbe : « gelecek », il viendra, « yapacak », il fera. Avec je et nous, le k final s'adoucit et presque disparaît : on dit « yapacağım », je ferai, en allongeant un peu le a, et « gideceğiz », nous irons. Décomposons « gideceğiz » : « git », aller, qui s'adoucit en « gid », puis « ecek », le futur, puis « iz », nous. Pour vous, on dit « yapacaksınız », vous ferez. Dans la rue, vous entendrez souvent la forme raccourcie « yapıcam », très courante à l'oral entre amis. Astuce : « ecek » sonne comme un petit élan vers l'avant, comme le futur lui-même.","lit":"mardi · soir · cinéma-à · aller-[futur]-nous","say":{"yapacağım":"yapacağım","gelecek":"gelecek","yapacak":"yapacak","gideceğiz":"gideceğiz","yapacaksınız":"yapacaksınız"}}},{"title":"Le hammam du samedi","phrases":[{"fr":"Le samedi, je vais au hammam avec un ami.","tgt":"Cumartesileri bir arkadaşımla hamama gidiyorum."},{"fr":"Viens avec nous cette fois-ci !","tgt":"Bu sefer sen de bizimle gel!"},{"fr":"Entrez, posez vos affaires dans la cabine.","tgt":"Buyurun, eşyalarınızı kabine koyun."},{"fr":"Prenez cette serviette et ces sabots en bois.","tgt":"Bu peştemalı ve bu takunyaları alın."},{"fr":"Allongez-vous sur la grande pierre chaude.","tgt":"Sıcak göbek taşına uzanın."},{"fr":"Attendez un peu, le masseur arrive.","tgt":"Biraz bekleyin, tellak geliyor."},{"fr":"Détendez-vous et respirez profondément.","tgt":"Rahatlayın ve derin nefes alın."},{"fr":"Ça fait un bien fou après une longue semaine.","tgt":"Uzun bir haftadan sonra insana çok iyi geliyor."},{"fr":"Buvez un thé ou un sorbet avant de partir.","tgt":"Çıkmadan önce bir çay ya da şerbet için."},{"fr":"Reviens samedi prochain, on t'attend !","tgt":"Gelecek cumartesi yine gel, seni bekliyoruz!"}],"tip":{"title":"L'impératif : « gel », « gelin », viens, venez","example":"Viens avec nous cette fois-ci ! — Bu sefer sen de bizimle <b>gel</b>!","body":"Pour donner un ordre ou lancer une invitation, le turc est très simple : la racine seule suffit pour tutoyer, « gel », viens, « al », prends, « otur », assieds-toi. Pour vouvoyer, on ajoute « in » en suivant la musique du mot : « gelin », venez, « alın », prenez, « oturun », asseyez-vous. Dans « gelin », il y a donc « gel », venir, et « in », vous. Ce n'est pas brusque du tout : avec un sourire et « lütfen », s'il vous plaît, c'est parfaitement poli. Le mot « buyurun », je vous en prie, entrez, est l'impératif le plus aimable que vous entendrez partout. Astuce : la racine nue, c'est le verbe en tenue de hammam, sans rien autour.","lit":"ce · fois · toi · aussi · nous-avec · viens","say":{"gel":"gel","gelin":"gelin","al":"al","otur":"otur","alın":"alın","oturun":"oturun","lütfen":"lütfen","buyurun":"buyurun"}}},{"title":"Un rendez-vous chez le médecin","phrases":[{"fr":"J'ai pris rendez-vous chez le médecin pour dix heures.","tgt":"Saat on için doktordan randevu aldım."},{"fr":"Bonjour docteur, j'ai mal à la gorge depuis trois jours.","tgt":"Merhaba doktor bey, üç gündür boğazım ağrıyor."},{"fr":"Avez-vous aussi de la fièvre ?","tgt":"Ateşiniz de var mı?"},{"fr":"Oui, un peu, surtout le soir.","tgt":"Evet, biraz var, özellikle akşamları."},{"fr":"Ouvrez la bouche et dites « a ».","tgt":"Ağzınızı açın ve \"a\" deyin."},{"fr":"Votre gorge est un peu rouge.","tgt":"Boğazınız biraz kızarmış."},{"fr":"Je vais vous prescrire un sirop.","tgt":"Size bir şurup yazacağım."},{"fr":"Prenez-le trois fois par jour, après les repas.","tgt":"Günde üç kez, yemeklerden sonra için."},{"fr":"Allez-vous me donner un arrêt de travail ?","tgt":"Bana rapor verecek misiniz?"},{"fr":"Oui, reposez-vous deux jours à la maison.","tgt":"Evet, iki gün evde dinlenin."}]},{"title":"À la pharmacie de garde","phrases":[{"fr":"La pharmacie de garde est dans la rue d'à côté.","tgt":"Nöbetçi eczane yan sokakta."},{"fr":"Bonsoir, j'ai une ordonnance du docteur.","tgt":"İyi akşamlar, doktordan bir reçetem var."},{"fr":"Voici votre sirop et des pastilles pour la gorge.","tgt":"Buyurun, şurubunuz ve boğaz pastilleriniz."},{"fr":"Ces pastilles sont à la menthe ?","tgt":"Bu pastiller naneli mi?"},{"fr":"Oui, et elles soulagent très vite.","tgt":"Evet, ayrıca çok çabuk rahatlatıyor."},{"fr":"Avez-vous aussi quelque chose contre le mal de tête ?","tgt":"Baş ağrısı için de bir şeyiniz var mı?"},{"fr":"Ce médicament se vend sans ordonnance.","tgt":"Bu ilaç reçetesiz satılıyor."},{"fr":"Prenez-en deux par jour au maximum.","tgt":"Günde en fazla iki tane alın."},{"fr":"Combien ça coûte avec l'assurance ?","tgt":"Sigortayla ne kadar tutuyor?"},{"fr":"Rétablissez-vous vite !","tgt":"Geçmiş olsun!"}]},{"title":"Une journée au bureau","phrases":[{"fr":"Je travaille dans un bureau du quartier de Nilüfer.","tgt":"Nilüfer'de bir ofiste çalışıyorum."},{"fr":"La réunion du matin commence à neuf heures.","tgt":"Sabah toplantısı saat dokuzda başlıyor."},{"fr":"Aujourd'hui, j'ai beaucoup de courriels à lire.","tgt":"Bugün okumam gereken çok e-posta var."},{"fr":"Mon chef m'a demandé un rapport pour vendredi.","tgt":"Müdürüm cumaya kadar bir rapor istedi."},{"fr":"Pouvez-vous m'envoyer ce dossier avant midi ?","tgt":"Bu dosyayı öğlene kadar bana gönderebilir misiniz?"},{"fr":"Bien sûr, je vous l'envoie tout de suite.","tgt":"Tabii, hemen gönderiyorum."},{"fr":"Le livreur de thé passe toutes les heures.","tgt":"Çaycı her saat başı çay getiriyor."},{"fr":"Je quitte le bureau à cinq heures et demie.","tgt":"Beş buçukta işten çıkıyorum."},{"fr":"Le soir, il y a souvent des bouchons en ville.","tgt":"Akşamları şehirde genelde trafik oluyor."},{"fr":"Heureusement, le métro, lui, est rapide.","tgt":"Neyse ki metro hızlı."}]},{"title":"Les tâches ménagères","phrases":[{"fr":"Le dimanche matin, nous faisons le ménage ensemble.","tgt":"Pazar sabahları birlikte temizlik yapıyoruz."},{"fr":"Moi, je passe l'aspirateur dans le salon.","tgt":"Ben salonu süpürüyorum."},{"fr":"Mon mari fait la vaisselle après le petit déjeuner.","tgt":"Eşim kahvaltıdan sonra bulaşıkları yıkıyor."},{"fr":"Tu as étendu le linge ?","tgt":"Çamaşırları astın mı?"},{"fr":"Pas encore, la machine tourne toujours.","tgt":"Daha değil, makine hâlâ çalışıyor."},{"fr":"Il faut aussi faire laver les tapis avant l'hiver.","tgt":"Kıştan önce halıları da yıkatmamız lazım."},{"fr":"Les vitres sont vraiment sales.","tgt":"Camlar gerçekten çok kirli."},{"fr":"Je les nettoierai cet après-midi.","tgt":"Öğleden sonra onları sileceğim."},{"fr":"Qui va sortir la poubelle ce soir ?","tgt":"Bu akşam çöpü kim çıkaracak?"},{"fr":"Après tout ce travail, nous avons bien mérité un thé.","tgt":"Bunca işten sonra bir çayı hak ettik."}]},{"title":"Les voisins de l'immeuble","phrases":[{"fr":"La voisine du dessus nous a apporté des börek.","tgt":"Üst kattaki komşumuz bize börek getirdi."},{"fr":"En Turquie, on apporte à manger aux nouveaux voisins.","tgt":"Türkiye'de yeni komşulara yemek götürülür."},{"fr":"On ne rend jamais une assiette vide.","tgt":"Tabak asla boş geri verilmez."},{"fr":"Je vais lui préparer un gâteau à la française.","tgt":"Ona bir Fransız keki yapacağım."},{"fr":"Le concierge de l'immeuble s'appelle Ahmet Bey.","tgt":"Apartmanın kapıcısının adı Ahmet Bey."},{"fr":"Il dépose le pain devant notre porte chaque matin.","tgt":"Her sabah kapımıza ekmek bırakıyor."},{"fr":"Les enfants des voisins jouent dans la cour.","tgt":"Komşunun çocukları bahçede oynuyor."},{"fr":"Ce soir, nous sommes invités chez les voisins d'en face.","tgt":"Bu akşam karşı komşuya davetliyiz."},{"fr":"Que faut-il apporter quand on est invité ?","tgt":"Davete giderken ne götürmek gerekir?"},{"fr":"Des fleurs ou une boîte de loukoums, c'est parfait.","tgt":"Çiçek ya da bir kutu lokum çok iyi olur."}]},{"title":"Les nouvelles du quartier","phrases":[{"fr":"Tu as entendu ? La boulangerie a changé de propriétaire.","tgt":"Duydun mu? Fırın el değiştirmiş."},{"fr":"Il paraît que le nouveau boulanger est de Trabzon.","tgt":"Yeni fırıncı Trabzonluymuş."},{"fr":"Notre voisin a trouvé un nouveau travail, semble-t-il.","tgt":"Komşumuz yeni bir iş bulmuş."},{"fr":"On dit que le marché du mardi a déménagé.","tgt":"Salı pazarı başka yere taşınmış."},{"fr":"Oh, il a beaucoup neigé sur l'Uludağ cette nuit !","tgt":"Aa, bu gece Uludağ'a çok kar yağmış!"},{"fr":"Tiens, quelqu'un a réparé l'ascenseur.","tgt":"Bak, biri asansörü tamir etmiş."},{"fr":"Apparemment, le hammam est fermé samedi.","tgt":"Hamam cumartesi kapalıymış."},{"fr":"Je n'y étais pas, c'est ma voisine qui me l'a raconté.","tgt":"Ben orada değildim, komşum anlattı."},{"fr":"Comme votre fils a grandi !","tgt":"Oğlunuz ne kadar büyümüş!"},{"fr":"Les nouvelles circulent vite dans ce quartier.","tgt":"Bu mahallede haberler çabuk yayılıyor."}],"tip":{"title":"Le passé en « -miş » : ce qu'on a appris ou découvert","example":"Oh, il a beaucoup neigé sur l'Uludağ cette nuit ! — Aa, bu gece Uludağ'a çok kar <b>yağmış</b>!","body":"Le turc a un deuxième passé, en « miş », pour ce qu'on n'a pas vu soi-même : ce qu'on a entendu dire, ou ce qu'on découvre d'un coup. « Geldi » veut dire il est venu, et je l'ai vu ; « gelmiş » veut dire il est venu, paraît-il, ou tiens, il est venu. Décomposons « yağmış » : « yağ », tomber, pour la pluie ou la neige, puis « mış », le passé découvert. À l'oral, on le dit souvent avec un air surpris : « Oğlunuz ne kadar büyümüş ! », comme votre fils a grandi ! Le suffixe suit la musique du mot : « miş », « mış », « muş », « müş ». Astuce : « miş » sonne comme un murmure, comme une nouvelle chuchotée entre voisins.","lit":"oh · ce · nuit · Uludağ-sur · beaucoup · neige · tomber-[miş]","say":{"Geldi":"Geldi","gelmiş":"gelmiş","yağmış":"yağmış","Oğlunuz ne kadar büyümüş !":"Oğlunuz ne kadar büyümüş!"}}},{"title":"Un dimanche sur l'Uludağ","phrases":[{"fr":"Dimanche, nous sommes montés sur l'Uludağ en téléphérique.","tgt":"Pazar günü teleferikle Uludağ'a çıktık."},{"fr":"Le trajet dure environ vingt-cinq minutes.","tgt":"Yolculuk yaklaşık yirmi beş dakika sürüyor."},{"fr":"D'en haut, la vue sur la ville est magnifique.","tgt":"Yukarıdan şehrin manzarası muhteşem."},{"fr":"Là-haut, il fait beaucoup plus froid qu'en bas.","tgt":"Yukarısı aşağıdan çok daha soğuk."},{"fr":"Heureusement, j'avais pris un gros pull.","tgt":"Neyse ki yanıma kalın bir kazak almıştım."},{"fr":"Nous avons fait un barbecue dans la forêt.","tgt":"Ormanda mangal yaptık."},{"fr":"Les enfants ont joué dans la neige toute la journée.","tgt":"Çocuklar bütün gün karda oynadı."},{"fr":"En chemin, nous avons mangé des châtaignes grillées.","tgt":"Yolda kestane kebap yedik."},{"fr":"Avez-vous déjà fait du ski ici ?","tgt":"Burada hiç kayak yaptınız mı?"},{"fr":"Pas encore, mais j'essaierai cet hiver.","tgt":"Henüz değil ama bu kış deneyeceğim."}]},{"title":"Payer les factures","phrases":[{"fr":"La facture d'électricité est arrivée ce matin.","tgt":"Elektrik faturası bu sabah geldi."},{"fr":"Elle est plus élevée que le mois dernier.","tgt":"Geçen aydan daha yüksek."},{"fr":"Nous avons beaucoup fait marcher la chaudière.","tgt":"Kombiyi çok çalıştırdık."},{"fr":"Comment paie-t-on la facture d'eau ici ?","tgt":"Burada su faturası nasıl ödeniyor?"},{"fr":"Vous pouvez payer en ligne ou à la banque.","tgt":"İnternetten ya da bankadan ödeyebilirsiniz."},{"fr":"J'ai mis en place un prélèvement automatique.","tgt":"Otomatik ödeme talimatı verdim."},{"fr":"Le loyer est de douze mille livres turques par mois.","tgt":"Kira ayda on iki bin Türk lirası."},{"fr":"Nous le versons au propriétaire le premier du mois.","tgt":"Ayın birinde ev sahibine ödüyoruz."},{"fr":"Internet est-il compris dans les charges ?","tgt":"İnternet aidata dahil mi?"},{"fr":"Non, il faut prendre un abonnement à part.","tgt":"Hayır, ayrıca abone olmak gerekiyor."}]},{"title":"Cuisiner le soir","phrases":[{"fr":"Ce soir, je vais préparer des haricots blancs à la turque.","tgt":"Bu akşam kuru fasulye pişireceğim."},{"fr":"Il me faut des oignons, des tomates et des poivrons.","tgt":"Soğan, domates ve biber lazım."},{"fr":"As-tu acheté du riz pour le pilaf ?","tgt":"Pilav için pirinç aldın mı?"},{"fr":"Oui, il est dans le placard de gauche.","tgt":"Evet, soldaki dolapta."},{"fr":"Coupe les oignons pendant que je lave le riz.","tgt":"Ben pirinci yıkarken sen soğanları doğra."},{"fr":"Le plat doit mijoter une heure à feu doux.","tgt":"Yemeğin bir saat kısık ateşte pişmesi lazım."},{"fr":"Ça sent déjà très bon dans la cuisine.","tgt":"Mutfak şimdiden mis gibi kokuyor."},{"fr":"On le mange avec du pain et des légumes au vinaigre.","tgt":"Ekmek ve turşuyla yiyoruz."},{"fr":"C'est ma belle-mère qui m'a donné cette recette.","tgt":"Bu tarifi bana kayınvalidem verdi."},{"fr":"Tu peux mettre la table, s'il te plaît ?","tgt":"Sofrayı kurar mısın lütfen?"}]},{"title":"La machine à laver en panne","phrases":[{"fr":"La machine à laver ne marche plus depuis hier.","tgt":"Çamaşır makinesi dünden beri çalışmıyor."},{"fr":"L'eau ne s'évacue pas du tout.","tgt":"Su hiç boşalmıyor."},{"fr":"Ce matin, j'ai appelé le service de réparation.","tgt":"Bu sabah tamir servisini aradım."},{"fr":"Le technicien viendra demain entre deux et quatre heures.","tgt":"Teknisyen yarın saat iki ile dört arasında gelecek."},{"fr":"Serez-vous à la maison à ce moment-là ?","tgt":"O saatte evde olacak mısınız?"},{"fr":"Oui, demain je travaille de chez moi.","tgt":"Evet, yarın evden çalışıyorum."},{"fr":"Le filtre était complètement bouché.","tgt":"Filtre tamamen tıkanmıştı."},{"fr":"La réparation a coûté huit cents livres turques.","tgt":"Tamir sekiz yüz Türk lirası tuttu."},{"fr":"C'est moins cher qu'une machine neuve.","tgt":"Yeni bir makineden daha ucuz."},{"fr":"Maintenant, elle tourne comme au premier jour.","tgt":"Şimdi ilk günkü gibi çalışıyor."}]},{"title":"Un samedi à Cumalıkızık","phrases":[{"fr":"Samedi, nous avons visité le village de Cumalıkızık.","tgt":"Cumartesi Cumalıkızık köyünü gezdik."},{"fr":"Les vieilles maisons ottomanes y sont très bien conservées.","tgt":"Oradaki eski Osmanlı evleri çok iyi korunmuş."},{"fr":"Les ruelles pavées montent vers la colline.","tgt":"Taş sokaklar tepeye doğru çıkıyor."},{"fr":"Nous avons pris un grand petit déjeuner dans un jardin.","tgt":"Bir bahçede serpme kahvaltı yaptık."},{"fr":"Il y avait au moins vingt petites assiettes !","tgt":"En az yirmi küçük tabak vardı!"},{"fr":"La confiture de mûres était délicieuse.","tgt":"Dut reçeli çok lezzetliydi."},{"fr":"Une vieille dame vendait des pâtes faites maison.","tgt":"Bir teyze ev yapımı erişte satıyordu."},{"fr":"J'en ai rapporté deux paquets à la maison.","tgt":"Eve iki paket aldım."},{"fr":"On peut y aller en bus depuis le centre-ville.","tgt":"Şehir merkezinden oraya otobüsle gidilebiliyor."},{"fr":"Je recommande cette sortie à tout le monde.","tgt":"Bu geziyi herkese tavsiye ederim."}]},{"title":"Des collègues à dîner","phrases":[{"fr":"Nous avons invité trois collègues à dîner vendredi.","tgt":"Cuma akşamı üç iş arkadaşımızı yemeğe davet ettik."},{"fr":"Qu'est-ce qu'on va leur préparer ?","tgt":"Onlara ne hazırlayacağız?"},{"fr":"Faisons des mezzés et un poisson au four.","tgt":"Meze ve fırında balık yapalım."},{"fr":"Il faut acheter du poisson frais à Mudanya.","tgt":"Mudanya'dan taze balık almak lazım."},{"fr":"Prends aussi le pain et les fruits.","tgt":"Ekmekle meyveyi de al."},{"fr":"Les invités arrivent à huit heures.","tgt":"Misafirler saat sekizde geliyor."},{"fr":"Bienvenue, entrez donc !","tgt":"Hoş geldiniz, buyurun içeri!"},{"fr":"Ravis d'être là, quelle belle maison vous avez !","tgt":"Hoş bulduk, ne güzel bir eviniz var!"},{"fr":"Reprenez un peu de poisson, je vous en prie.","tgt":"Lütfen biraz daha balık alın."},{"fr":"C'était une soirée vraiment chaleureuse.","tgt":"Gerçekten çok samimi bir akşamdı."}]},{"title":"Une journée avec les enfants","phrases":[{"fr":"Ne fais pas ça, c'est dangereux !","tgt":"Yapma, tehlikeli!"},{"fr":"Ne cours pas dans les escaliers !","tgt":"Merdivenlerde koşma!"},{"fr":"Ne touche pas au four, il est chaud.","tgt":"Fırına dokunma, sıcak."},{"fr":"N'oublie pas ton manteau, il fait froid dehors.","tgt":"Montunu unutma, dışarısı soğuk."},{"fr":"Les enfants, ne mangez pas trop de bonbons.","tgt":"Çocuklar, çok fazla şeker yemeyin."},{"fr":"Ne vous inquiétez pas, ils sont avec moi.","tgt":"Merak etmeyin, onlar benimle."},{"fr":"Ne crie pas, ton petit frère dort.","tgt":"Bağırma, kardeşin uyuyor."},{"fr":"Range tes jouets avant le dîner.","tgt":"Akşam yemeğinden önce oyuncaklarını topla."},{"fr":"Les enfants veulent aller au parc botanique.","tgt":"Çocuklar botanik parkına gitmek istiyor."},{"fr":"D'accord, mais ne rentrons pas trop tard.","tgt":"Tamam ama çok geç dönmeyelim."}],"tip":{"title":"« Yapma » : l'interdiction, ne fais pas","example":"Ne cours pas dans les escaliers ! — Merdivenlerde <b>koşma</b>!","body":"Pour interdire, on glisse « me » ou « ma » juste après la racine du verbe : « yap », fais, devient « yapma », ne fais pas, et « gel », viens, devient « gelme », ne viens pas. Pour vouvoyer ou parler à plusieurs, on ajoute encore « yin » : « yapmayın », ne faites pas, « merak etmeyin », ne vous inquiétez pas. Décomposons « koşma » : « koş », courir, puis « ma », la négation, et c'est tout. Attention à l'accent : on appuie sur la syllabe juste avant la négation, on dit « YAP-ma » et non « yap-MA ». Le mot que vous entendrez le plus souvent est « unutma », n'oublie pas. Astuce : ce « ma », c'est la main levée qui dit stop.","lit":"escaliers-dans · courir-[ne… pas]","say":{"Yapma":"Yapma","yapma":"yapma","gelme":"gelme","yapmayın":"yapmayın","merak etmeyin":"merak etmeyin","koşma":"koşma","unutma":"unutma"}}},{"title":"Fin du module : un bilan","phrases":[{"fr":"Ce module sur la vie quotidienne est maintenant terminé.","tgt":"Gündelik hayat modülü artık bitti."},{"fr":"Vous savez raconter votre journée d'hier en turc.","tgt":"Artık dünkü gününüzü Türkçe anlatabiliyorsunuz."},{"fr":"Vous pouvez aussi parler de vos projets de la semaine.","tgt":"Haftalık planlarınızdan da bahsedebilirsiniz."},{"fr":"Le passé en « di » vous servira chaque jour.","tgt":"Di'li geçmiş zaman her gün işinize yarayacak."},{"fr":"Avec le passé en « miş », vous rapportez ce qu'on vous a dit.","tgt":"Miş'li geçmiş zamanla duyduklarınızı anlatıyorsunuz."},{"fr":"L'impératif vous aide au hammam comme chez le médecin.","tgt":"Emir kipi hamamda da doktorda da işinize yarıyor."},{"fr":"Au marché, à la boulangerie et au bureau, vous parlez avec aisance.","tgt":"Pazarda, fırında ve ofiste artık rahatça konuşabiliyorsunuz."},{"fr":"Réécoutez une ou deux fois les leçons difficiles.","tgt":"Zor dersleri bir iki kez daha dinleyin."},{"fr":"Le turc devient peu à peu votre langue de tous les jours.","tgt":"Türkçe yavaş yavaş gündelik diliniz oluyor."},{"fr":"Bravo, et à bientôt pour le prochain module !","tgt":"Tebrikler, bir sonraki modülde görüşmek üzere!"}]}]},{"id":2,"name":"En voyage","desc":"Des situations de voyage plus variées et plus complexes.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Le car de nuit vers la Cappadoce","phrases":[{"fr":"Ce soir, on part en Cappadoce en car de nuit.","tgt":"Bu akşam Kapadokya'ya gece otobüsüyle gidiyoruz."},{"fr":"Le car part de la gare routière à neuf heures.","tgt":"Otobüs otogardan saat dokuzda kalkıyor."},{"fr":"Le trajet dure à peu près onze heures.","tgt":"Yolculuk aşağı yukarı on bir saat sürüyor."},{"fr":"J'ai réservé deux sièges côte à côte.","tgt":"Yan yana iki koltuk ayırttım."},{"fr":"L'employé du car sert du thé et des biscuits.","tgt":"Görevli çay ve bisküvi ikram ediyor."},{"fr":"On fera une pause sur une aire de repos vers minuit.","tgt":"Gece yarısına doğru bir dinlenme tesisinde mola vereceğiz."},{"fr":"Je n'arrive pas du tout à dormir dans le car.","tgt":"Otobüste bir türlü uyuyamıyorum."},{"fr":"Vous avez apporté un oreiller pour la nuit ?","tgt":"Gece için yastık getirdiniz mi?"},{"fr":"On arrivera à Göreme tôt le matin.","tgt":"Göreme'ye sabah erkenden varacağız."},{"fr":"Au lever du jour, le paysage change complètement.","tgt":"Gün doğarken manzara tamamen değişiyor."}]},{"title":"Un hôtel creusé dans la roche","phrases":[{"fr":"Notre hôtel est creusé dans la roche.","tgt":"Otelimiz kayaya oyulmuş."},{"fr":"Bonjour, nous avons une réservation au nom de Martin.","tgt":"Merhaba, Martin adına rezervasyonumuz var."},{"fr":"Malheureusement, la chambre n'est pas encore prête.","tgt":"Maalesef oda henüz hazır değil."},{"fr":"Laissez vos valises à la réception, on les montera.","tgt":"Valizlerinizi resepsiyona bırakın, biz odaya çıkarırız."},{"fr":"À l'intérieur, il fait frais même en été.","tgt":"İçerisi yazın bile serin."},{"fr":"Les murs sont en pierre tendre.","tgt":"Duvarlar yumuşak taştan."},{"fr":"Depuis la terrasse, on voit toute la vallée.","tgt":"Terastan bütün vadi görünüyor."},{"fr":"Le petit-déjeuner est servi de sept heures à dix heures.","tgt":"Kahvaltı yediden ona kadar veriliyor."},{"fr":"Internet ne capte pas bien dans les chambres.","tgt":"Odalarda internet pek iyi çekmiyor."},{"fr":"C'est la première fois que je dors dans une grotte.","tgt":"İlk defa bir mağarada uyuyorum."}]},{"title":"Un guide qui connaît la région par cœur","phrases":[{"fr":"Notre guide s'appelle Mehmet, il est né à Ürgüp.","tgt":"Rehberimizin adı Mehmet, Ürgüp'te doğmuş."},{"fr":"Il se lève très tôt tous les matins.","tgt":"Her sabah çok erken kalkar."},{"fr":"Le matin, je bois toujours un thé bien fort.","tgt":"Sabahları hep demli bir çay içerim."},{"fr":"En général, les touristes arrivent en juin.","tgt":"Turistler genellikle haziranda gelir."},{"fr":"Ici, il ne pleut presque jamais en été.","tgt":"Burada yazın neredeyse hiç yağmur yağmaz."},{"fr":"Mehmet parle quatre langues.","tgt":"Mehmet dört dil konuşur."},{"fr":"Par ici, les gens dînent tôt.","tgt":"Buralarda insanlar akşam yemeğini erken yer."},{"fr":"Moi, je ne mange jamais de viande le soir.","tgt":"Ben akşamları hiç et yemem."},{"fr":"Le matin, vous buvez du café ou du thé ?","tgt":"Sabahları kahve mi içersiniz, çay mı?"},{"fr":"La nuit, il fait froid dans les vallées.","tgt":"Geceleri vadilerde hava soğuk olur."}],"tip":{"title":"L'aoriste : « içerim », ce qu'on fait d'habitude","example":"Le matin, je bois toujours un thé bien fort. — Sabahları hep demli bir çay <b>içerim</b>.","body":"Pour parler de ses habitudes, le turc a un temps spécial qu'on appelle l'aoriste. Il ne décrit pas ce qui se passe en ce moment, comme « içiyorum », je suis en train de boire, mais ce qu'on fait en général. On le reconnaît à l'oreille grâce à un petit « r » : « içerim », je bois d'habitude, « yerim », je mange, « gelir », il vient. Décomposons « içerim » : « iç », boire, puis « er », la marque de l'habitude, puis « im », je. Au négatif, le « r » disparaît et on entend « mez » ou « maz » : « içmem », je ne bois pas, « yemem », je ne mange pas. Astuce : pensez au « r » de « régulier », celui des choses qu'on fait tout le temps.","lit":"matins-les · toujours · bien-infusé · un · thé · boire-[habitude]-je","say":{"içerim":"içerim","içiyorum":"içiyorum","yerim":"yerim","gelir":"gelir","içmem":"içmem","yemem":"yemem"}}},{"title":"Les montgolfières au lever du soleil","phrases":[{"fr":"Le minibus vient nous chercher à quatre heures et demie.","tgt":"Minibüs bizi dört buçukta alacak."},{"fr":"Il fait encore nuit et il fait très froid.","tgt":"Hâlâ karanlık ve hava çok soğuk."},{"fr":"Les ballons se gonflent un par un.","tgt":"Balonlar birer birer şişiyor."},{"fr":"Notre nacelle transporte vingt personnes.","tgt":"Sepetimiz yirmi kişi taşıyor."},{"fr":"Le pilote nous explique les règles de sécurité.","tgt":"Pilot bize güvenlik kurallarını anlatıyor."},{"fr":"On monte doucement au-dessus des cheminées de fée.","tgt":"Peribacalarının üzerinde yavaş yavaş yükseliyoruz."},{"fr":"Regardez, le soleil se lève derrière les montagnes !","tgt":"Bakın, güneş dağların arkasından doğuyor!"},{"fr":"Il y a plus de cent ballons dans le ciel.","tgt":"Gökyüzünde yüzden fazla balon var."},{"fr":"Je n'ai pas eu peur du tout, j'en suis moi-même surpris.","tgt":"Hiç korkmadım, ben de şaşırdım."},{"fr":"À l'atterrissage, chacun reçoit un petit certificat.","tgt":"İnişte herkese küçük bir sertifika veriyorlar."}]},{"title":"Réserver une excursion","phrases":[{"fr":"Je peux réserver une excursion pour demain ?","tgt":"Yarın için bir tur ayırtabilir miyim?"},{"fr":"Bien sûr, vous pouvez choisir entre le circuit rouge et le circuit vert.","tgt":"Tabii, kırmızı turla yeşil tur arasında seçim yapabilirsiniz."},{"fr":"Est-ce qu'on peut payer par carte ?","tgt":"Kartla ödeyebilir miyiz?"},{"fr":"Les enfants peuvent venir aussi ?","tgt":"Çocuklar da gelebilir mi?"},{"fr":"Le minibus peut nous prendre devant l'hôtel ?","tgt":"Minibüs bizi otelin önünden alabilir mi?"},{"fr":"Le déjeuner est compris dans le prix.","tgt":"Öğle yemeği fiyata dahil."},{"fr":"Excusez-moi, je ne peux pas marcher longtemps.","tgt":"Kusura bakmayın, uzun süre yürüyemem."},{"fr":"Vous pouvez annuler jusqu'à la veille au soir.","tgt":"Bir önceki akşama kadar iptal edebilirsiniz."},{"fr":"Ça fait combien par personne ?","tgt":"Kişi başı ne kadar?"},{"fr":"Je peux vous laisser mon numéro de téléphone ?","tgt":"Size telefon numaramı bırakabilir miyim?"}],"tip":{"title":"« -ebilir » : pouvoir, « gidebilir miyim ? »","example":"Je peux réserver une excursion pour demain ? — Yarın için bir tur <b>ayırtabilir miyim</b>?","body":"En turc, « pouvoir » n'est pas un verbe à part : c'est un petit morceau qu'on colle au verbe, « ebil » ou « abil » selon les voyelles. « Gitmek », aller, devient « gidebilirim », je peux y aller. Pour demander la permission, on ajoute la petite question « mi » : « gidebilir miyim ? », est-ce que je peux y aller ? Décomposons : « gid », aller, « ebil », pouvoir, « ir », la marque du présent général, puis « miyim », est-ce que je. Au négatif, on entend simplement « eme » : « yürüyemem », je ne peux pas marcher, « gelemem », je ne peux pas venir. Astuce : quand vous entendez « bil » au milieu d'un verbe, pensez tout de suite à pouvoir.","lit":"demain · pour · un · tour · réserver-pouvoir · [question]-je","say":{"gidebilir miyim ?":"gidebilir miyim?","Gitmek":"Gitmek","gidebilirim":"gidebilirim","yürüyemem":"yürüyemem","gelemem":"gelemem"}}},{"title":"La ville souterraine","phrases":[{"fr":"La ville souterraine descend à plus de cinquante mètres.","tgt":"Yeraltı şehri elli metreden daha derine iniyor."},{"fr":"Les couloirs sont très étroits et très bas.","tgt":"Koridorlar çok dar ve çok alçak."},{"fr":"Baissez la tête en passant par ici.","tgt":"Buradan geçerken başınızı eğin."},{"fr":"Autrefois, des milliers de personnes vivaient ici.","tgt":"Eskiden burada binlerce insan yaşarmış."},{"fr":"Ils cachaient aussi leurs animaux sous terre.","tgt":"Hayvanlarını da yerin altında saklarlarmış."},{"fr":"Cette grosse pierre ronde servait de porte.","tgt":"Bu büyük yuvarlak taş kapı olarak kullanılıyormuş."},{"fr":"Il y avait même une cuisine et une cave.","tgt":"Hatta bir mutfak ve bir mahzen bile varmış."},{"fr":"Je me sens un peu à l'étroit là-dedans.","tgt":"Burada kendimi biraz sıkışmış hissediyorum."},{"fr":"L'air reste frais toute l'année.","tgt":"Hava bütün yıl serin kalıyor."},{"fr":"Remontons, j'ai besoin de voir un peu le ciel.","tgt":"Hadi yukarı çıkalım, biraz gökyüzü görmem lazım."}]},{"title":"Randonnée dans les vallées","phrases":[{"fr":"Aujourd'hui, on randonne dans la vallée des Roses.","tgt":"Bugün Güllüdere Vadisi'nde yürüyüş yapıyoruz."},{"fr":"Le sentier n'est pas bien balisé partout.","tgt":"Patika her yerde iyi işaretlenmemiş."},{"fr":"Il faut prendre beaucoup d'eau avec nous.","tgt":"Yanımıza bol su almamız lazım."},{"fr":"Les rochers changent de couleur avec la lumière.","tgt":"Kayalar ışığa göre renk değiştiriyor."},{"fr":"On a trouvé un vieux pigeonnier creusé dans la falaise.","tgt":"Kayalığa oyulmuş eski bir güvercinlik bulduk."},{"fr":"Un vieil homme vend du jus d'orange frais au bord du chemin.","tgt":"Yolun kenarında yaşlı bir adam taze portakal suyu satıyor."},{"fr":"Je crois qu'on s'est un peu perdus.","tgt":"Galiba biraz kaybolduk."},{"fr":"Excusez-moi, le village de Çavuşin, c'est par où ?","tgt":"Affedersiniz, Çavuşin köyü ne tarafta?"},{"fr":"Continuez tout droit, puis tournez à gauche une fois le pont passé.","tgt":"Dümdüz devam edin, köprüyü geçince sola dönün."},{"fr":"J'ai mal aux pieds, mais quelle vue !","tgt":"Ayaklarım ağrıyor ama ne manzara!"}]},{"title":"Si le vent se lève","phrases":[{"fr":"Si le vent est trop fort, les ballons ne décollent pas.","tgt":"Rüzgâr çok kuvvetliyse balonlar kalkmaz."},{"fr":"Notre vol de ce matin a été annulé.","tgt":"Bu sabahki uçuşumuz iptal edildi."},{"fr":"Si vous voulez, on peut le reporter à demain.","tgt":"İsterseniz yarına erteleyebiliriz."},{"fr":"Si demain il fait beau, on vole à l'aube.","tgt":"Yarın hava güzel olursa sabah erkenden uçarız."},{"fr":"Et s'il est encore annulé, on est remboursés ?","tgt":"Yine iptal olursa paramızı geri alır mıyız?"},{"fr":"Oui, si le vol n'a pas lieu, on vous rembourse tout.","tgt":"Evet, uçuş olmazsa bütün paranızı iade ediyoruz."},{"fr":"Si tu viens avec nous, je réserve trois places.","tgt":"Bizimle gelirsen üç yer ayırtırım."},{"fr":"Si on se lève tôt, on verra quand même les ballons depuis la colline.","tgt":"Erken kalkarsak balonları yine de tepeden görürüz."},{"fr":"Si vous avez froid, prenez une couverture.","tgt":"Üşürseniz bir battaniye alın."},{"fr":"C'est dommage, mais la sécurité passe avant tout.","tgt":"Yazık ama güvenlik her şeyden önce gelir."}],"tip":{"title":"La condition en « -se » : « gelirsen », si tu viens","example":"Si tu viens avec nous, je réserve trois places. — Bizimle <b>gelirsen</b> üç yer ayırtırım.","body":"Pour dire « si », le turc ne met pas de petit mot au début de la phrase : il colle « se » ou « sa » à la fin du verbe. « Gelirsen » veut dire si tu viens : « gel », venir, « ir », la marque du présent général, puis « sen », si tu. Avec vous, on dit « gelirseniz », et avec nous, « gelirsek ». La suite de la phrase vient ensuite, souvent à l'aoriste : « üç yer ayırtırım », je réserve trois places. Ça marche même sans verbe : « kuvvetliyse », s'il est fort. Astuce : en français le « si » ouvre la condition, en turc il la referme, comme une porte qu'on ferme derrière soi.","lit":"nous-avec · venir-[aoriste]-si-tu · trois · place · réserver-[aoriste]-je","say":{"gelirsen":"gelirsen","Gelirsen":"Gelirsen","gelirseniz":"gelirseniz","gelirsek":"gelirsek","üç yer ayırtırım":"üç yer ayırtırım","kuvvetliyse":"kuvvetliyse"}}},{"title":"Un atelier de poterie à Avanos","phrases":[{"fr":"Avanos est célèbre pour sa poterie.","tgt":"Avanos çömlekçiliğiyle ünlü."},{"fr":"Le potier fait tourner le tour avec son pied.","tgt":"Çömlekçi çarkı ayağıyla çeviriyor."},{"fr":"L'argile vient du fleuve Kızılırmak.","tgt":"Kil Kızılırmak'tan geliyor."},{"fr":"Vous voulez essayer ?","tgt":"Denemek ister misiniz?"},{"fr":"J'ai les mains pleines de boue !","tgt":"Ellerim çamur içinde!"},{"fr":"Mon vase ressemble plutôt à un bol.","tgt":"Benim vazom daha çok bir kâseye benziyor."},{"fr":"Ce métier se transmet de père en fils.","tgt":"Bu meslek babadan oğula geçiyor."},{"fr":"Ces assiettes peintes à la main sont superbes.","tgt":"Bu elle boyanmış tabaklar harika."},{"fr":"Vous pouvez l'emballer avec soin ?","tgt":"Dikkatlice paketler misiniz?"},{"fr":"Ça ne va pas se casser dans la valise ?","tgt":"Valizde kırılmaz, değil mi?"}]},{"title":"Un dîner de kebab en jarre","phrases":[{"fr":"Ce soir, on va goûter le kebab cuit en jarre.","tgt":"Bu akşam testi kebabı tadacağız."},{"fr":"La viande cuit pendant des heures dans un pot en terre.","tgt":"Et toprak bir çömlekte saatlerce pişiyor."},{"fr":"Le serveur casse la jarre devant nous.","tgt":"Garson testiyi önümüzde kırıyor."},{"fr":"Faites attention, c'est brûlant !","tgt":"Dikkat edin, çok sıcak!"},{"fr":"Je ne mange pas épicé, c'est possible sans piment ?","tgt":"Acı yemem, acısız olur mu?"},{"fr":"Comme dessert, je vous conseille la citrouille confite.","tgt":"Tatlı olarak size kabak tatlısı öneririm."},{"fr":"Ce sirop de raisin s'appelle le pekmez.","tgt":"Bu üzüm şurubunun adı pekmez."},{"fr":"Tout était délicieux, merci infiniment.","tgt":"Her şey çok lezzetliydi, çok teşekkürler."},{"fr":"On peut avoir l'addition ? On se lève tôt demain.","tgt":"Hesabı alabilir miyiz? Yarın erken kalkıyoruz."},{"fr":"On laisse un pourboire au serveur ?","tgt":"Garsona bahşiş bırakalım mı?"}]},{"title":"Se plaindre à la réception","phrases":[{"fr":"Excusez-moi, j'ai un problème avec ma chambre.","tgt":"Affedersiniz, odamla ilgili bir sorunum var."},{"fr":"Il n'y a pas d'eau chaude dans la douche.","tgt":"Duşta sıcak su yok."},{"fr":"La climatisation fait un bruit terrible.","tgt":"Klima korkunç bir ses çıkarıyor."},{"fr":"Les voisins ont fait du bruit toute la nuit.","tgt":"Yan odadakiler bütün gece gürültü yaptı."},{"fr":"On n'a pas fermé l'œil.","tgt":"Gözümüze uyku girmedi."},{"fr":"Les serviettes n'ont pas été changées.","tgt":"Havlular değiştirilmemiş."},{"fr":"J'avais réservé une chambre avec vue.","tgt":"Manzaralı bir oda ayırtmıştım."},{"fr":"Nous sommes vraiment désolés, on règle ça tout de suite.","tgt":"Çok özür dileriz, hemen hallediyoruz."},{"fr":"Ce soir, on vous donne une autre chambre.","tgt":"Bu akşam size başka bir oda veriyoruz."},{"fr":"Merci, c'est très aimable à vous.","tgt":"Teşekkürler, çok naziksiniz."}]},{"title":"Changer de programme","phrases":[{"fr":"Je veux voir le musée en plein air de Göreme.","tgt":"Göreme Açık Hava Müzesi'ni görmek istiyorum."},{"fr":"Nous voulons rester un jour de plus en Cappadoce.","tgt":"Kapadokya'da bir gün daha kalmak istiyoruz."},{"fr":"Je ne veux pas reprendre le car de nuit.","tgt":"Bir daha gece otobüsüne binmek istemiyorum."},{"fr":"Vous voulez changer la date de votre billet ?","tgt":"Biletinizin tarihini değiştirmek mi istiyorsunuz?"},{"fr":"Oui, je voudrais partir jeudi au lieu de mercredi.","tgt":"Evet, çarşamba yerine perşembe gitmek istiyorum."},{"fr":"Il reste encore des places pour jeudi soir.","tgt":"Perşembe akşamı için hâlâ yer var."},{"fr":"Ma femme veut essayer le hammam de l'hôtel.","tgt":"Eşim otelin hamamını denemek istiyor."},{"fr":"Et moi, je veux juste dormir un peu.","tgt":"Ben de sadece biraz uyumak istiyorum."},{"fr":"Il faut payer une différence de cent livres turques.","tgt":"Yüz Türk lirası fark ödemeniz gerekiyor."},{"fr":"Pas de problème, on veut profiter un peu plus.","tgt":"Sorun değil, biraz daha keyif yapmak istiyoruz."}],"tip":{"title":"« Görmek istiyorum » : l'infinitif après vouloir","example":"Je veux voir le musée en plein air de Göreme. — Göreme Açık Hava Müzesi'ni <b>görmek istiyorum</b>.","body":"Pour dire « je veux faire quelque chose », le turc fait comme le français : un infinitif, puis le verbe vouloir. Mais l'ordre est inversé : l'infinitif d'abord, et « istiyorum », je veux, tout à la fin. L'infinitif se termine toujours par « mek » ou « mak » : « görmek », voir, « kalmak », rester, « uyumak », dormir. Décomposons « bir gün daha kalmak istiyoruz » : un, jour, de plus, rester, nous voulons. Pour la négation, c'est vouloir qui change : « binmek istemiyorum », je ne veux pas monter. Astuce : dites d'abord ce que vous voulez faire, et gardez « je veux » pour la fin, comme une signature.","lit":"Göreme · ouvert · air · musée-[COD] · voir · vouloir-je","say":{"Görmek istiyorum":"Görmek istiyorum","istiyorum":"istiyorum","görmek":"görmek","kalmak":"kalmak","uyumak":"uyumak","bir gün daha kalmak istiyoruz":"bir gün daha kalmak istiyoruz","binmek istemiyorum":"binmek istemiyorum"}}},{"title":"En route vers Pamukkale","phrases":[{"fr":"Ce soir, on quitte la Cappadoce pour Pamukkale.","tgt":"Bu akşam Kapadokya'dan ayrılıp Pamukkale'ye gidiyoruz."},{"fr":"Le car arrive à Denizli vers sept heures.","tgt":"Otobüs saat yedi gibi Denizli'ye varıyor."},{"fr":"De là, un minibus nous emmène au village.","tgt":"Oradan bir minibüs bizi köye götürüyor."},{"fr":"À quelle heure part le prochain minibus ?","tgt":"Bir sonraki minibüs saat kaçta kalkıyor?"},{"fr":"Il y en a un toutes les demi-heures.","tgt":"Her yarım saatte bir tane var."},{"fr":"Le chauffeur a oublié de nous réveiller !","tgt":"Şoför bizi uyandırmayı unuttu!"},{"fr":"Heureusement, ma voisine de siège m'a prévenu.","tgt":"Neyse ki yanımdaki kadın beni uyardı."},{"fr":"Où est-ce que je peux acheter un ticket ?","tgt":"Nereden bilet alabilirim?"},{"fr":"Vous payez directement le chauffeur.","tgt":"Parayı doğrudan şoföre veriyorsunuz."},{"fr":"On voit déjà les pentes blanches au loin.","tgt":"Uzaktaki beyaz yamaçlar şimdiden görünüyor."}]},{"title":"Les terrasses blanches","phrases":[{"fr":"Les terrasses blanches ressemblent à de la neige.","tgt":"Beyaz teraslar kara benziyor."},{"fr":"En fait, ce n'est pas de la neige, c'est du calcaire.","tgt":"Aslında bu kar değil, kireç taşı."},{"fr":"Il faut enlever ses chaussures pour marcher dessus.","tgt":"Üstünde yürümek için ayakkabıları çıkarmak gerekiyor."},{"fr":"Le sol est un peu glissant par endroits.","tgt":"Zemin yer yer biraz kaygan."},{"fr":"L'eau tiède coule dans les bassins.","tgt":"Ilık su havuzlara akıyor."},{"fr":"Ne sortez pas du chemin, s'il vous plaît.","tgt":"Lütfen yolun dışına çıkmayın."},{"fr":"Le gardien siffle les touristes imprudents.","tgt":"Bekçi dikkatsiz turistlere düdük çalıyor."},{"fr":"En fin d'après-midi, la lumière est magnifique.","tgt":"Akşamüstü ışık muhteşem oluyor."},{"fr":"Vous pouvez me prendre en photo devant ce bassin turquoise ?","tgt":"Beni şu turkuaz havuzun önünde çeker misiniz?"},{"fr":"On se croirait sur une autre planète.","tgt":"Sanki başka bir gezegendeyiz."}]},{"title":"La piscine antique et les sources chaudes","phrases":[{"fr":"Il est possible de nager dans la piscine antique.","tgt":"Antik havuzda yüzmek mümkün."},{"fr":"L'eau est à trente-cinq degrés toute l'année.","tgt":"Su bütün yıl otuz beş derece."},{"fr":"De vieilles colonnes reposent au fond de l'eau.","tgt":"Suyun dibinde eski sütunlar yatıyor."},{"fr":"L'entrée de la piscine se paie à part.","tgt":"Havuzun girişi ayrıca ücretli."},{"fr":"Il y a des vestiaires et des casiers.","tgt":"Soyunma odaları ve dolaplar var."},{"fr":"N'oubliez pas votre maillot de bain !","tgt":"Mayonuzu unutmayın!"},{"fr":"On dit que cette eau est bonne pour la peau.","tgt":"Derler ki bu su cilde iyi gelir."},{"fr":"Ça fait une heure que je suis dans l'eau, tous mes muscles sont détendus.","tgt":"Bir saattir sudayım, bütün kaslarım gevşedi."},{"fr":"Les bulles chatouillent les jambes.","tgt":"Kabarcıklar bacakları gıdıklıyor."},{"fr":"C'est le plus beau moment de tout le voyage.","tgt":"Bu, bütün yolculuğun en güzel anı."}]},{"title":"Une journée à Hiérapolis","phrases":[{"fr":"Avant le petit-déjeuner, on va voir les terrasses désertes.","tgt":"Kahvaltıdan önce boş terasları görmeye gidiyoruz."},{"fr":"Après le petit-déjeuner, on visite la ville antique.","tgt":"Kahvaltıdan sonra antik kenti geziyoruz."},{"fr":"Le théâtre antique se trouve en haut de la colline.","tgt":"Antik tiyatro tepenin üst tarafında."},{"fr":"Il faut y monter avant midi, après il fait trop chaud.","tgt":"Oraya öğleden önce çıkmak lazım, sonra hava çok ısınıyor."},{"fr":"On déjeune après la visite du musée.","tgt":"Müze gezisinden sonra öğle yemeği yiyoruz."},{"fr":"Avant de partir, achetons de l'eau.","tgt":"Yola çıkmadan önce su alalım."},{"fr":"Après le coucher du soleil, les terrasses deviennent roses.","tgt":"Gün batımından sonra teraslar pembeleşiyor."},{"fr":"On libère la chambre deux heures avant le départ.","tgt":"Kalkıştan iki saat önce odayı boşaltıyoruz."},{"fr":"Après une journée pareille, je m'endors tout de suite.","tgt":"Böyle bir günden sonra hemen uyurum."},{"fr":"Les ruines s'étendent sur des kilomètres.","tgt":"Kalıntılar kilometrelerce uzanıyor."}],"tip":{"title":"« -den önce » et « -den sonra » : avant et après","example":"Après le petit-déjeuner, on visite la ville antique. — <b>Kahvaltıdan sonra</b> antik kenti geziyoruz.","body":"En turc, « avant » et « après » se placent après le mot, et non devant. On dit d'abord le nom avec le petit suffixe « den » ou « dan », qui veut dire « à partir de », puis « önce », avant, ou « sonra », après. « Kahvaltıdan sonra » se décompose ainsi : « kahvaltı », le petit-déjeuner, « dan », de, et « sonra », après. De la même façon, « öğleden önce » veut dire avant midi, et « müzeden sonra », après le musée. Avec un verbe, on entend « madan önce » : « çıkmadan önce », avant de partir. Astuce : pensez « du petit-déjeuner, après », et la phrase turque vient toute seule.","lit":"petit-déjeuner-de · après · antique · ville-[COD] · visiter-[présent]-nous","say":{"önce":"önce","sonra":"sonra","Kahvaltıdan sonra":"Kahvaltıdan sonra","kahvaltı":"kahvaltı","öğleden önce":"öğleden önce","müzeden sonra":"müzeden sonra","çıkmadan önce":"çıkmadan önce"}}},{"title":"Un sac oublié dans le minibus","phrases":[{"fr":"J'ai oublié mon sac dans le minibus !","tgt":"Çantamı minibüste unuttum!"},{"fr":"Qu'est-ce qu'il y avait dedans ?","tgt":"İçinde ne vardı?"},{"fr":"Mon passeport et mon appareil photo.","tgt":"Pasaportum ve fotoğraf makinem."},{"fr":"Vous avez le numéro de la compagnie ?","tgt":"Firmanın numarası sizde var mı?"},{"fr":"Je vais appeler le chauffeur tout de suite.","tgt":"Şoförü hemen arayacağım."},{"fr":"Le chauffeur dit que le sac est en sécurité.","tgt":"Şoför diyor ki çanta güvende."},{"fr":"Il paraît qu'il repasse par ici dans une heure.","tgt":"Bir saat içinde buradan tekrar geçecekmiş."},{"fr":"Ouf, j'ai vraiment eu très peur !","tgt":"Oh be, gerçekten çok korktum!"},{"fr":"Les gens d'ici sont vraiment serviables.","tgt":"Buradaki insanlar gerçekten çok yardımsever."},{"fr":"Désormais, je garderai toujours mon passeport sur moi.","tgt":"Bundan sonra pasaportumu hep üstümde taşıyacağım."}]},{"title":"Marchander des écharpes en soie","phrases":[{"fr":"Je cherche un petit cadeau pour ma mère.","tgt":"Annem için küçük bir hediye arıyorum."},{"fr":"Ces écharpes en soie viennent de Buldan, tout près d'ici.","tgt":"Bu ipek eşarplar hemen yakındaki Buldan'dan geliyor."},{"fr":"Combien coûte celle-là, la bleue ?","tgt":"Şu mavi olan kaç para?"},{"fr":"Trois cents livres turques, c'est un bon prix.","tgt":"Üç yüz Türk lirası, iyi bir fiyat."},{"fr":"C'est un peu cher, vous me faites une réduction ?","tgt":"Biraz pahalı, indirim yapar mısınız?"},{"fr":"Si vous en prenez deux, je vous les laisse à cinq cents.","tgt":"İki tane alırsanız ikisini beş yüze veririm."},{"fr":"D'accord, je prends la bleue et la verte.","tgt":"Tamam, mavisini de yeşilini de alıyorum."},{"fr":"Il y a un distributeur de billets par ici ?","tgt":"Buralarda bankamatik var mı?"},{"fr":"Vous pourriez me faire un paquet cadeau ?","tgt":"Hediye paketi yapar mısınız?"},{"fr":"Merci beaucoup, vos écharpes sont superbes.","tgt":"Çok teşekkürler, eşarplarınız çok güzel."}]},{"title":"Le dernier jour du circuit","phrases":[{"fr":"Aujourd'hui, c'est notre dernier jour en Turquie.","tgt":"Bugün Türkiye'deki son günümüz."},{"fr":"Notre avion décolle de Denizli demain matin.","tgt":"Uçağımız yarın sabah Denizli'den kalkıyor."},{"fr":"Il faut libérer la chambre avant onze heures.","tgt":"Odayı on birden önce boşaltmamız gerekiyor."},{"fr":"Vous pouvez nous appeler un taxi pour l'aéroport ?","tgt":"Bize havalimanı için bir taksi çağırabilir misiniz?"},{"fr":"Ma valise est devenue très lourde, à cause de tous ces cadeaux.","tgt":"Valizim çok ağırlaştı, hep bu hediyeler yüzünden."},{"fr":"On a fait beaucoup de route en dix jours.","tgt":"On günde çok yol yaptık."},{"fr":"Ce que j'ai préféré, ce sont les montgolfières.","tgt":"En çok balonları sevdim."},{"fr":"Moi, j'ai adoré les sources chaudes.","tgt":"Bense sıcak su kaynaklarına bayıldım."},{"fr":"Si on revient, on visitera aussi Éphèse.","tgt":"Bir daha gelirsek Efes'i de görürüz."},{"fr":"Au revoir la Turquie, et à bientôt !","tgt":"Hoşça kal Türkiye, yakında görüşürüz!"}]},{"title":"Fin du module : un bilan","phrases":[{"fr":"Dans ce module, on a voyagé de la Cappadoce à Pamukkale.","tgt":"Bu modülde Kapadokya'dan Pamukkale'ye yolculuk ettik."},{"fr":"En turc, on sait maintenant réserver, se plaindre et changer de programme.","tgt":"Artık Türkçe rezervasyon yapabiliyor, şikâyet edebiliyor ve programı değiştirebiliyoruz."},{"fr":"L'aoriste nous sert à raconter nos habitudes.","tgt":"Geniş zaman, alışkanlıklarımızı anlatmaya yarıyor."},{"fr":"Avec « gidebilir miyim », on demande poliment la permission.","tgt":"\"Gidebilir miyim\" ile kibarca izin istiyoruz."},{"fr":"Les phrases avec une condition ne nous font plus peur.","tgt":"Artık şartlı cümlelerden korkmuyoruz."},{"fr":"Je parle turc bien plus facilement qu'aux premiers jours.","tgt":"Artık Türkçeyi ilk günlere göre çok daha rahat konuşuyorum."},{"fr":"Chaque étape du circuit nous a appris de nouveaux mots.","tgt":"Gezinin her durağı bize yeni kelimeler öğretti."},{"fr":"Bravo, vous avez fait beaucoup de chemin.","tgt":"Tebrikler, çok yol aldınız."},{"fr":"Maintenant, on a bien mérité un peu de repos.","tgt":"Şimdi biraz dinlenmeyi hak ettik."},{"fr":"Rendez-vous au prochain module pour bavarder avec les gens.","tgt":"İnsanlarla sohbet etmek için bir sonraki modülde görüşürüz."}]}]},{"id":3,"name":"Conversation sociale","desc":"Des échanges sociaux plus nuancés et plus naturels.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Retrouvailles sur le Kordon","phrases":[{"fr":"Salut ! Ça fait une éternité qu'on ne s'est pas vus.","tgt":"Selam! Görüşmeyeli uzun zaman oldu."},{"fr":"Tu n'as pas changé du tout, dis donc.","tgt":"Hiç değişmemişsin."},{"fr":"On s'assoit un peu face à la mer ?","tgt":"Biraz denize karşı oturalım mı?"},{"fr":"Le coucher de soleil est magnifique ce soir.","tgt":"Bu akşam gün batımı muhteşem."},{"fr":"Je suis arrivé à Izmir hier soir.","tgt":"Dün akşam İzmir'e geldim."},{"fr":"Tu restes combien de temps cette fois-ci ?","tgt":"Bu sefer ne kadar kalacaksın?"},{"fr":"Deux semaines, jusqu'à la fin du mois.","tgt":"İki hafta, ay sonuna kadar kalacağım."},{"fr":"Le Kordon est toujours aussi animé le soir.","tgt":"Kordon akşamları hâlâ çok hareketli."},{"fr":"Prenons un thé chacun, c'est moi qui invite.","tgt":"Birer çay içelim, benden."},{"fr":"Ça me fait vraiment plaisir de te revoir.","tgt":"Seni tekrar gördüğüme çok sevindim."}]},{"title":"Prendre des nouvelles","phrases":[{"fr":"Salut, quoi de neuf ?","tgt":"Selam, naber?"},{"fr":"Ça va bien, et toi, quoi de neuf ?","tgt":"İyidir, senden naber?"},{"fr":"Rien de spécial, comme d'habitude.","tgt":"Hiç, her zamanki gibi."},{"fr":"Et le boulot, quelles nouvelles ?","tgt":"İşlerden ne haber?"},{"fr":"Et ta sœur, tu as des nouvelles ?","tgt":"Kız kardeşinden ne haber?"},{"fr":"Ça roule, je ne me plains pas.","tgt":"İyi gidiyor, şikâyetim yok."},{"fr":"Tu es où, là, en ce moment ?","tgt":"Neredesin şu an?"},{"fr":"Je suis à Alsancak avec des copains.","tgt":"Alsancak'tayım, arkadaşlarlayım."},{"fr":"Viens toi aussi, on t'attend.","tgt":"Sen de gel, seni bekliyoruz."},{"fr":"D'accord, j'y suis dans dix minutes.","tgt":"Tamam, on dakikaya oradayım."}],"tip":{"title":"Le registre familier entre amis : « naber », « ne haber »","example":"Salut, quoi de neuf ? — Selam, <b>naber</b>?","body":"Entre amis, on ne dit presque jamais la longue formule polie pour demander comment ça va : on lance simplement « naber », qui veut dire quoi de neuf. C'est la contraction de « ne haber », littéralement quelle nouvelle, prononcé très vite jusqu'à ne faire qu'un seul mot, avec l'accent sur la fin : na-BER. La réponse typique est « iyidir », ça va bien, suivie de « senden naber », et toi quoi de neuf, mot à mot de toi quelle nouvelle. Pour demander des nouvelles de quelqu'un ou de quelque chose, on garde la forme complète après le nom : « işlerden ne haber », quelles nouvelles du travail. Retenez-le comme un salut de copains, à éviter avec votre banquier mais parfait sur le Kordon.","lit":"salut · quoi-nouvelle","say":{"naber":"naber","ne haber":"ne haber","iyidir":"iyidir","senden naber":"senden naber","işlerden ne haber":"işlerden ne haber"}}},{"title":"Une soirée meze","phrases":[{"fr":"Ce soir, on mange des meze au bord de la mer.","tgt":"Bu akşam deniz kenarında meze yiyoruz."},{"fr":"Qu'est-ce que tu prends comme meze ?","tgt":"Meze olarak ne alıyorsun?"},{"fr":"Je raffole des feuilles de vigne farcies.","tgt":"Yaprak sarmasına bayılırım."},{"fr":"Essaie cette salade d'aubergine, elle est délicieuse.","tgt":"Bu patlıcan salatasını bir dene, çok lezzetli."},{"fr":"Le serveur nous a apporté du pain tout chaud.","tgt":"Garson bize sıcacık ekmek getirdi."},{"fr":"On commande encore une assiette de fromage blanc ?","tgt":"Bir tabak daha beyaz peynir söyleyelim mi?"},{"fr":"Je n'avais jamais mangé de poulpe préparé comme ça.","tgt":"Ahtapotu hiç böyle yememiştim."},{"fr":"Ici, personne ne se presse à table.","tgt":"Burada sofrada kimse acele etmez."},{"fr":"C'est à Izmir qu'on fait les meilleures meze.","tgt":"En güzel mezeler İzmir'de yapılır."},{"fr":"Tu veux encore un peu de salade ?","tgt":"Biraz daha salata ister misin?"}]},{"title":"Du poisson grillé à Urla","phrases":[{"fr":"On va manger du poisson à Urla dimanche ?","tgt":"Pazar günü Urla'ya balık yemeye gidelim mi?"},{"fr":"Je connais un petit restaurant sur le port.","tgt":"Limanda küçük bir lokanta biliyorum."},{"fr":"Là-bas, le poisson arrive frais chaque matin.","tgt":"Orada balıklar her sabah taze geliyor."},{"fr":"Tu préfères la daurade ou le bar ?","tgt":"Çipura mı seversin, levrek mi?"},{"fr":"Moi, je vais prendre le bar grillé avec de la roquette.","tgt":"Ben ızgara levrek ve roka alacağım."},{"fr":"Presse un peu de citron dessus et mange.","tgt":"Üstüne biraz limon sıkıp ye."},{"fr":"Ce poisson est cuit à la perfection.","tgt":"Bu balık tam kıvamında pişmiş."},{"fr":"Après le repas, marchons jusqu'à la jetée.","tgt":"Yemekten sonra iskeleye kadar yürüyelim."},{"fr":"Cette fois, l'addition est pour moi.","tgt":"Bu sefer hesap benden."},{"fr":"Merci, c'était un repas inoubliable.","tgt":"Teşekkürler, unutulmaz bir yemekti."}]},{"title":"Des projets pas encore sûrs","phrases":[{"fr":"On ira peut-être à Çeşme ce week-end.","tgt":"Belki bu hafta sonu Çeşme'ye gideriz."},{"fr":"Il me semble qu'il va pleuvoir demain.","tgt":"Galiba yarın yağmur yağacak."},{"fr":"Peut-être que Selin viendra aussi.","tgt":"Belki Selin de gelir."},{"fr":"Je crois que la plage sera bondée.","tgt":"Galiba plaj çok kalabalık olacak."},{"fr":"On partira peut-être tôt le matin.","tgt":"Belki sabah erkenden çıkarız."},{"fr":"Il me semble que Murat a une voiture.","tgt":"Galiba Murat'ın arabası var."},{"fr":"Peut-être, mais je n'en suis pas certain.","tgt":"Belki, ama emin değilim."},{"fr":"Je crois que je me suis trompé de jour.","tgt":"Galiba günü karıştırdım."},{"fr":"Si tu es libre, appelle-moi samedi.","tgt":"Boşsan cumartesi beni ara."},{"fr":"Bon, on verra ce que ça donne.","tgt":"Neyse, bakalım ne olacak."}],"tip":{"title":"« Belki » et « galiba » : peut-être, il me semble","example":"Il me semble qu'il va pleuvoir demain. — <b>Galiba</b> yarın yağmur yağacak.","body":"Pour adoucir ce qu'on dit, le turc a deux petits mots très pratiques qui ne changent jamais de forme. « Belki » veut dire peut-être, et il s'accompagne très souvent de l'aoriste, ce présent des possibilités : « belki gelir », peut-être qu'il viendra. « Galiba » veut dire il me semble, je crois bien, et se place en général au début de la phrase : « galiba yarın yağmur yağacak », mot à mot il-me-semble demain pluie tombera. Contrairement au français, pas besoin de « que » ni de changer le verbe : on pose le mot devant, et la phrase reste normale. À l'oral, on peut même répondre d'un seul mot, « belki », ou « galiba », pour dire peut-être bien. Astuce : « galiba » sonne comme « gare, il y a ! », un doute qu'on lance en passant.","lit":"il-semble · demain · pluie · tombera","say":{"Belki":"Belki","galiba":"galiba","belki gelir":"belki gelir","Galiba":"Galiba","galiba yarın yağmur yağacak":"galiba yarın yağmur yağacak","belki":"belki"}}},{"title":"Souvenirs de vacances","phrases":[{"fr":"Tu te souviens de nos vacances à Ayvalık ?","tgt":"Ayvalık tatilimizi hatırlıyor musun?"},{"fr":"On avait loué une petite maison près de la plage.","tgt":"Plajın yakınında küçük bir ev kiralamıştık."},{"fr":"Chaque matin, on nageait avant le petit-déjeuner.","tgt":"Her sabah kahvaltıdan önce yüzerdik."},{"fr":"Tu avais pris un terrible coup de soleil.","tgt":"Sen fena halde güneşte yanmıştın."},{"fr":"Le soir, on jouait au backgammon sur la terrasse.","tgt":"Akşamları terasta tavla oynardık."},{"fr":"Ton frère perdait à chaque fois.","tgt":"Kardeşin her seferinde kaybederdi."},{"fr":"C'étaient les plus belles vacances de ma vie.","tgt":"Hayatımın en güzel tatiliydi."},{"fr":"J'ai encore toutes les photos dans mon téléphone.","tgt":"Bütün fotoğraflar hâlâ telefonumda."},{"fr":"Montre-les-moi, j'ai envie de les revoir.","tgt":"Göster bana, tekrar görmek istiyorum."},{"fr":"On devrait refaire ce voyage l'été prochain.","tgt":"Gelecek yaz o tatili tekrar yapmalıyız."}]},{"title":"Une invitation à dîner","phrases":[{"fr":"Tu fais quelque chose vendredi soir ?","tgt":"Cuma akşamı bir planın var mı?"},{"fr":"J'invite quelques amis à dîner chez moi.","tgt":"Evde birkaç arkadaşa yemek veriyorum."},{"fr":"J'aimerais beaucoup que tu viennes.","tgt":"Gelmeni çok isterim."},{"fr":"Avec grand plaisir, je viendrai.","tgt":"Memnuniyetle, gelirim."},{"fr":"Qu'est-ce que j'apporte ?","tgt":"Ne getireyim?"},{"fr":"N'apporte rien, ta présence suffit.","tgt":"Hiçbir şey getirme, kendin gel yeter."},{"fr":"J'apporterai quand même un dessert.","tgt":"Yine de bir tatlı getireceğim."},{"fr":"On se donne rendez-vous à quelle heure ?","tgt":"Saat kaçta buluşuyoruz?"},{"fr":"Vers huit heures, chez moi à Karşıyaka.","tgt":"Sekiz gibi, Karşıyaka'daki evimde."},{"fr":"Super, à vendredi alors !","tgt":"Süper, cuma görüşürüz o zaman!"}]},{"title":"Préparer un anniversaire","phrases":[{"fr":"C'est l'anniversaire de Deniz samedi prochain.","tgt":"Gelecek cumartesi Deniz'in doğum günü."},{"fr":"Et si on lui faisait une surprise ?","tgt":"Ona bir sürpriz yapsak mı?"},{"fr":"Bonne idée, mais il ne doit se douter de rien.","tgt":"İyi fikir, ama hiçbir şey bilmemeli."},{"fr":"Le gâteau, je m'en occupe.","tgt":"Pastayı ben hallederim."},{"fr":"Tu peux appeler les autres pour les inviter ?","tgt":"Diğerlerini arayıp davet eder misin?"},{"fr":"Qu'est-ce qu'on lui offre comme cadeau ?","tgt":"Ona hediye olarak ne alalım?"},{"fr":"Il parle tout le temps d'un appareil photo.","tgt":"Hep bir fotoğraf makinesinden bahsediyor."},{"fr":"Si chacun donne un peu, on pourra l'acheter.","tgt":"Herkes biraz verirse onu alabiliriz."},{"fr":"Quand il arrivera, on chantera tous ensemble.","tgt":"O gelince hep birlikte şarkı söyleyeceğiz."},{"fr":"Joyeux anniversaire, mon vieux !","tgt":"Doğum günün kutlu olsun, dostum!"}]},{"title":"Demander un petit service","phrases":[{"fr":"J'ai un petit service à te demander.","tgt":"Senden küçük bir ricam var."},{"fr":"Bien sûr, vas-y, dis-moi.","tgt":"Tabii, söyle."},{"fr":"Tu pourrais arroser mes plantes la semaine prochaine ?","tgt":"Gelecek hafta çiçeklerimi sular mısın?"},{"fr":"Je pars à Ankara pour le travail.","tgt":"İş için Ankara'ya gidiyorum."},{"fr":"Je laisserai les clés à la voisine.","tgt":"Anahtarları komşuya bırakırım."},{"fr":"Pas de souci, je passerai mardi et jeudi.","tgt":"Sorun değil, salı ve perşembe uğrarım."},{"fr":"Tu me sauves, merci beaucoup.","tgt":"Beni kurtardın, çok sağ ol."},{"fr":"C'est normal, entre amis on s'entraide.","tgt":"Ne demek, arkadaşlar birbirine yardım eder."},{"fr":"Je te rapporterai quelque chose d'Ankara.","tgt":"Sana Ankara'dan bir şey getiririm."},{"fr":"Ne t'embête pas avec ça, ce n'est rien.","tgt":"Zahmet etme, önemli değil."}]},{"title":"Des nouvelles de la famille","phrases":[{"fr":"Comment vont ta mère et ton père ?","tgt":"Annen baban nasıl?"},{"fr":"Ils vont bien, ils ont déménagé à Urla.","tgt":"İyiler, Urla'ya taşındılar."},{"fr":"Mon père s'est mis au jardinage.","tgt":"Babam bahçeyle uğraşmaya başladı."},{"fr":"Ma petite sœur s'est mariée en juin.","tgt":"Kız kardeşim haziranda evlendi."},{"fr":"Félicitations ! Je n'étais pas au courant.","tgt":"Tebrikler! Bilmiyordum."},{"fr":"Ils vont avoir un bébé au printemps.","tgt":"İlkbaharda bebekleri olacak."},{"fr":"Tu vas devenir tonton, alors !","tgt":"O zaman dayı olacaksın!"},{"fr":"Ma grand-mère vient d'avoir quatre-vingt-dix ans.","tgt":"Babaannem doksan yaşına girdi."},{"fr":"Elle est encore en pleine forme.","tgt":"Hâlâ turp gibi."},{"fr":"Passe-leur le bonjour de ma part.","tgt":"Hepsine benden selam söyle."}]},{"title":"Une balade à vélo à Urla","phrases":[{"fr":"On loue des vélos pour la journée ?","tgt":"Bugünlük bisiklet kiralayalım mı?"},{"fr":"La route passe entre les oliviers et les vignes.","tgt":"Yol zeytinliklerin ve bağların arasından geçiyor."},{"fr":"Attends-moi, je ne peux pas rouler aussi vite !","tgt":"Bekle beni, o kadar hızlı gidemiyorum!"},{"fr":"Arrêtons-nous un moment à l'ombre.","tgt":"Biraz gölgede duralım."},{"fr":"Tu n'as pas oublié l'eau, j'espère ?","tgt":"Su almayı unutmadın, değil mi?"},{"fr":"Le petit village là-bas s'appelle Barbaros.","tgt":"Oradaki küçük köyün adı Barbaros."},{"fr":"Il y a un café charmant sur la place.","tgt":"Meydanda şirin bir kafe var."},{"fr":"On y boit un thé, puis on repart.","tgt":"Orada bir çay içip yola devam ederiz."},{"fr":"Je n'ai plus de force dans les jambes !","tgt":"Bacaklarımda derman kalmadı!"},{"fr":"Allez, plus que trois kilomètres !","tgt":"Hadi, sadece üç kilometre kaldı."}]},{"title":"Rapporter ce qu'on a entendu","phrases":[{"fr":"Ayşe dit qu'elle sera un peu en retard.","tgt":"Ayşe diyor ki biraz geç kalacak."},{"fr":"Mon frère dit que le match était génial.","tgt":"Kardeşim diyor ki maç süpermiş."},{"fr":"Elle m'a dit qu'elle avait trouvé un nouveau travail.","tgt":"Bana yeni bir iş bulduğunu söyledi."},{"fr":"Murat dit qu'il ne peut pas venir ce soir.","tgt":"Murat diyor ki bu akşam gelemiyormuş."},{"fr":"Qu'est-ce qu'il a dit, exactement ?","tgt":"Tam olarak ne dedi?"},{"fr":"Il a dit : « Désolé, je suis malade. »","tgt":"Dedi ki: \"Kusura bakma, hastayım.\""},{"fr":"Ma mère dit toujours qu'il faut manger lentement.","tgt":"Annem hep der ki yavaş yemek lazım."},{"fr":"Le serveur dit que le poisson est très frais aujourd'hui.","tgt":"Garson diyor ki bugün balık çok tazeymiş."},{"fr":"On dit que ce café est le plus vieux d'Izmir.","tgt":"Derler ki bu kahvehane İzmir'in en eskisiymiş."},{"fr":"Je ne sais pas si c'est vrai.","tgt":"Doğru mu, bilmiyorum."}],"tip":{"title":"« Diyor ki » : rapporter ce que quelqu'un dit","example":"Ayşe dit qu'elle sera un peu en retard. — Ayşe <b>diyor ki</b> biraz geç kalacak.","body":"Pour rapporter des paroles à l'oral, le turc a une construction qui ressemble beaucoup au français : « diyor ki », il dit que, suivi de la phrase rapportée. Décomposons : « Ayşe diyor ki biraz geç kalacak », mot à mot Ayşe dit que un-peu en-retard restera, dans le même ordre que chez nous. Au passé, on dit « dedi ki », il a dit que, et pour les vérités générales « der ki », il dit toujours que, ou « derler ki », on dit que. Souvent, on ajoute à la fin le petit suffixe « -miş », qui signale qu'on le tient de quelqu'un d'autre : « tazeymiş », il paraît qu'il est frais. Astuce : pensez à « ki » comme au « que » français, il sert de pont entre celui qui parle et ce qu'il dit.","lit":"Ayşe · dit · que · un-peu · en-retard · restera","say":{"Diyor ki":"Diyor ki","diyor ki":"diyor ki","Ayşe diyor ki biraz geç kalacak":"Ayşe diyor ki biraz geç kalacak","dedi ki":"dedi ki","der ki":"der ki","derler ki":"derler ki","tazeymiş":"tazeymiş","ki":"ki"}}},{"title":"Un ami déménage","phrases":[{"fr":"Kerem déménage à Bornova le mois prochain.","tgt":"Kerem gelecek ay Bornova'ya taşınıyor."},{"fr":"Apparemment, il a trouvé un appartement plus grand.","tgt":"Daha büyük bir daire bulmuş."},{"fr":"Il paraît qu'il a vue sur la baie.","tgt":"Körfez manzarası varmış."},{"fr":"Samedi, on l'aidera à porter les cartons.","tgt":"Cumartesi kolileri taşımasına yardım edeceğiz."},{"fr":"On sera combien, au total ?","tgt":"Toplam kaç kişi olacağız?"},{"fr":"Au moins cinq, avec sa cousine.","tgt":"En az beş, kuzeniyle birlikte."},{"fr":"N'oublie pas d'apporter des gants.","tgt":"Eldiven getirmeyi unutma."},{"fr":"Ce canapé ne passera jamais par la porte !","tgt":"Bu kanepe kapıdan asla geçmez!"},{"fr":"Essayons en le mettant sur le côté.","tgt":"Yan çevirip deneyelim."},{"fr":"Ce soir, il nous offre des lahmacuns pour nous remercier.","tgt":"Bu akşam teşekkür için bize lahmacun ısmarlıyor."}]},{"title":"Un après-midi à la plage","phrases":[{"fr":"Pendant que tu nageais, j'ai lu mon livre.","tgt":"Sen yüzerken ben kitabımı okudum."},{"fr":"J'ai croisé Elif en marchant sur la plage.","tgt":"Plajda yürürken Elif'le karşılaştım."},{"fr":"Ne parle pas en mangeant !","tgt":"Yemek yerken konuşma!"},{"fr":"Quand j'étais petit, je venais ici chaque été.","tgt":"Çocukken her yaz buraya gelirdim."},{"fr":"Tant que tu es là, tu me mets de la crème dans le dos ?","tgt":"Hazır buradayken sırtıma krem sürer misin?"},{"fr":"Le vent s'est levé pendant qu'on jouait aux cartes.","tgt":"Biz kâğıt oynarken rüzgâr çıktı."},{"fr":"Je me suis endormi en écoutant les vagues.","tgt":"Dalgaları dinlerken uyuyakaldım."},{"fr":"Achète des glaces en revenant.","tgt":"Dönerken dondurma al."},{"fr":"Le soleil se couchait pendant qu'on rentrait.","tgt":"Biz dönerken güneş batıyordu."},{"fr":"On refait la même chose demain ?","tgt":"Yarın da aynısını yapalım mı?"}],"tip":{"title":"« -ken » : pendant que","example":"Pendant que tu nageais, j'ai lu mon livre. — Sen <b>yüzerken</b> ben kitabımı okudum.","body":"Là où le français dit pendant que ou en faisant, le turc colle simplement « -ken » à la fin du verbe. On part de la forme de l'aoriste, par exemple « yüzer », il nage, et on ajoute « ken » : « yüzerken », pendant qu'il nage, ou en nageant. Bonne nouvelle, ce suffixe ne change jamais avec l'harmonie des voyelles et ne prend pas de personne : c'est le sujet devant qui dit qui fait l'action, comme dans « sen yüzerken », pendant que toi tu nageais. On l'entend partout : « yürürken », en marchant, « yemek yerken », en mangeant, et même « çocukken », quand j'étais enfant. Astuce : dès que vous entendez « ken » en fin de verbe, pensez « pendant que », une action qui sert de décor à une autre.","lit":"toi · nager-pendant-que · moi · livre-mon-[objet] · lu-j'ai","say":{"yüzer":"yüzer","yüzerken":"yüzerken","sen yüzerken":"sen yüzerken","yürürken":"yürürken","yemek yerken":"yemek yerken","çocukken":"çocukken"}}},{"title":"Parler boulot entre amis","phrases":[{"fr":"Alors, ton nouveau travail, ça se passe comment ?","tgt":"Eee, yeni iş nasıl gidiyor?"},{"fr":"Mes collègues sont très chaleureux.","tgt":"İş arkadaşlarım çok cana yakın."},{"fr":"Mais je fais beaucoup d'heures supplémentaires.","tgt":"Ama çok fazla mesai yapıyorum."},{"fr":"Tu rentres chez toi à quelle heure, le soir ?","tgt":"Akşamları saat kaçta eve dönüyorsun?"},{"fr":"En général, je ne rentre pas avant neuf heures.","tgt":"Genelde dokuzdan önce dönemiyorum."},{"fr":"Il faut que tu en parles à ton chef.","tgt":"Müdürünle konuşman lazım."},{"fr":"Si ça continue comme ça, je lui parlerai.","tgt":"Böyle devam ederse onunla konuşacağım."},{"fr":"Et toi, tu travailles toujours dans le tourisme ?","tgt":"Sen hâlâ turizmde mi çalışıyorsun?"},{"fr":"Oui, cet été, il y a eu énormément de touristes.","tgt":"Evet, bu yaz çok fazla turist geldi."},{"fr":"Bon, ce soir, on ne parle plus de travail !","tgt":"Neyse, bu akşam iş konuşmak yok!"}]},{"title":"Au marché de Kemeraltı","phrases":[{"fr":"On fait un tour à Kemeraltı demain matin ?","tgt":"Yarın sabah Kemeraltı'nda bir tur atalım mı?"},{"fr":"Je dois trouver un cadeau pour ma mère.","tgt":"Anneme bir hediye almam lazım."},{"fr":"Regarde ces jolies serviettes en coton !","tgt":"Şu güzel pamuklu havlulara bak!"},{"fr":"Combien coûte celle-ci ?","tgt":"Bu kaç para?"},{"fr":"Trois cents livres, mais je te fais une remise.","tgt":"Üç yüz lira, ama sana indirim yaparım."},{"fr":"Elle me plaît, je la prends.","tgt":"Beğendim, alıyorum."},{"fr":"Allons boire un café turc au Kızlarağası Hanı.","tgt":"Kızlarağası Hanı'nda bir Türk kahvesi içelim."},{"fr":"Je ne savais pas que ce marché était si grand.","tgt":"Bu çarşının bu kadar büyük olduğunu bilmiyordum."},{"fr":"On s'est presque perdus dans les ruelles.","tgt":"Ara sokaklarda neredeyse kaybolduk."},{"fr":"Je reviendrai sûrement avant de partir.","tgt":"Gitmeden önce mutlaka tekrar gelirim."}]},{"title":"Une soirée cinéma en plein air","phrases":[{"fr":"Ce soir, il y a du cinéma en plein air au parc.","tgt":"Bu akşam parkta açık hava sineması var."},{"fr":"Tu veux venir avec nous ?","tgt":"Bizimle gelmek ister misin?"},{"fr":"Quel film est-ce qu'ils passent ?","tgt":"Hangi filmi gösteriyorlar?"},{"fr":"Une vieille comédie turque des années soixante-dix.","tgt":"Yetmişlerden eski bir Türk komedisi."},{"fr":"Je l'avais vue enfant avec mon grand-père.","tgt":"Onu çocukken dedemle izlemiştim."},{"fr":"Apporte un coussin, les chaises sont dures.","tgt":"Bir minder getir, sandalyeler sert."},{"fr":"On achètera des graines de tournesol sur place.","tgt":"Çekirdeği orada alırız."},{"fr":"Chut, le film commence !","tgt":"Şşş, film başlıyor!"},{"fr":"J'étais mort de rire !","tgt":"Gülmekten öldüm!"},{"fr":"Ça m'a rappelé de beaux souvenirs.","tgt":"Bana güzel anılarımı hatırlattı."}]},{"title":"Les petits vœux du quotidien","phrases":[{"fr":"Bon courage pour le travail !","tgt":"Kolay gelsin!"},{"fr":"Tu repeins ton balcon ? Bon courage !","tgt":"Balkonu mu boyuyorsun? Kolay gelsin!"},{"fr":"Merci, tu es adorable.","tgt":"Sağ ol, çok naziksin."},{"fr":"J'ai appris que tu étais malade, remets-toi vite.","tgt":"Hasta olduğunu duydum, geçmiş olsun."},{"fr":"Ton grand-père s'est cassé le bras ? Qu'il se remette vite.","tgt":"Deden kolunu mu kırdı? Geçmiş olsun."},{"fr":"Merci, il va déjà mieux.","tgt":"Sağ ol, şimdi daha iyi."},{"fr":"Bon appétit, tout le monde !","tgt":"Herkese afiyet olsun!"},{"fr":"Merci, bon appétit à toi aussi.","tgt":"Teşekkürler, sana da afiyet olsun."},{"fr":"C'était délicieux, bravo au cuisinier !","tgt":"Çok lezzetliydi, ellerine sağlık!"},{"fr":"Repose-toi bien, on se voit demain.","tgt":"İyi dinlen, yarın görüşürüz."}],"tip":{"title":"Les vœux du quotidien : « kolay gelsin », « geçmiş olsun », « afiyet olsun »","example":"Tu repeins ton balcon ? Bon courage ! — Balkonu mu boyuyorsun? <b>Kolay gelsin</b>!","body":"La vie sociale turque est rythmée par de petits vœux que tout le monde dit sans réfléchir, et les connaître vous rendra tout de suite sympathique. Ils sont construits sur le même modèle, un mot suivi d'un verbe au souhait, comme notre « que ce soit » : « kolay gelsin », mot à mot facile que-ça-vienne, se dit à toute personne qui travaille, du vendeur à l'ami qui repeint son balcon. « Geçmiş olsun », que ce soit passé, se dit à quelqu'un de malade ou qui a eu un souci, et « afiyet olsun », que ce soit à votre santé, c'est notre bon appétit. À chacun, on répond simplement « sağ ol », merci, et après un bon repas on félicite la cuisinière par « ellerine sağlık », santé à tes mains. Astuce : retenez que la fin en « olsun » ou « gelsin » sonne toujours comme un vœu, un peu comme « ainsi soit-il ».","lit":"balcon-le · [question] · peins-tu · facile · vienne","say":{"kolay gelsin":"kolay gelsin","geçmiş olsun":"geçmiş olsun","afiyet olsun":"afiyet olsun","Geçmiş olsun":"Geçmiş olsun","sağ ol":"sağ ol","ellerine sağlık":"ellerine sağlık","olsun":"olsun","gelsin":"gelsin"}}},{"title":"Avant de rentrer en France","phrases":[{"fr":"Je rentre en France après-demain.","tgt":"Öbür gün Fransa'ya dönüyorum."},{"fr":"Déjà ? Les vacances sont passées si vite !","tgt":"Şimdiden mi? Tatil ne çabuk geçti!"},{"fr":"On passe une dernière soirée sur le Kordon ?","tgt":"Kordon'da son bir akşam geçirelim mi?"},{"fr":"Tu vas énormément me manquer.","tgt":"Seni çok özleyeceğim."},{"fr":"Toi aussi, reviens vite nous voir.","tgt":"Ben de seni özleyeceğim, yine çabuk gel."},{"fr":"Si tu viens à Paris, tu dormiras chez moi.","tgt":"Paris'e gelirsen bende kalırsın."},{"fr":"Promis, je viendrai l'an prochain.","tgt":"Söz, seneye gelirim."},{"fr":"On s'écrira tous les jours.","tgt":"Her gün yazışırız."},{"fr":"Bon voyage, et appelle-moi en arrivant.","tgt":"İyi yolculuklar, varınca beni ara."},{"fr":"Prends bien soin de toi, mon ami.","tgt":"Kendine iyi bak, dostum."}]},{"title":"Fin du module : un bilan","phrases":[{"fr":"Dans ce module, on a appris à bavarder entre amis en turc.","tgt":"Bu modülde arkadaşlarla Türkçe sohbet etmeyi öğrendik."},{"fr":"Tu sais maintenant demander des nouvelles avec « naber ».","tgt":"Artık \"naber\" diye hal hatır sorabiliyorsun."},{"fr":"Tu sais aussi raconter ce que quelqu'un a dit.","tgt":"Birinin ne dediğini de anlatabiliyorsun."},{"fr":"Tu connais aussi les petits vœux du quotidien.","tgt":"Günlük güzel dilekleri de artık biliyorsun."},{"fr":"Le deuxième niveau de turc se termine ici.","tgt":"Türkçenin ikinci seviyesi burada bitiyor."},{"fr":"Tu as fait de très beaux progrès à l'oral.","tgt":"Konuşmada çok güzel ilerleme kaydettin."},{"fr":"Au niveau suivant, on parlera un turc plus riche.","tgt":"Bir sonraki seviyede daha zengin bir Türkçe konuşacağız."},{"fr":"Bravo pour ta persévérance !","tgt":"Azmin için tebrikler!"},{"fr":"Accorde-toi quelques jours de repos.","tgt":"Kendine dinlenmek için birkaç gün ayır."},{"fr":"À très vite pour le troisième niveau !","tgt":"Üçüncü seviyede görüşmek üzere!"}]}]}]},{"id":3,"name":"Niveau 3","freeLessonsPerModule":{"1":3,"2":0,"3":0},"modules":[{"id":1,"name":"Le quotidien","desc":"Une vie quotidienne installée en Turquie, avec ses subtilités.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"La réunion a été reportée","phrases":[{"fr":"La réunion de lundi a été reportée à mercredi.","tgt":"Pazartesi toplantısı çarşambaya ertelendi."},{"fr":"Le rapport a été envoyé au client hier soir.","tgt":"Rapor dün akşam müşteriye gönderildi."},{"fr":"La salle de réunion du dixième étage a déjà été réservée.","tgt":"Onuncu kattaki toplantı odası çoktan rezerve edildi."},{"fr":"Les nouveaux contrats seront signés la semaine prochaine.","tgt":"Yeni sözleşmeler gelecek hafta imzalanacak."},{"fr":"Cette décision a été prise sans nous consulter.","tgt":"Bu karar bize danışılmadan alındı."},{"fr":"Le compte rendu a été rédigé par Elif.","tgt":"Toplantı tutanağı Elif tarafından yazıldı."},{"fr":"Le café est servi dans la salle d'à côté.","tgt":"Kahve yandaki salonda servis ediliyor."},{"fr":"Les chiffres du trimestre ont été vérifiés deux fois.","tgt":"Üç aylık rakamlar iki kez kontrol edildi."},{"fr":"En fait, rien n'a encore été décidé.","tgt":"Aslında henüz hiçbir şeye karar verilmedi."},{"fr":"On nous a prévenus au tout dernier moment.","tgt":"Bize son anda haber verildi."}],"tip":{"title":"Le passif en « -il » : « yapıldı », ça a été fait","example":"La réunion de lundi a été reportée à mercredi. — Pazartesi toplantısı çarşambaya <b>ertelendi</b>.","body":"Pour dire qu'une chose a été faite sans dire par qui, le turc glisse un petit « il » juste après la racine du verbe. « Yaptı » veut dire il a fait, et « yapıldı » veut dire ça a été fait ; de même, « gönderdi », il a envoyé, devient « gönderildi », ça a été envoyé. Quand la racine finit par une voyelle, on entend seulement un « n » : « erteledi », il a reporté, devient « ertelendi », ça a été reporté. Décomposons : « toplantı çarşambaya ertelendi », réunion, à mercredi, reportée. Au bureau, c'est la tournure idéale pour rester poli et neutre, comme notre « on » : « bize haber verildi », on nous a prévenus. Astuce : pensez au mot français « il » caché dans le verbe, il fait disparaître celui qui agit.","lit":"lundi · réunion-sa · mercredi-à · reporter-[passif]-[passé]","say":{"yapıldı":"yapıldı","Yaptı":"Yaptı","gönderdi":"gönderdi","gönderildi":"gönderildi","erteledi":"erteledi","ertelendi":"ertelendi","toplantı çarşambaya ertelendi":"toplantı çarşambaya ertelendi","bize haber verildi":"bize haber verildi"}}},{"title":"Premier jour au bureau à Levent","phrases":[{"fr":"Mes nouveaux bureaux sont dans une tour à Levent.","tgt":"Yeni ofisim Levent'te bir gökdelende."},{"fr":"Chaque matin, je prends le métro jusqu'à la station Levent.","tgt":"Her sabah Levent durağına kadar metroya biniyorum."},{"fr":"Mon badge d'accès n'était pas encore prêt ce matin.","tgt":"Giriş kartım bu sabah henüz hazır değildi."},{"fr":"La responsable des ressources humaines m'a fait visiter tout l'étage.","tgt":"İnsan kaynakları müdürü bana bütün katı gezdirdi."},{"fr":"Mon bureau est près de la fenêtre, avec vue sur le Bosphore.","tgt":"Masam pencerenin yanında, Boğaz manzaralı."},{"fr":"Mes nouveaux collègues m'ont accueilli très chaleureusement.","tgt":"Yeni iş arkadaşlarım beni çok sıcak karşıladılar."},{"fr":"On m'a expliqué pendant une heure comment l'équipe fonctionne.","tgt":"Ekibin nasıl çalıştığını bana bir saat boyunca anlattılar."},{"fr":"À midi, nous avons déjeuné ensemble à la cantine de la tour.","tgt":"Öğlen gökdelenin yemekhanesinde birlikte yemek yedik."},{"fr":"Il me faudra quelques semaines pour prendre mes marques.","tgt":"Alışmam birkaç hafta sürecek."},{"fr":"Pour un premier jour, tout s'est plutôt bien passé.","tgt":"İlk gün için her şey oldukça iyi geçti."}]},{"title":"Faire réparer, faire livrer","phrases":[{"fr":"Je dois faire réparer ma voiture avant le voyage à Ankara.","tgt":"Ankara yolculuğundan önce arabamı tamir ettirmem lazım."},{"fr":"Nous avons fait repeindre le bureau le mois dernier.","tgt":"Geçen ay ofisi boyattık."},{"fr":"J'ai fait traduire mes diplômes par un traducteur assermenté.","tgt":"Diplomalarımı yeminli bir tercümana çevirttim."},{"fr":"Le directeur a fait préparer un nouveau devis pour le client.","tgt":"Müdür müşteri için yeni bir fiyat teklifi hazırlattı."},{"fr":"Ce soir, je vais me faire couper les cheveux à Karaköy.","tgt":"Bu akşam Karaköy'de saçımı kestireceğim."},{"fr":"Pourriez-vous faire porter les documents au bureau par coursier ?","tgt":"Belgeleri ofise kuryeyle yollatabilir misiniz?"},{"fr":"On a fait installer la climatisation dans la salle de réunion.","tgt":"Toplantı odasına klima taktırdık."},{"fr":"Ma cheffe m'a fait réécrire tout le rapport.","tgt":"Müdürüm bütün raporu bana yeniden yazdırdı."},{"fr":"Je fais nettoyer l'appartement une fois par semaine.","tgt":"Daireyi haftada bir temizletiyorum."},{"fr":"Faire faire coûte cher, mais ça fait gagner du temps.","tgt":"Başkasına yaptırmak pahalı ama zaman kazandırıyor."}],"tip":{"title":"Faire faire : le causatif « yaptırmak »","example":"Je dois faire réparer ma voiture avant le voyage à Ankara. — Ankara yolculuğundan önce arabamı <b>tamir ettirmem</b> lazım.","body":"Là où le français dit « faire faire », le turc ajoute simplement un suffixe au verbe, le plus souvent « dir » ou « tir ». « Yapmak », faire, devient « yaptırmak », faire faire ; « kesmek », couper, devient « kestirmek », et « saçımı kestireceğim » veut dire je vais me faire couper les cheveux. Après une voyelle, un simple « t » suffit : « temizlemek », nettoyer, devient « temizletmek », faire nettoyer, et « boyamak », peindre, donne « boyatmak ». Décomposons « tamir ettirmem lazım » : réparation, que je fasse faire, nécessaire ; donc il faut que je fasse réparer. Astuce : quand vous entendez ce « t » ou ce « tir » en plus, quelqu'un d'autre fait le travail à votre place.","lit":"Ankara · voyage-son-de · avant · voiture-ma-[objet] · réparation · faire-faire-mon · nécessaire","say":{"yaptırmak":"yaptırmak","Yapmak":"Yapmak","kesmek":"kesmek","kestirmek":"kestirmek","saçımı kestireceğim":"saçımı kestireceğim","temizlemek":"temizlemek","temizletmek":"temizletmek","boyamak":"boyamak","boyatmak":"boyatmak","tamir ettirmem lazım":"tamir ettirmem lazım"}}},{"title":"Un client exigeant","phrases":[{"fr":"Un de nos gros clients nous a appelés tôt ce matin.","tgt":"Önemli müşterilerimizden biri bu sabah erkenden bizi aradı."},{"fr":"Il n'est pas satisfait de la dernière livraison.","tgt":"Son teslimattan memnun değil."},{"fr":"Il faut absolument trouver une solution avant vendredi.","tgt":"Cumadan önce mutlaka bir çözüm bulmamız gerekiyor."},{"fr":"Je vais lui proposer une remise de dix pour cent.","tgt":"Ona yüzde on indirim önereceğim."},{"fr":"Il veut nous voir en personne dans un café de Karaköy.","tgt":"Bizimle Karaköy'de bir kafede yüz yüze görüşmek istiyor."},{"fr":"Écoutons d'abord ce qu'il a à nous dire.","tgt":"Önce bize ne söyleyeceğini dinleyelim."},{"fr":"Nous ne devons surtout pas perdre ce client.","tgt":"Bu müşteriyi kesinlikle kaybetmemeliyiz."},{"fr":"Au bout d'une heure, il a accepté notre proposition.","tgt":"Bir saat sonra teklifimizi kabul etti."},{"fr":"Nous lui avons promis de mieux nous occuper de lui.","tgt":"Kendisiyle daha yakından ilgileneceğimize söz verdik."},{"fr":"Un client mécontent peut devenir un client fidèle.","tgt":"Memnun olmayan bir müşteri sadık bir müşteriye dönüşebilir."}]},{"title":"Le collègue qui vient d'Ankara","phrases":[{"fr":"L'homme qui attend à la porte est notre nouveau directeur.","tgt":"Kapıda bekleyen adam yeni müdürümüz."},{"fr":"Le collègue qui travaille à Ankara arrive ce soir.","tgt":"Ankara'da çalışan iş arkadaşımız bu akşam geliyor."},{"fr":"Les gens qui habitent à Karaköy vont au bureau à pied.","tgt":"Karaköy'de oturan insanlar ofise yürüyerek gidiyor."},{"fr":"La femme qui parle au téléphone est notre avocate.","tgt":"Telefonda konuşan kadın avukatımız."},{"fr":"Ceux qui arrivent en retard doivent apporter des simits.","tgt":"Geç kalanlar simit getirmek zorunda."},{"fr":"Le train qui part à sept heures arrive à Ankara vers midi.","tgt":"Saat yedide kalkan tren öğlene doğru Ankara'ya varıyor."},{"fr":"Je ne connais pas la personne qui a envoyé ce courriel.","tgt":"Bu e-postayı gönderen kişiyi tanımıyorum."},{"fr":"Il n'y a pas beaucoup d'employés qui parlent français ici.","tgt":"Burada Fransızca bilen çalışan pek yok."},{"fr":"Le ferry qui traverse le Bosphore est toujours plein le matin.","tgt":"Boğaz'ı geçen vapur sabahları hep dolu."},{"fr":"Celui qui pose des questions apprend plus vite.","tgt":"Soru soran daha hızlı öğrenir."}],"tip":{"title":"Le participe en « -en » : « gelen adam », l'homme qui vient","example":"Le collègue qui travaille à Ankara arrive ce soir. — Ankara'da <b>çalışan</b> iş arkadaşımız bu akşam geliyor.","body":"En turc, il n'y a pas de petit mot « qui » : on transforme le verbe en adjectif avec le suffixe « en » ou « an », et on le place avant le nom. « Gelmek », venir, donne « gelen adam », l'homme qui vient ; « çalışmak », travailler, donne « çalışan », celui qui travaille. Après une voyelle, on ajoute un « y » pour la liaison : « beklemek », attendre, donne « bekleyen », et « kapıda bekleyen adam » veut dire l'homme qui attend à la porte. L'ordre est donc inversé par rapport au français : à la porte, attendant, homme. Ce participe peut même devenir un nom tout seul : « geç kalanlar », ceux qui sont en retard. Astuce : dites d'abord ce que fait la personne, puis qui elle est.","lit":"Ankara-à · travailler-[qui] · travail · ami-notre · ce · soir · venir-[présent]","say":{"gelen adam":"gelen adam","Gelmek":"Gelmek","çalışmak":"çalışmak","çalışan":"çalışan","beklemek":"beklemek","bekleyen":"bekleyen","kapıda bekleyen adam":"kapıda bekleyen adam","geç kalanlar":"geç kalanlar"}}},{"title":"Un déplacement à Ankara","phrases":[{"fr":"Mardi, je pars deux jours à Ankara pour le travail.","tgt":"Salı günü iş için iki günlüğüne Ankara'ya gidiyorum."},{"fr":"J'ai pris le train à grande vitesse depuis Istanbul.","tgt":"İstanbul'dan hızlı trene bindim."},{"fr":"Le trajet dure un peu plus de quatre heures.","tgt":"Yolculuk dört saatten biraz fazla sürüyor."},{"fr":"Notre réunion avec l'agence d'Ankara est à dix heures.","tgt":"Ankara şubesiyle toplantımız saat onda."},{"fr":"Mon hôtel est tout près du quartier de Kızılay.","tgt":"Otelim Kızılay'a çok yakın."},{"fr":"Le soir, les collègues d'Ankara m'ont emmené dans un bon restaurant.","tgt":"Akşam Ankaralı iş arkadaşları beni güzel bir lokantaya götürdüler."},{"fr":"Ankara est plus calme et mieux organisée qu'Istanbul.","tgt":"Ankara İstanbul'dan daha sakin ve düzenli."},{"fr":"Je n'ai malheureusement pas eu le temps de visiter la ville.","tgt":"Maalesef şehri gezmeye vaktim olmadı."},{"fr":"Mes frais de déplacement seront pris en charge par la société.","tgt":"Yol masraflarım şirket tarafından karşılanacak."},{"fr":"Je rentre demain soir par le dernier vol.","tgt":"Yarın akşam son uçakla dönüyorum."}]},{"title":"À la banque","phrases":[{"fr":"Je voudrais ouvrir un compte en livres turques.","tgt":"Türk lirası hesabı açtırmak istiyorum."},{"fr":"Quels documents dois-je apporter pour l'ouverture ?","tgt":"Hesap açılışı için hangi belgeleri getirmem gerekiyor?"},{"fr":"Il faut une copie de votre permis de séjour.","tgt":"İkamet izninizin fotokopisi lazım."},{"fr":"Ma carte bancaire a été bloquée hier soir.","tgt":"Banka kartım dün akşam bloke edildi."},{"fr":"Le distributeur devant l'agence a avalé ma carte.","tgt":"Şubenin önündeki bankamatik kartımı yuttu."},{"fr":"Je voudrais virer cinq mille livres sur un autre compte.","tgt":"Başka bir hesaba beş bin lira havale etmek istiyorum."},{"fr":"Combien de temps faut-il pour un virement vers la France ?","tgt":"Fransa'ya havale ne kadar sürer?"},{"fr":"Les frais sont-ils compris dans ce montant ?","tgt":"Masraflar bu tutara dahil mi?"},{"fr":"Mon salaire est versé le quinze de chaque mois.","tgt":"Maaşım her ayın on beşinde yatırılıyor."},{"fr":"Prenez un ticket et attendez qu'on appelle votre numéro.","tgt":"Sıra numarası alın ve numaranızın çağrılmasını bekleyin."}]},{"title":"Une journée où rien ne va","phrases":[{"fr":"Je n'ai même pas eu le temps de boire un café.","tgt":"Kahve içmeye bile vaktim olmadı."},{"fr":"Même le ferry était en retard ce matin.","tgt":"Bu sabah vapur bile gecikti."},{"fr":"Même le directeur ne connaissait pas la réponse.","tgt":"Müdür bile cevabı bilmiyordu."},{"fr":"Il n'a même pas dit bonjour en arrivant.","tgt":"Gelince merhaba bile demedi."},{"fr":"Les imprimantes sont en panne, même la nouvelle.","tgt":"Yazıcılar bozuldu, yenisi bile."},{"fr":"Même un enfant comprendrait ce tableau.","tgt":"Bu tabloyu bir çocuk bile anlar."},{"fr":"À midi, je n'ai même pas mangé.","tgt":"Öğlen yemek bile yemedim."},{"fr":"Même dans le métro, il n'y avait pas une place assise.","tgt":"Metroda bile oturacak yer yoktu."},{"fr":"Même mon thé a refroidi sur le bureau.","tgt":"Masadaki çayım bile soğudu."},{"fr":"Malgré tout ça, je garde le sourire.","tgt":"Bütün bunlara rağmen keyfim hâlâ yerinde."}],"tip":{"title":"« Bile » : même","example":"Même le ferry était en retard ce matin. — Bu sabah vapur <b>bile</b> gecikti.","body":"Le petit mot « bile » veut dire même, mais attention à sa place : en français on le met avant le mot, en turc on le met juste après. On dit donc « vapur bile », le ferry même, pour même le ferry, et « müdür bile », même le directeur. Avec un verbe négatif, « bile » se traduit par même pas : « merhaba bile demedi », bonjour même pas il a dit, donc il n'a même pas dit bonjour. Autre exemple : « bir çocuk bile anlar », même un enfant comprendrait. Astuce : imaginez que « bile » s'accroche comme une étiquette derrière le mot qui vous surprend, et appuyez un peu la voix sur ce mot.","lit":"ce · matin · ferry · même · être en retard-[passé]","say":{"Bile":"Bile","bile":"bile","vapur bile":"vapur bile","müdür bile":"müdür bile","merhaba bile demedi":"merhaba bile demedi","bir çocuk bile anlar":"bir çocuk bile anlar"}}},{"title":"Renouveler son permis de séjour","phrases":[{"fr":"Mon permis de séjour expire à la fin du mois.","tgt":"İkamet iznim ay sonunda bitiyor."},{"fr":"J'ai pris rendez-vous en ligne pour le renouveler.","tgt":"Yenilemek için internetten randevu aldım."},{"fr":"Ce formulaire doit être rempli en turc.","tgt":"Bu formun Türkçe doldurulması gerekiyor."},{"fr":"N'oubliez pas d'apporter quatre photos d'identité.","tgt":"Dört tane vesikalık fotoğraf getirmeyi unutmayın."},{"fr":"La file d'attente était interminable ce matin.","tgt":"Bu sabah sıra bitmek bilmiyordu."},{"fr":"Le fonctionnaire a vérifié tous mes documents un par un.","tgt":"Memur bütün belgelerimi tek tek kontrol etti."},{"fr":"Il manquait une signature sur le contrat de location.","tgt":"Kira sözleşmesinde bir imza eksikti."},{"fr":"Je dois revenir la semaine prochaine avec le papier manquant.","tgt":"Gelecek hafta eksik belgeyle tekrar gelmem lazım."},{"fr":"La nouvelle carte arrivera par la poste d'ici un mois.","tgt":"Yeni kart bir ay içinde postayla gelecek."},{"fr":"Les démarches administratives demandent surtout de la patience.","tgt":"Resmî işler en çok sabır ister."}]},{"title":"Chercher un appartement près de Karaköy","phrases":[{"fr":"Nous cherchons un appartement pas trop loin de Karaköy.","tgt":"Karaköy'e çok uzak olmayan bir daire arıyoruz."},{"fr":"Le loyer ne doit pas dépasser trente mille livres.","tgt":"Kira otuz bin lirayı geçmemeli."},{"fr":"L'agent immobilier nous a montré trois appartements aujourd'hui.","tgt":"Emlakçı bugün bize üç daire gösterdi."},{"fr":"Le premier était lumineux mais beaucoup trop petit.","tgt":"İlki aydınlıktı ama çok küçüktü."},{"fr":"Le deuxième avait une terrasse avec vue sur la mer.","tgt":"İkincisinin deniz manzaralı bir terası vardı."},{"fr":"Le propriétaire demande deux mois de caution.","tgt":"Ev sahibi iki kira depozito istiyor."},{"fr":"Les charges de l'immeuble sont-elles incluses dans le loyer ?","tgt":"Aidat kiraya dahil mi?"},{"fr":"Il y a un chantier dans la rue, c'est un peu bruyant.","tgt":"Sokakta inşaat var, biraz gürültülü."},{"fr":"Nous aimerions revoir l'appartement avant de signer.","tgt":"İmzalamadan önce daireyi bir kez daha görmek istiyoruz."},{"fr":"Trouver un logement à Istanbul, c'est aussi une question de chance.","tgt":"İstanbul'da ev bulmak biraz da şans işi."}]},{"title":"Chez le médecin","phrases":[{"fr":"J'ai mal à la gorge depuis trois jours.","tgt":"Üç gündür boğazım ağrıyor."},{"fr":"J'ai pris rendez-vous dans une clinique de Şişli.","tgt":"Şişli'de bir klinikten randevu aldım."},{"fr":"Le médecin m'a demandé si j'avais de la fièvre.","tgt":"Doktor ateşim olup olmadığını sordu."},{"fr":"Il m'a fait faire une prise de sang.","tgt":"Bana kan tahlili yaptırdı."},{"fr":"Les résultats seront prêts demain après-midi.","tgt":"Sonuçlar yarın öğleden sonra hazır olacak."},{"fr":"Ce n'est rien de grave, juste une petite infection.","tgt":"Ciddi bir şey değil, sadece hafif bir enfeksiyon."},{"fr":"Prenez ce médicament trois fois par jour après les repas.","tgt":"Bu ilacı günde üç kez yemekten sonra alın."},{"fr":"Mon assurance privée rembourse une partie des frais.","tgt":"Özel sigortam masrafların bir kısmını karşılıyor."},{"fr":"Il m'a conseillé de me reposer deux jours à la maison.","tgt":"İki gün evde dinlenmemi tavsiye etti."},{"fr":"Je vais envoyer mon arrêt maladie à mon chef.","tgt":"Raporumu müdürüme göndereceğim."}]},{"title":"Le langage du bureau : « efendim », « buyurun », les formules polies","phrases":[{"fr":"Allô, oui ? Je vous écoute, allez-y.","tgt":"Efendim? Buyurun, sizi dinliyorum."},{"fr":"Pardon ? Je n'ai pas bien entendu.","tgt":"Efendim? Tam duyamadım."},{"fr":"Entrez, je vous en prie, asseyez-vous.","tgt":"Buyurun, girin, oturun lütfen."},{"fr":"Bon courage pour votre travail !","tgt":"Kolay gelsin!"},{"fr":"Pourriez-vous patienter une petite minute, monsieur ?","tgt":"Bir dakika bekler misiniz efendim?"},{"fr":"Merci infiniment pour votre aide précieuse, madame.","tgt":"Değerli yardımınız için çok teşekkür ederim efendim."},{"fr":"Voici votre thé, monsieur, servez-vous.","tgt":"Çayınız, buyurun efendim."},{"fr":"Bravo au cuisinier, c'était délicieux.","tgt":"Ellerinize sağlık, çok güzel olmuş."},{"fr":"Excusez-moi de vous avoir dérangé.","tgt":"Rahatsız ettim, kusura bakmayın."},{"fr":"Bonne continuation et au revoir !","tgt":"İyi çalışmalar, hoşça kalın!"}],"tip":{"title":"Le langage du bureau : « efendim », « buyurun », les formules polies","example":"Pardon ? Je n'ai pas bien entendu. — <b>Efendim</b>? Tam duyamadım.","body":"Deux petits mots vous rendront poli dans toutes les situations au bureau. « Efendim » veut dire monsieur ou madame, mais on l'utilise aussi pour répondre au téléphone, comme notre allô, oui, et pour faire répéter, comme notre pardon : prononcé avec une voix qui monte, « efendim ? » signifie je n'ai pas compris. « Buyurun » est un mot magique qui veut dire je vous en prie : on le dit pour faire entrer quelqu'un, pour tendre un thé, ou pour inviter à parler. Ajoutez « kolay gelsin », que ce soit facile, quand vous entrez chez quelqu'un qui travaille, et « iyi çalışmalar », bon travail, en partant. Astuce : dans le doute, un « buyurun » avec un sourire ouvre toutes les portes.","lit":"pardon-[question] · complètement · entendre-pouvoir-[ne… pas]-[passé]-je","say":{"efendim":"efendim","buyurun":"buyurun","Efendim":"Efendim","efendim ?":"efendim?","Buyurun":"Buyurun","kolay gelsin":"kolay gelsin","iyi çalışmalar":"iyi çalışmalar"}}},{"title":"Les débats du déjeuner autour d'un thé","phrases":[{"fr":"À midi, on parle de tout et de rien autour d'un thé.","tgt":"Öğlen çay eşliğinde her şeyden konuşuruz."},{"fr":"Aujourd'hui, le débat portait sur les loyers à Istanbul.","tgt":"Bugün tartışma İstanbul'daki kiralar üzerineydi."},{"fr":"Selon moi, travailler de chez soi est plus efficace.","tgt":"Bence evden çalışmak daha verimli."},{"fr":"Je ne partage pas tout à fait votre avis.","tgt":"Size tam olarak katılmıyorum."},{"fr":"D'un côté vous avez raison, mais de l'autre, c'est plus compliqué.","tgt":"Bir açıdan haklısınız ama öbür açıdan iş daha karmaşık."},{"fr":"Les embouteillages sont devenus insupportables en ville.","tgt":"Şehirde trafik artık çekilmez hale geldi."},{"fr":"Pour traverser, le ferry reste le moyen le plus agréable.","tgt":"Karşıya geçmek için en keyifli yol hâlâ vapur."},{"fr":"Chacun défend son point de vue, mais toujours avec humour.","tgt":"Herkes kendi fikrini savunuyor ama hep esprili bir şekilde."},{"fr":"On reprend un thé avant de retourner au travail ?","tgt":"İşe dönmeden önce birer çay daha içelim mi?"},{"fr":"Ces discussions rendent les journées plus légères.","tgt":"Bu sohbetler günleri hafifletiyor."}]},{"title":"Le ferry du matin","phrases":[{"fr":"Chaque matin, je prends le ferry de Kadıköy à Karaköy.","tgt":"Her sabah Kadıköy'den Karaköy'e vapura biniyorum."},{"fr":"La traversée ne dure que vingt petites minutes.","tgt":"Karşıya geçmek topu topu yirmi dakika sürüyor."},{"fr":"Je bois un thé sur le pont en regardant les mouettes.","tgt":"Martıları seyrederek güvertede çay içiyorum."},{"fr":"Certains passagers lancent des morceaux de simit aux mouettes.","tgt":"Bazı yolcular martılara simit atıyor."},{"fr":"Quand il y a du brouillard, les ferries sont annulés.","tgt":"Sis olunca vapur seferleri iptal ediliyor."},{"fr":"Dans ce cas, je prends le train qui passe sous le Bosphore.","tgt":"O zaman Boğaz'ın altından geçen trene biniyorum."},{"fr":"Ma carte de transport se recharge automatiquement.","tgt":"Ulaşım kartıma otomatik olarak para yükleniyor."},{"fr":"C'est le plus beau moment de ma journée.","tgt":"Günümün en güzel anı bu."},{"fr":"J'en profite pour relire mes notes avant les réunions.","tgt":"Toplantılardan önce notlarımı gözden geçirmek için bu zamanı kullanıyorum."},{"fr":"Aller travailler en bateau, c'est un vrai luxe.","tgt":"İşe vapurla gitmek gerçek bir lüks."}]},{"title":"Les impôts et la comptabilité","phrases":[{"fr":"Notre comptable s'occupe de toutes nos déclarations.","tgt":"Muhasebecimiz bütün beyannamelerimizle ilgileniyor."},{"fr":"La déclaration annuelle doit être déposée en mars.","tgt":"Yıllık beyanname mart ayında verilmeli."},{"fr":"J'ai rassemblé toutes mes factures dans un classeur.","tgt":"Bütün faturalarımı bir klasörde topladım."},{"fr":"Les factures doivent être conservées pendant cinq ans.","tgt":"Faturaların beş yıl saklanması gerekiyor."},{"fr":"Le taux de TVA a changé l'an dernier.","tgt":"KDV oranı geçen yıl değişti."},{"fr":"Une erreur dans le formulaire peut coûter très cher.","tgt":"Formdaki bir hata pahalıya patlayabilir."},{"fr":"Le comptable a repéré une facture saisie deux fois.","tgt":"Muhasebeci iki kez girilmiş bir fatura fark etti."},{"fr":"Il faut payer avant la date limite pour éviter une amende.","tgt":"Ceza yememek için son günden önce ödemek lazım."},{"fr":"Je ne comprends rien au vocabulaire fiscal en turc.","tgt":"Türkçe vergi terimlerinden hiçbir şey anlamıyorum."},{"fr":"Heureusement, tout est réglé jusqu'à l'année prochaine.","tgt":"Neyse ki gelecek yıla kadar her şey halloldu."}]},{"title":"Une présentation importante","phrases":[{"fr":"Demain, je présente notre projet devant toute la direction.","tgt":"Yarın projemizi bütün yönetimin önünde sunuyorum."},{"fr":"J'ai préparé une vingtaine de diapositives.","tgt":"Yirmi kadar slayt hazırladım."},{"fr":"Je vais commencer par un bref résumé des résultats.","tgt":"Sonuçların kısa bir özetiyle başlayacağım."},{"fr":"Ensuite, j'expliquerai nos objectifs pour l'année prochaine.","tgt":"Sonra gelecek yılki hedeflerimizi anlatacağım."},{"fr":"Hier soir, j'ai répété ma présentation trois fois.","tgt":"Dün akşam sunumumu üç kez prova ettim."},{"fr":"Parler turc devant un public me rend un peu nerveux.","tgt":"Topluluk önünde Türkçe konuşmak beni biraz geriyor."},{"fr":"Mes collègues m'ont donné de précieux conseils.","tgt":"İş arkadaşlarım bana değerli tavsiyeler verdi."},{"fr":"Les questions à la fin étaient nombreuses mais bienveillantes.","tgt":"Sondaki sorular çoktu ama hepsi iyi niyetliydi."},{"fr":"Le directeur général avait l'air convaincu.","tgt":"Genel müdür ikna olmuş görünüyordu."},{"fr":"Ce soir, je fête ça avec un bon dîner à Karaköy.","tgt":"Bu akşam bunu Karaköy'de güzel bir yemekle kutluyorum."}]},{"title":"Travailler depuis la maison","phrases":[{"fr":"Je travaille de chez moi le lundi et le vendredi.","tgt":"Pazartesi ve cuma günleri evden çalışıyorum."},{"fr":"Mon salon s'est transformé en petit bureau.","tgt":"Salonum küçük bir ofise dönüştü."},{"fr":"La connexion internet de l'immeuble est parfois lente.","tgt":"Apartmanın interneti bazen yavaş."},{"fr":"Les réunions en ligne commencent toujours avec dix minutes de retard.","tgt":"Çevrim içi toplantılar hep on dakika geç başlıyor."},{"fr":"J'économise presque deux heures de trajet par jour.","tgt":"Günde neredeyse iki saatlik yoldan kurtuluyorum."},{"fr":"Mais le thé du bureau et les collègues me manquent.","tgt":"Ama ofisin çayını ve iş arkadaşlarımı özlüyorum."},{"fr":"Pendant les appels, le chat du voisin vient souvent sur mon balcon.","tgt":"Görüşmeler sırasında komşunun kedisi sık sık balkonuma geliyor."},{"fr":"Le soir, il faut savoir s'arrêter à l'heure.","tgt":"Akşamları vaktinde bırakmayı bilmek lazım."},{"fr":"Je m'habille quand même comme si j'allais au bureau.","tgt":"Yine de ofise gidiyormuş gibi giyiniyorum."},{"fr":"Deux jours à la maison, c'est l'équilibre parfait pour moi.","tgt":"Evde iki gün benim için ideal denge."}]},{"title":"Les voisins de l'immeuble","phrases":[{"fr":"Notre concierge connaît tout le monde dans la rue.","tgt":"Kapıcımız sokaktaki herkesi tanıyor."},{"fr":"Il nous monte du pain frais chaque matin.","tgt":"Her sabah bize taze ekmek getiriyor."},{"fr":"La voisine du dessus nous a apporté des feuilles de vigne farcies.","tgt":"Üst kattaki komşu bize sarma getirdi."},{"fr":"En Turquie, on ne rend jamais une assiette vide.","tgt":"Türkiye'de tabak asla boş geri verilmez."},{"fr":"Je lui ai donc rendu l'assiette avec des petits gâteaux.","tgt":"Ben de tabağı kurabiyeyle geri verdim."},{"fr":"La réunion des copropriétaires a lieu jeudi soir.","tgt":"Apartman toplantısı perşembe akşamı."},{"fr":"Il faut décider qui paiera la réparation de l'ascenseur.","tgt":"Asansörün tamirini kimin ödeyeceğine karar vermemiz lazım."},{"fr":"Le voisin du rez-de-chaussée se plaint sans cesse du bruit.","tgt":"Giriş kattaki komşu hep gürültüden şikâyet ediyor."},{"fr":"Les enfants de l'immeuble jouent ensemble dans la cour.","tgt":"Apartmanın çocukları bahçede birlikte oynuyor."},{"fr":"Ici, les voisins sont presque une deuxième famille.","tgt":"Burada komşular neredeyse ikinci bir aile gibi."}]},{"title":"Le pot de départ d'un collègue","phrases":[{"fr":"Notre collègue Murat quitte la société vendredi.","tgt":"İş arkadaşımız Murat cuma günü şirketten ayrılıyor."},{"fr":"Il a trouvé un nouveau poste à Izmir.","tgt":"İzmir'de yeni bir iş buldu."},{"fr":"Nous avons organisé un petit pot au dernier étage.","tgt":"En üst katta küçük bir veda partisi düzenledik."},{"fr":"Tout le monde a mis un peu d'argent pour son cadeau.","tgt":"Hediyesi için herkes biraz para koydu."},{"fr":"Nous lui avons offert un service à thé en cuivre.","tgt":"Ona bakır bir çay takımı hediye ettik."},{"fr":"Le directeur a fait un petit discours très touchant.","tgt":"Müdür çok dokunaklı kısa bir konuşma yaptı."},{"fr":"Murat nous a remerciés pour ces six belles années.","tgt":"Murat bu altı güzel yıl için hepimize teşekkür etti."},{"fr":"Il va vraiment beaucoup nous manquer au bureau.","tgt":"Ofiste onu gerçekten çok özleyeceğiz."},{"fr":"Nous avons promis d'aller le voir à Izmir cet été.","tgt":"Bu yaz onu İzmir'de ziyaret etmeye söz verdik."},{"fr":"Bonne route à toi, et ne nous oublie pas !","tgt":"Yolun açık olsun, bizi unutma!"}]},{"title":"Fin du module : un bilan","phrases":[{"fr":"Ce module nous a plongés dans la vie active à Istanbul.","tgt":"Bu modül bizi İstanbul'daki iş hayatının içine soktu."},{"fr":"Vous savez maintenant parler d'une réunion ou d'un client.","tgt":"Artık bir toplantıdan ya da bir müşteriden bahsedebilirsiniz."},{"fr":"Le passif et le causatif n'ont plus de secret pour vous.","tgt":"Edilgen ve ettirgen çatı artık sizin için sır değil."},{"fr":"Les participes rendent vos phrases en turc plus riches.","tgt":"Sıfat-fiiller Türkçe cümlelerinizi zenginleştiriyor."},{"fr":"Grâce à « efendim » et « buyurun », vous savez rester poli partout.","tgt":"“Efendim” ve “buyurun” sayesinde her yerde kibar olabiliyorsunuz."},{"fr":"Même l'administration turque ne vous fait plus peur.","tgt":"Türk bürokrasisi bile artık sizi korkutmuyor."},{"fr":"Le prochain module vous emmènera sur les routes de Turquie.","tgt":"Bir sonraki modül sizi Türkiye yollarına götürecek."},{"fr":"Continuez à écouter ces phrases sur le chemin du travail.","tgt":"İşe giderken bu cümleleri dinlemeye devam edin."},{"fr":"Votre turc devient vraiment professionnel.","tgt":"Türkçeniz gerçekten profesyonelleşiyor."},{"fr":"Bravo, et à très bientôt pour la suite !","tgt":"Tebrikler, devamında görüşmek üzere!"}]}]},{"id":2,"name":"En voyage","desc":"Des aventures de voyage plus poussées et plus authentiques.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Arrivée à Antalya","phrases":[{"fr":"Nous sommes arrivés à Antalya tard dans la nuit.","tgt":"Antalya'ya gece geç saatte vardık."},{"fr":"Notre pension se trouve au cœur de Kaleiçi.","tgt":"Pansiyonumuz Kaleiçi'nin tam ortasında."},{"fr":"Les ruelles pavées descendent jusqu'au vieux port.","tgt":"Taş döşeli sokaklar eski limana kadar iniyor."},{"fr":"Depuis la terrasse, on aperçoit les montagnes enneigées.","tgt":"Terastan karlı dağlar görünüyor."},{"fr":"Le propriétaire nous a accueillis avec un thé bien chaud.","tgt":"Ev sahibi bizi sıcacık bir çayla karşıladı."},{"fr":"Il nous a conseillé de passer par la porte d'Hadrien.","tgt":"Hadrian Kapısı'ndan geçmemizi tavsiye etti."},{"fr":"Ce voyage, nous en rêvions depuis des années.","tgt":"Bu yolculuğu yıllardır hayal ediyorduk."},{"fr":"Nous avons trois semaines devant nous pour longer la côte.","tgt":"Kıyı boyunca gitmek için önümüzde üç hafta var."},{"fr":"Le premier soir, nous avons dîné face à la mer.","tgt":"İlk akşam denize karşı yemek yedik."},{"fr":"Demain, on commence par les sites antiques des environs.","tgt":"Yarın çevredeki antik kentlerle başlıyoruz."}]},{"title":"Les relatives en « -diğim » : « gördüğüm şehir », la ville que j'ai vue","phrases":[{"fr":"Perge est la plus belle cité antique que j'aie vue.","tgt":"Perge, gördüğüm en güzel antik kent."},{"fr":"Les colonnes que nous avons photographiées ont deux mille ans.","tgt":"Fotoğrafını çektiğimiz sütunlar iki bin yıllık."},{"fr":"Le guide que nous avons rencontré connaissait chaque pierre.","tgt":"Tanıştığımız rehber her taşı biliyordu."},{"fr":"Le stade que vous voyez pouvait accueillir douze mille personnes.","tgt":"Gördüğünüz stadyum on iki bin kişi alabiliyordu."},{"fr":"Le chemin que nous avons pris longeait l'ancienne rue principale.","tgt":"Tuttuğumuz yol eski ana caddenin yanından geçiyordu."},{"fr":"Je ne retrouve pas le billet que j'ai acheté à l'entrée.","tgt":"Girişte aldığım bileti bulamıyorum."},{"fr":"Les statues trouvées ici sont exposées au musée d'Antalya.","tgt":"Burada bulunan heykeller Antalya Müzesi'nde sergileniyor."},{"fr":"L'endroit que j'ai préféré, ce sont les anciens thermes.","tgt":"En çok beğendiğim yer eski hamamlar oldu."},{"fr":"Montrez-moi les photos que vous avez prises.","tgt":"Çektiğiniz fotoğrafları bana gösterin."},{"fr":"Le restaurant que vous nous avez conseillé était fermé.","tgt":"Bize tavsiye ettiğiniz lokanta kapalıydı."}],"tip":{"title":"Les relatives en « -diğim » : « gördüğüm şehir », la ville que j'ai vue","example":"Perge est la plus belle cité antique que j'aie vue. — Perge, <b>gördüğüm</b> en güzel antik kent.","body":"En français, la relative vient après le nom : la ville que j'ai vue. En turc, c'est l'inverse : on place d'abord le verbe transformé, puis le nom, comme si l'on disait « ma vue ville ». On prend le verbe, on ajoute « -dik », puis la marque de la personne : « gördüğüm », que j'ai vu, « gördüğün », que tu as vu, « gördüğümüz », que nous avons vu. À l'oral, le « ğ » ne se prononce pas, il allonge simplement la voyelle : on dit « gueur-du-um ». Essayez avec « aldığım bilet », le billet que j'ai acheté, ou « tanıştığımız rehber », le guide que nous avons rencontré. Pour retenir, pensez à une étiquette qu'on colle devant le nom : d'abord ce qu'on a fait, ensuite la chose.","lit":"Perge · voir-que-j'ai · le-plus · beau · antique · cité","say":{"gördüğüm şehir":"gördüğüm şehir","gördüğüm":"gördüğüm","gördüğün":"gördüğün","gördüğümüz":"gördüğümüz","aldığım bilet":"aldığım bilet","tanıştığımız rehber":"tanıştığımız rehber"}}},{"title":"Louer une voiture","phrases":[{"fr":"Je voudrais louer une voiture pour une semaine.","tgt":"Bir haftalığına araba kiralamak istiyorum."},{"fr":"Préférez-vous une boîte manuelle ou automatique ?","tgt":"Manuel mi yoksa otomatik vites mi tercih edersiniz?"},{"fr":"L'assurance tous risques est-elle comprise dans le prix ?","tgt":"Kasko fiyata dahil mi?"},{"fr":"Il faut laisser une caution de cinq mille livres.","tgt":"Beş bin lira depozito bırakmanız gerekiyor."},{"fr":"Peut-on rendre la voiture à Fethiye plutôt qu'ici ?","tgt":"Arabayı burada değil de Fethiye'de teslim edebilir miyiz?"},{"fr":"Le réservoir est plein, rendez-le plein, s'il vous plaît.","tgt":"Depo dolu, lütfen dolu teslim edin."},{"fr":"Il y a déjà une rayure sur la portière arrière.","tgt":"Arka kapıda zaten bir çizik var."},{"fr":"Notez-la sur le contrat, pour éviter tout malentendu.","tgt":"Yanlış anlaşılma olmasın diye sözleşmeye yazın lütfen."},{"fr":"Mon permis français est-il valable en Turquie ?","tgt":"Fransız ehliyetim Türkiye'de geçerli mi?"},{"fr":"Les péages se paient avec un badge collé sur le pare-brise.","tgt":"Otoyol ücretleri ön cama yapıştırılan etiketle ödeniyor."}]},{"title":"« İçin » : pour, afin de","phrases":[{"fr":"Arrêtons-nous ici pour faire le plein.","tgt":"Benzin almak için burada duralım."},{"fr":"Nous sommes partis tôt pour éviter la chaleur.","tgt":"Sıcaktan kaçmak için erken yola çıktık."},{"fr":"Pour aller à Kaş, prenez la route côtière.","tgt":"Kaş'a gitmek için sahil yolunu kullanın."},{"fr":"Ce panier de fruits, c'est pour vous.","tgt":"Bu meyve sepeti sizin için."},{"fr":"Merci pour votre aide, vous nous avez sauvé la journée.","tgt":"Yardımınız için teşekkürler, günümüzü kurtardınız."},{"fr":"On a fait un détour pour voir la plage d'Olympos.","tgt":"Olimpos sahilini görmek için biraz yoldan saptık."},{"fr":"Pour moi, un ayran bien frais, s'il vous plaît.","tgt":"Benim için soğuk bir ayran lütfen."},{"fr":"Il conduit lentement pour profiter du paysage.","tgt":"Manzaranın tadını çıkarmak için yavaş sürüyor."},{"fr":"Nous avons acheté des cartes postales pour nos amis.","tgt":"Arkadaşlarımız için kartpostal aldık."},{"fr":"Pour une fois, nous ne sommes pas pressés.","tgt":"Bu sefer hiç acelemiz yok."}],"tip":{"title":"« İçin » : pour, afin de","example":"Arrêtons-nous ici pour faire le plein. — Benzin almak <b>için</b> burada duralım.","body":"Le mot « için », qui se prononce « i-tchine », veut dire pour. Contrairement au français, il ne se place pas avant mais après ce qu'il introduit : on dit « sizin için », mot à mot vous pour. Pour exprimer un but, on met le verbe à l'infinitif puis « için » : « benzin almak için », pour prendre de l'essence, « Kaş'a gitmek için », pour aller à Kaş. Avec les pronoms, on emploie la forme du possesseur : « benim için », pour moi, « sizin için », pour vous. On le retrouve aussi dans les remerciements : « yardımınız için teşekkürler », merci pour votre aide. Retenez simplement que « için » ferme la phrase de but, comme une porte qu'on referme derrière soi.","lit":"essence · prendre · pour · ici · arrêtons-nous","say":{"İçin":"İçin","için":"için","sizin için":"sizin için","benzin almak için":"benzin almak için","Kaş'a gitmek için":"Kaş'a gitmek için","benim için":"benim için","yardımınız için teşekkürler":"yardımınız için teşekkürler"}}},{"title":"Une panne au bord de la route","phrases":[{"fr":"Le voyant du moteur vient de s'allumer.","tgt":"Motor arıza lambası az önce yandı."},{"fr":"On dirait qu'on a crevé un pneu.","tgt":"Galiba lastiğimiz patladı."},{"fr":"Garons-nous sur le bas-côté, en sécurité.","tgt":"Güvenli bir şekilde yol kenarına çekelim."},{"fr":"La roue de secours est dans le coffre, sous le tapis.","tgt":"Yedek lastik bagajda, paspasın altında."},{"fr":"Je n'ai aucun réseau, impossible d'appeler l'agence.","tgt":"Telefon hiç çekmiyor, şirketi arayamıyorum."},{"fr":"Un berger s'est arrêté pour nous donner un coup de main.","tgt":"Bir çoban bize yardım etmek için durdu."},{"fr":"Le garage le plus proche est à quinze kilomètres.","tgt":"En yakın tamirci on beş kilometre uzakta."},{"fr":"Le mécanicien a dit que la réparation prendrait une heure.","tgt":"Tamirci tamirin bir saat süreceğini söyledi."},{"fr":"En attendant, on nous a offert du thé et des figues.","tgt":"Bu arada bize çay ve incir ikram ettiler."},{"fr":"Finalement, cette panne nous a laissé un beau souvenir.","tgt":"Sonuçta bu arıza bize güzel bir anı bıraktı."}]},{"title":"Le théâtre d'Aspendos","phrases":[{"fr":"Le théâtre d'Aspendos est remarquablement bien conservé.","tgt":"Aspendos Tiyatrosu şaşırtıcı derecede iyi korunmuş."},{"fr":"Il a été construit il y a près de deux mille ans.","tgt":"Yaklaşık iki bin yıl önce inşa edilmiş."},{"fr":"Assis tout en haut, on entend chaque mot prononcé sur scène.","tgt":"En tepede oturunca sahnede söylenen her kelime duyuluyor."},{"fr":"L'acoustique est si parfaite qu'un murmure suffit.","tgt":"Akustik o kadar mükemmel ki bir fısıltı yetiyor."},{"fr":"En été, on y donne encore des spectacles de danse.","tgt":"Yazın burada hâlâ dans gösterileri yapılıyor."},{"fr":"L'aqueduc antique s'étend sur des kilomètres dans la plaine.","tgt":"Antik su kemeri ovada kilometrelerce uzanıyor."},{"fr":"Ces pierres ont été taillées et posées à la main.","tgt":"Bu taşlar elle yontulup yerleştirilmiş."},{"fr":"On se sent tout petit face à ces gradins immenses.","tgt":"Bu devasa basamakların karşısında insan kendini küçücük hissediyor."},{"fr":"Notre guide a raconté la légende de la construction du théâtre.","tgt":"Rehberimiz tiyatronun yapılışıyla ilgili efsaneyi anlattı."},{"fr":"Venez au coucher du soleil, la lumière est magique.","tgt":"Gün batımında gelin, ışık büyüleyici."}]},{"title":"Le regret : « keşke » et « gitseydim », si seulement j'étais allé","phrases":[{"fr":"Si seulement j'étais allé à Termessos !","tgt":"Keşke Termessos'a gitseydim!"},{"fr":"Si seulement nous avions réservé plus tôt !","tgt":"Keşke daha erken rezervasyon yapsaydık!"},{"fr":"J'aurais dû prendre un chapeau, le soleil tape fort.","tgt":"Keşke şapka alsaydım, güneş çok yakıyor."},{"fr":"Si seulement on était restés une nuit de plus !","tgt":"Keşke bir gece daha kalsaydık!"},{"fr":"Si j'avais su, j'aurais pris le bus de nuit.","tgt":"Bilseydim gece otobüsüne binerdim."},{"fr":"Si seulement vous nous aviez prévenus !","tgt":"Keşke bizi önceden uyarsaydınız!"},{"fr":"Le dernier bus est parti sans nous.","tgt":"Son otobüs bizsiz gitti."},{"fr":"Si seulement j'avais pris mon appareil photo !","tgt":"Keşke fotoğraf makinemi yanıma alsaydım!"},{"fr":"Tant pis, on ira la prochaine fois.","tgt":"Neyse, bir dahaki sefere gideriz."},{"fr":"Je ne regrette rien, ce détour en valait vraiment la peine.","tgt":"Hiç pişman değilim, yolu uzatmamıza gerçekten değdi."}],"tip":{"title":"Le regret : « keşke » et « gitseydim », si seulement j'étais allé","example":"Si seulement j'étais allé à Termessos ! — <b>Keşke</b> Termessos'a <b>gitseydim</b>!","body":"Pour exprimer un regret, le turc ouvre la phrase avec « keşke », prononcé « kech-ké », qui veut dire si seulement. Le verbe prend ensuite deux petits morceaux à la suite : « se » pour la condition, puis « ydi » pour le passé, et enfin la personne. Ainsi « git », aller, devient « gitseydim », si j'étais allé, mot à mot aller, si, passé, je. On dit de même « kalsaydık », si nous étions restés, ou « yapsaydık », si nous avions fait. Sans « keşke », la même forme sert à dire si j'avais su : « bilseydim ». Pour retenir, écoutez le « seydi » au milieu du mot : il sonne comme un petit soupir de regret.","lit":"si-seulement · Termessos-à · aller-si-[passé]-je","say":{"keşke":"keşke","gitseydim":"gitseydim","kalsaydık":"kalsaydık","yapsaydık":"yapsaydık","bilseydim":"bilseydim"}}},{"title":"Arrivée à Fethiye","phrases":[{"fr":"Après six heures de route, nous voici enfin à Fethiye.","tgt":"Altı saatlik yolculuktan sonra nihayet Fethiye'deyiz."},{"fr":"La baie est entourée de collines couvertes de pins.","tgt":"Körfez çam ağaçlarıyla kaplı tepelerle çevrili."},{"fr":"Au-dessus de la ville, on voit des tombeaux taillés dans la roche.","tgt":"Şehrin yukarısında kayalara oyulmuş mezarlar görülüyor."},{"fr":"Au marché aux poissons, on choisit son poisson et on le fait griller à côté.","tgt":"Balık pazarında balığınızı seçiyorsunuz, yandaki lokantada pişiriyorlar."},{"fr":"Nous avons loué un petit appartement près du port.","tgt":"Limanın yakınında küçük bir daire tuttuk."},{"fr":"La propriétaire parle un peu français, quelle chance !","tgt":"Ev sahibi biraz Fransızca konuşuyor, ne şans!"},{"fr":"Elle nous a montré où garer la voiture la nuit.","tgt":"Geceleri arabayı nereye park edeceğimizi gösterdi."},{"fr":"Le soir, toute la ville se promène le long du front de mer.","tgt":"Akşamları bütün şehir sahil boyunca yürüyüş yapıyor."},{"fr":"Ici, la vie s'écoule plus lentement qu'à Antalya.","tgt":"Burada hayat Antalya'dan daha yavaş akıyor."},{"fr":"Je crois qu'on va beaucoup se plaire ici.","tgt":"Sanırım burayı çok seveceğiz."}]},{"title":"Une croisière en goélette","phrases":[{"fr":"Nous avons réservé une croisière de trois jours en goélette.","tgt":"Üç günlük bir gület turuna yer ayırttık."},{"fr":"Le capitaine nous a accueillis à bord avec un grand sourire.","tgt":"Kaptan bizi tekneye kocaman bir gülümsemeyle buyur etti."},{"fr":"Les cabines sont petites, mais on dort sur le pont.","tgt":"Kamaralar küçük ama güvertede uyuyoruz."},{"fr":"Le cuisinier prépare tous les repas à bord.","tgt":"Aşçı bütün yemekleri teknede hazırlıyor."},{"fr":"On jette l'ancre dans des criques inaccessibles par la route.","tgt":"Karayoluyla ulaşılamayan koylarda demir atıyoruz."},{"fr":"L'eau est si claire qu'on voit le fond à dix mètres.","tgt":"Su o kadar berrak ki on metre aşağıdaki dip bile görünüyor."},{"fr":"Qui veut sauter du toit de la cabine ?","tgt":"Kim kamaranın üstünden atlamak ister?"},{"fr":"Je n'ai pas eu le mal de mer, contrairement à ce que je craignais.","tgt":"Korktuğumun aksine beni hiç deniz tutmadı."},{"fr":"La nuit, on voit plus d'étoiles qu'on n'en a jamais vu.","tgt":"Geceleri hayatımızda gördüğümüzden daha çok yıldız görüyoruz."},{"fr":"Ces trois jours en mer sont passés comme un rêve.","tgt":"Denizdeki bu üç gün bir rüya gibi geçti."}]},{"title":"L'excursion des douze îles","phrases":[{"fr":"L'excursion des douze îles part du port à dix heures.","tgt":"On iki adalar turu limandan saat onda kalkıyor."},{"fr":"Combien coûte la journée, déjeuner compris ?","tgt":"Öğle yemeği dahil günlüğü ne kadar?"},{"fr":"Pensez à prendre de la crème solaire et une serviette.","tgt":"Güneş kremi ve havlu almayı unutmayın."},{"fr":"La première baignade a lieu dans une grotte marine.","tgt":"İlk yüzme molası bir deniz mağarasında."},{"fr":"On a vu une tortue de mer nager juste à côté du bateau.","tgt":"Teknenin hemen yanında yüzen bir deniz kaplumbağası gördük."},{"fr":"Faites attention, les rochers sont glissants.","tgt":"Dikkat edin, kayalar kaygan."},{"fr":"Sur cette île, des pêcheurs vivent encore toute l'année.","tgt":"Bu adada hâlâ yıl boyunca balıkçılar yaşıyor."},{"fr":"Le déjeuner est servi sur le pont : poisson grillé et salade.","tgt":"Öğle yemeği güvertede servis ediliyor: ızgara balık ve salata."},{"fr":"La musique à bord était un peu trop forte à mon goût.","tgt":"Teknedeki müzik bana göre biraz fazla yüksekti."},{"fr":"Nous sommes rentrés bronzés et heureux.","tgt":"Bronzlaşmış ve mutlu döndük."}]},{"title":"Du parapente à Ölüdeniz","phrases":[{"fr":"Depuis le mont Babadağ, les parapentes descendent vers le lagon.","tgt":"Babadağ'dan yamaç paraşütçüleri lagüne doğru süzülüyor."},{"fr":"Vous avez déjà fait du parapente ?","tgt":"Daha önce yamaç paraşütü yaptınız mı?"},{"fr":"On vole en tandem avec un pilote expérimenté.","tgt":"Deneyimli bir pilotla birlikte tandem uçuş yapıyorsunuz."},{"fr":"J'ai le vertige, mais je veux essayer quand même.","tgt":"Yükseklik korkum var ama yine de denemek istiyorum."},{"fr":"Il suffit de courir quelques pas, et on décolle.","tgt":"Birkaç adım koşmanız yeterli, sonra havalanıyorsunuz."},{"fr":"Vu d'en haut, le lagon a une couleur incroyable.","tgt":"Yukarıdan bakınca lagünün rengi inanılmaz."},{"fr":"Le vol dure environ une demi-heure.","tgt":"Uçuş yaklaşık yarım saat sürüyor."},{"fr":"J'ai crié au début, puis j'ai tout savouré.","tgt":"Başta bağırdım, sonra her anın tadını çıkardım."},{"fr":"L'atterrissage sur la plage s'est fait en douceur.","tgt":"Plaja iniş çok yumuşak oldu."},{"fr":"La vidéo du vol coûte un supplément.","tgt":"Uçuş videosu için ayrıca ücret alınıyor."}]},{"title":"« -meli » : il faudrait, on devrait","phrases":[{"fr":"On devrait partir avant le lever du soleil.","tgt":"Güneş doğmadan yola çıkmalıyız."},{"fr":"Il faudrait emporter au moins trois litres d'eau chacun.","tgt":"Her birimiz en az üç litre su almalıyız."},{"fr":"Vous devriez porter de vraies chaussures de marche.","tgt":"Gerçek yürüyüş ayakkabısı giymelisiniz."},{"fr":"Il faut suivre les marques rouges et blanches.","tgt":"Kırmızı beyaz işaretleri takip etmelisiniz."},{"fr":"On ne devrait pas marcher seuls sur ce tronçon.","tgt":"Bu etapta yalnız yürümemeliyiz."},{"fr":"Je devrais m'entraîner un peu avant le grand départ.","tgt":"Büyük yolculuktan önce biraz antrenman yapmalıyım."},{"fr":"Où devrait-on dormir le premier soir ?","tgt":"İlk gece nerede kalmalıyız?"},{"fr":"Il faudrait prévenir la pension de notre arrivée.","tgt":"Pansiyona geleceğimizi haber vermeliyiz."},{"fr":"La voie lycienne fait plus de cinq cents kilomètres.","tgt":"Likya Yolu beş yüz kilometreden uzun."},{"fr":"Nous n'en ferons qu'une petite partie, en quatre jours.","tgt":"Biz sadece küçük bir kısmını dört günde yürüyeceğiz."}],"tip":{"title":"« -meli » : il faudrait, on devrait","example":"On devrait partir avant le lever du soleil. — Güneş doğmadan yola <b>çıkmalıyız</b>.","body":"Pour dire qu'il faut ou qu'on devrait faire quelque chose, le turc n'utilise pas de verbe devoir séparé : il colle « -meli » ou « -malı » au verbe, selon les voyelles, puis la personne. « Çıkmak », partir, devient « çıkmalıyız », nous devons partir, mot à mot partir, devoir, nous. De même, « gitmeliyim », je dois y aller, et « giymelisiniz », vous devriez porter. Pour la négation, on glisse « me » juste avant : « yürümemeliyiz », nous ne devrions pas marcher. À l'oral, le ton suffit souvent à distinguer le conseil amical de l'obligation ferme. Pour retenir, pensez à « malin » : il est malin de partir tôt, « çıkmalıyız ».","lit":"soleil · se-lever-sans · route-à · sortir-devoir-nous","say":{"Çıkmak":"Çıkmak","çıkmalıyız":"çıkmalıyız","gitmeliyim":"gitmeliyim","giymelisiniz":"giymelisiniz","yürümemeliyiz":"yürümemeliyiz"}}},{"title":"Sur la voie lycienne","phrases":[{"fr":"Le sentier serpente entre les oliviers et la mer.","tgt":"Patika zeytin ağaçlarıyla deniz arasında kıvrılıyor."},{"fr":"Ça grimpe sec, faisons une pause à l'ombre.","tgt":"Yokuş çok dik, gölgede mola verelim."},{"fr":"Regardez, une tombe lycienne au milieu du chemin !","tgt":"Bakın, yolun ortasında bir Likya mezarı!"},{"fr":"Nous avons croisé un troupeau de chèvres.","tgt":"Bir keçi sürüsüyle karşılaştık."},{"fr":"Je crois qu'on s'est trompés de chemin.","tgt":"Galiba yolu şaşırdık."},{"fr":"La dernière marque était près de ce gros rocher.","tgt":"Son işaret şu büyük kayanın yanındaydı."},{"fr":"Mes pieds me font mal, mais la vue en vaut la peine.","tgt":"Ayaklarım ağrıyor ama manzara buna değer."},{"fr":"On remplit nos gourdes à la fontaine du village.","tgt":"Mataralarımızı köyün çeşmesinden dolduruyoruz."},{"fr":"Il nous reste encore deux heures avant l'étape.","tgt":"Konaklama yerine daha iki saatimiz var."},{"fr":"En arrivant, je n'avais qu'une envie : me baigner.","tgt":"Varınca tek isteğim denize girmekti."}]},{"title":"Une nuit chez l'habitant","phrases":[{"fr":"Une famille du village loue des chambres aux randonneurs.","tgt":"Köyden bir aile yürüyüşçülere oda kiralıyor."},{"fr":"La grand-mère prépare des gözleme sur une grande plaque.","tgt":"Nine büyük bir sacın üstünde gözleme yapıyor."},{"fr":"Tout ce qu'on mange vient de leur jardin.","tgt":"Yediğimiz her şey kendi bahçelerinden geliyor."},{"fr":"Ils nous ont invités à dîner avec eux sur la terrasse.","tgt":"Bizi terasta onlarla akşam yemeğine davet ettiler."},{"fr":"Malgré la barrière de la langue, on s'est bien compris.","tgt":"Dil engeline rağmen birbirimizi iyi anladık."},{"fr":"Le grand-père nous a raconté sa jeunesse de berger.","tgt":"Dede bize çobanlık yaptığı gençlik yıllarını anlattı."},{"fr":"Le matin, on a été réveillés par les coqs.","tgt":"Sabah horozların sesiyle uyandık."},{"fr":"Le petit-déjeuner était royal : miel, fromage, olives et œufs.","tgt":"Kahvaltı muhteşemdi: bal, peynir, zeytin ve yumurta."},{"fr":"Combien vous doit-on pour la nuit et les repas ?","tgt":"Gece ve yemekler için borcumuz ne kadar?"},{"fr":"Ils ont refusé qu'on paie le dîner.","tgt":"Akşam yemeği için para almak istemediler."}]},{"title":"Kaş et la plongée","phrases":[{"fr":"Kaş est un petit port tranquille aux maisons blanches.","tgt":"Kaş beyaz evleriyle sakin, küçük bir liman kasabası."},{"fr":"On dit que c'est l'un des meilleurs endroits pour plonger.","tgt":"Dalış için en iyi yerlerden biri olduğu söyleniyor."},{"fr":"Je n'ai jamais plongé, c'est possible pour un débutant ?","tgt":"Hiç dalmadım, yeni başlayan biri için mümkün mü?"},{"fr":"Le moniteur nous explique d'abord les signes de sécurité.","tgt":"Eğitmen önce güvenlik işaretlerini anlatıyor."},{"fr":"Nous sommes descendus jusqu'à douze mètres.","tgt":"On iki metreye kadar indik."},{"fr":"Il y a une épave d'avion au fond de la baie.","tgt":"Koyun dibinde bir uçak enkazı var."},{"fr":"J'ai vu un mérou énorme caché sous un rocher.","tgt":"Bir kayanın altına saklanmış kocaman bir orfoz gördüm."},{"fr":"Après une plongée, on ne prend pas l'avion avant vingt-quatre heures.","tgt":"Dalıştan sonra yirmi dört saat uçağa binilmez."},{"fr":"Le soir, les petites rues s'illuminent de lampions.","tgt":"Akşamları dar sokaklar fenerlerle aydınlanıyor."},{"fr":"Nous avons décidé de prolonger notre séjour à Kaş.","tgt":"Kaş'ta kalışımızı uzatmaya karar verdik."}]},{"title":"Kekova, la cité engloutie","phrases":[{"fr":"Nous avons loué un kayak de mer pour aller jusqu'à Kekova.","tgt":"Kekova'ya kadar gitmek için deniz kanosu kiraladık."},{"fr":"Sous l'eau, on devine les restes d'une ville engloutie.","tgt":"Suyun altında batık bir şehrin kalıntıları seçiliyor."},{"fr":"Il est interdit de se baigner au-dessus des ruines.","tgt":"Kalıntıların üzerinde yüzmek yasak."},{"fr":"Un tremblement de terre a fait sombrer une partie de la ville.","tgt":"Bir deprem şehrin bir bölümünü sulara gömmüş."},{"fr":"Le village de Kaleköy n'est accessible qu'en bateau.","tgt":"Kaleköy'e sadece tekneyle ulaşılabiliyor."},{"fr":"On est montés jusqu'au château pour la vue.","tgt":"Manzara için kaleye kadar çıktık."},{"fr":"Une vieille dame vendait des glaces faites maison.","tgt":"Yaşlı bir teyze ev yapımı dondurma satıyordu."},{"fr":"Pagayer contre le vent, c'est épuisant !","tgt":"Rüzgâra karşı kürek çekmek çok yorucu!"},{"fr":"Le paysage n'a sûrement pas changé depuis des siècles.","tgt":"Manzara yüzyıllardır pek değişmemiştir herhalde."},{"fr":"C'est l'endroit le plus paisible de tout notre voyage.","tgt":"Burası bütün yolculuğumuzun en huzurlu yeri."}]},{"title":"Rencontrer d'autres voyageurs","phrases":[{"fr":"Vous voyagez seule depuis longtemps ?","tgt":"Uzun zamandır tek başınıza mı seyahat ediyorsunuz?"},{"fr":"Nous nous sommes rencontrés sur le bateau pour Kekova.","tgt":"Kekova teknesinde tanıştık."},{"fr":"Il est infirmier et prend un an pour voyager.","tgt":"Kendisi hemşire, seyahat etmek için bir yıl izin almış."},{"fr":"Elle connaît la région bien mieux que nous.","tgt":"Bölgeyi bizden çok daha iyi tanıyor."},{"fr":"Elle nous a conseillé un village où les touristes ne vont pas.","tgt":"Bize turistlerin gitmediği bir köy önerdi."},{"fr":"On pourrait faire un bout de route ensemble, si vous voulez.","tgt":"İsterseniz yolun bir kısmını birlikte yapabiliriz."},{"fr":"Échangeons nos numéros pour rester en contact.","tgt":"İletişimde kalmak için numaralarımızı paylaşalım."},{"fr":"Quelle a été la plus belle étape de votre voyage ?","tgt":"Yolculuğunuzun en güzel durağı hangisiydi?"},{"fr":"Si vous passez un jour par la France, venez nous voir.","tgt":"Bir gün Fransa'ya yolunuz düşerse bize uğrayın."},{"fr":"Ces rencontres font tout le sel du voyage.","tgt":"Yolculuğun asıl tadını bu karşılaşmalar veriyor."}]},{"title":"« Gittikçe » : de plus en plus","phrases":[{"fr":"Le ciel devient de plus en plus sombre.","tgt":"Gökyüzü gittikçe kararıyor."},{"fr":"Le vent souffle de plus en plus fort.","tgt":"Rüzgâr gittikçe sertleşiyor."},{"fr":"Les vagues deviennent de plus en plus hautes.","tgt":"Dalgalar gittikçe büyüyor."},{"fr":"Le capitaine a décidé de rentrer au port.","tgt":"Kaptan limana dönmeye karar verdi."},{"fr":"La pluie tombe de plus en plus dru.","tgt":"Yağmur gittikçe şiddetleniyor."},{"fr":"J'avais de plus en plus froid sous mon imperméable.","tgt":"Yağmurluğumun altında gittikçe üşüyordum."},{"fr":"On s'est abrités dans un café au bord de l'eau.","tgt":"Su kenarındaki bir kahveye sığındık."},{"fr":"Peu à peu, le ciel s'est éclairci.","tgt":"Yavaş yavaş gökyüzü açıldı."},{"fr":"Les orages sont de plus en plus fréquents en cette saison.","tgt":"Bu mevsimde fırtınalar gittikçe sıklaşıyor."},{"fr":"Le soir, la mer était de nouveau calme.","tgt":"Akşam deniz yine sakindi."}],"tip":{"title":"« Gittikçe » : de plus en plus","example":"Le ciel devient de plus en plus sombre. — Gökyüzü <b>gittikçe</b> kararıyor.","body":"Là où le français a besoin de quatre mots, de plus en plus, le turc n'en utilise qu'un : « gittikçe », prononcé « guit-tik-tché ». Il vient du verbe aller et signifie littéralement au fur et à mesure qu'on va. On le place juste avant le verbe qui évolue : « gökyüzü gittikçe kararıyor », mot à mot ciel, de plus en plus, s'assombrit. Souvent, le verbe lui-même porte l'idée de changement : « büyüyor », ça grandit, « sertleşiyor », ça devient plus fort. On peut aussi ajouter « daha », plus : « gittikçe daha güzel », de plus en plus beau. Le même moule donne « gün geçtikçe », de jour en jour, une formule très utile pour parler de vos progrès.","lit":"ciel · de-plus-en-plus · s'assombrit","say":{"Gittikçe":"Gittikçe","gittikçe":"gittikçe","gökyüzü gittikçe kararıyor":"gökyüzü gittikçe kararıyor","büyüyor":"büyüyor","sertleşiyor":"sertleşiyor","daha":"daha","gittikçe daha güzel":"gittikçe daha güzel","gün geçtikçe":"gün geçtikçe"}}},{"title":"Raconter son voyage","phrases":[{"fr":"Je vais vous raconter comment s'est passé notre voyage.","tgt":"Size yolculuğumuzun nasıl geçtiğini anlatayım."},{"fr":"Tout a commencé par une panne sur la route d'Antalya.","tgt":"Her şey Antalya yolunda bir arızayla başladı."},{"fr":"Ce qui m'a le plus marqué, c'est l'hospitalité des gens.","tgt":"Beni en çok etkileyen, insanların misafirperverliği oldu."},{"fr":"Un soir, nous avons dormi à la belle étoile sur un bateau.","tgt":"Bir akşam teknede yıldızların altında uyuduk."},{"fr":"Il y a eu quelques imprévus, mais rien de grave.","tgt":"Birkaç aksilik oldu ama ciddi bir şey olmadı."},{"fr":"Le jour le plus dur a été celui de la randonnée sous la chaleur.","tgt":"En zor gün sıcakta yürüdüğümüz gündü."},{"fr":"On m'avait dit que la côte était belle, mais à ce point !","tgt":"Kıyının güzel olduğunu söylemişlerdi ama bu kadarını beklemiyordum!"},{"fr":"Regardez cette photo, c'était juste avant l'orage.","tgt":"Şu fotoğrafa bakın, fırtınadan hemen önceydi."},{"fr":"J'ai rapporté de l'huile d'olive et du miel de pin.","tgt":"Zeytinyağı ve çam balı getirdim."},{"fr":"Racontez-moi votre voyage à votre tour.","tgt":"Siz de bana yolculuğunuzu anlatın."}]},{"title":"Fin du module : un bilan de voyage","phrases":[{"fr":"Ce module consacré au voyage touche à sa fin.","tgt":"Yolculuğa ayrılan bu modül sona eriyor."},{"fr":"Je peux maintenant louer une voiture en turc.","tgt":"Artık Türkçe araba kiralayabiliyorum."},{"fr":"Je sais exprimer un regret avec « keşke ».","tgt":"\"Keşke\" ile pişmanlığımı ifade edebiliyorum."},{"fr":"Je sais décrire les lieux que j'ai visités.","tgt":"Gezdiğim yerleri anlatabiliyorum."},{"fr":"Je sais dire ce qu'il faudrait faire face à un imprévu.","tgt":"Beklenmedik bir durumda ne yapmak gerektiğini söyleyebiliyorum."},{"fr":"Je comprends mieux les gens que je rencontre en chemin.","tgt":"Yolda tanıştığım insanları daha iyi anlıyorum."},{"fr":"Mon turc devient de plus en plus naturel.","tgt":"Türkçem gittikçe daha doğal oluyor."},{"fr":"Il me reste encore beaucoup de vocabulaire à apprendre.","tgt":"Daha öğrenmem gereken çok kelime var."},{"fr":"Le prochain module portera sur la conversation sociale.","tgt":"Bir sonraki modül sosyal sohbet üzerine olacak."},{"fr":"Bravo, et à bientôt pour de nouvelles aventures en turc !","tgt":"Tebrikler, Türkçe yeni maceralarda görüşmek üzere!"}]}]},{"id":3,"name":"Conversation sociale","desc":"Des conversations profondes : opinions, débats, émotions.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Un soir sur les rives du Bosphore","phrases":[{"fr":"Depuis qu'il a appris la nouvelle, il a le sourire jusqu'aux oreilles.","tgt":"Haberi duyduğundan beri ağzı kulaklarında."},{"fr":"Ce soir, le Bosphore est d'un calme incroyable.","tgt":"Bu akşam Boğaz inanılmaz sakin."},{"fr":"Ma mère m'attend avec une grande impatience.","tgt":"Annem beni dört gözle bekliyor."},{"fr":"Ma fille est folle de joie, demain nous partons en vacances.","tgt":"Kızımın etekleri zil çalıyor, yarın tatile çıkıyoruz."},{"fr":"Excusez-moi, j'ai entendu votre conversation sans le vouloir.","tgt":"Kusura bakmayın, istemeden konuşmanıza kulak misafiri oldum."},{"fr":"Trouver cet appartement m'a donné un mal fou.","tgt":"Bu daireyi bulmak burnumdan geldi."},{"fr":"Notre voisin sait vraiment tout faire de ses mains.","tgt":"Komşumuzun elinden her iş gelir."},{"fr":"Aujourd'hui, j'ai la tête ailleurs.","tgt":"Bugün aklım başka yerde."},{"fr":"Ce petit café de Balat m'a tapé dans l'œil dès le premier regard.","tgt":"Balat'taki bu küçük kafeyi ilk görüşte gözüm tuttu."},{"fr":"Cette mésaventure m'a servi de leçon.","tgt":"Bu olay kulağıma küpe oldu."}],"tip":{"title":"Les expressions imagées : « ağzı kulaklarında », la bouche jusqu'aux oreilles","example":"Depuis qu'il a appris la nouvelle, il a le sourire jusqu'aux oreilles. — Haberi duyduğundan beri <b>ağzı kulaklarında</b>.","body":"Le turc adore parler avec le corps : la bouche, les yeux, les oreilles et les mains reviennent sans cesse dans les expressions de tous les jours. « Ağzı kulaklarında » se décompose en « ağzı », sa bouche, puis « kulaklarında », dans ses oreilles : sa bouche est dans ses oreilles, exactement comme notre sourire jusqu'aux oreilles. On garde l'image et on change seulement le possessif : « ağzım kulaklarımda » pour moi, « ağzınız kulaklarınızda » pour vous. Avec l'oreille, on dit aussi « kulak misafiri olmak », être l'invité de l'oreille, c'est-à-dire entendre sans le vouloir, et « kulağıma küpe oldu », c'est devenu une boucle d'oreille, pour une leçon qu'on n'oubliera plus. Astuce : apprenez ces expressions comme de petites images, et glissez-en une dans chaque conversation, vos amis turcs seront ravis.","lit":"nouvelle-la · entendu-son · depuis · bouche-sa · oreilles-ses-dans","say":{"ağzı kulaklarında":"ağzı kulaklarında","Ağzı kulaklarında":"Ağzı kulaklarında","ağzı":"ağzı","kulaklarında":"kulaklarında","ağzım kulaklarımda":"ağzım kulaklarımda","ağzınız kulaklarınızda":"ağzınız kulaklarınızda","kulak misafiri olmak":"kulak misafiri olmak","kulağıma küpe oldu":"kulağıma küpe oldu"}}},{"title":"Les souvenirs d'enfance","phrases":[{"fr":"Quand j'étais enfant, je passais mes étés chez ma grand-mère.","tgt":"Çocukken yazlarımı anneannemin yanında geçirirdim."},{"fr":"Sa maison sentait toujours le pain chaud.","tgt":"Evi hep sıcak ekmek kokardı."},{"fr":"On jouait au ballon dans la rue jusqu'à la tombée de la nuit.","tgt":"Akşam karanlığına kadar sokakta top oynardık."},{"fr":"Nos mères nous appelaient par la fenêtre pour le dîner.","tgt":"Annelerimiz pencereden bizi yemeğe çağırırdı."},{"fr":"Je me souviens encore de l'odeur des simits du matin.","tgt":"Sabah simitlerinin kokusunu hâlâ hatırlıyorum."},{"fr":"Mon grand-père me racontait des contes avant de dormir.","tgt":"Dedem uyumadan önce bana masal anlatırdı."},{"fr":"Le quartier où j'ai grandi a beaucoup changé.","tgt":"Büyüdüğüm mahalle çok değişti."},{"fr":"Je n'oublierai jamais le jour où j'ai vu la mer pour la première fois.","tgt":"Denizi ilk gördüğüm günü asla unutmayacağım."},{"fr":"À l'époque, on n'avait pas de téléphone, mais on ne s'ennuyait jamais.","tgt":"O zamanlar telefonumuz yoktu ama hiç sıkılmazdık."},{"fr":"Parfois, je voudrais retrouver ces jours insouciants.","tgt":"Bazen o tasasız günlere geri dönmek isterdim."}]},{"title":"Un dîner chez des amis à Balat","phrases":[{"fr":"Passez à table, tout est prêt.","tgt":"Sofraya buyurun, her şey hazır."},{"fr":"Merci pour ce festin, tout était délicieux.","tgt":"Ellerinize sağlık, her şey çok lezzetliydi."},{"fr":"Avec plaisir, je suis content que ça vous ait plu.","tgt":"Afiyet olsun, beğenmenize sevindim."},{"fr":"À vos souhaits !","tgt":"Çok yaşayın!"},{"fr":"Merci, je vous en souhaite autant.","tgt":"Siz de görün, teşekkür ederim."},{"fr":"Votre voiture est neuve ? Profitez-en bien !","tgt":"Arabanız yeni mi? Güle güle kullanın!"},{"fr":"Votre robe est superbe, portez-la avec bonheur.","tgt":"Elbiseniz çok güzel, güle güle giyin."},{"fr":"Bon courage en cuisine, je peux vous aider ?","tgt":"Mutfakta kolay gelsin, yardım edebilir miyim?"},{"fr":"Remettez-vous vite, j'espère que ce n'est pas grave.","tgt":"Geçmiş olsun, umarım ciddi bir şey değildir."},{"fr":"Votre nouvel appartement est magnifique, soyez-y heureux.","tgt":"Yeni eviniz harika, güle güle oturun."}],"tip":{"title":"Les formules du quotidien : « eline sağlık », « çok yaşa », « güle güle kullan »","example":"Merci pour ce festin, tout était délicieux. — <b>Ellerinize sağlık</b>, her şey çok lezzetliydi.","body":"La vie sociale turque est rythmée par de petites formules toutes faites, qu'on prononce presque par réflexe. Après un bon repas, on remercie la personne qui a cuisiné avec « eline sağlık », santé à ta main, ou au pluriel poli « ellerinize sağlık », santé à vos mains, et elle répond « afiyet olsun », bon appétit. Quand quelqu'un éternue, on lance « çok yaşa », vis longtemps, ou « çok yaşayın » pour vouvoyer, et la personne répond « sen de gör », toi aussi vois-le, c'est-à-dire je t'en souhaite autant. Devant un objet neuf, voiture ou téléphone, on dit « güle güle kullan », utilise-le en riant, et pour un vêtement « güle güle giy », porte-le en riant. Astuce : dès que vous voyez quelque chose de nouveau ou quelqu'un qui travaille, cherchez la formule, il y en a presque toujours une.","lit":"mains-vos-à · santé · chaque · chose · très · délicieux-était","say":{"eline sağlık":"eline sağlık","çok yaşa":"çok yaşa","güle güle kullan":"güle güle kullan","ellerinize sağlık":"ellerinize sağlık","afiyet olsun":"afiyet olsun","çok yaşayın":"çok yaşayın","sen de gör":"sen de gör","güle güle giy":"güle güle giy"}}},{"title":"Donner son avis et nuancer","phrases":[{"fr":"À mon avis, Istanbul est la plus belle ville du monde.","tgt":"Bence İstanbul dünyanın en güzel şehri."},{"fr":"Je ne suis pas tout à fait d'accord avec vous.","tgt":"Size tamamen katılmıyorum."},{"fr":"Je pense que les gens devraient prendre davantage le ferry.","tgt":"Bence insanlar daha çok vapura binmeli."},{"fr":"D'un côté vous avez raison, mais de l'autre, ce n'est pas si simple.","tgt":"Bir yandan haklısınız ama öte yandan iş o kadar basit değil."},{"fr":"Ce que vous dites me fait réfléchir.","tgt":"Söyledikleriniz beni düşündürüyor."},{"fr":"Il me semble que la ville change trop vite.","tgt":"Bana öyle geliyor ki şehir çok hızlı değişiyor."},{"fr":"Chacun peut avoir son propre avis.","tgt":"Herkesin kendi fikri olabilir."},{"fr":"Je n'avais jamais vu les choses sous cet angle.","tgt":"Bunu hiç bu açıdan düşünmemiştim."},{"fr":"Si vous voulez mon avis, il vaut mieux attendre.","tgt":"Bana sorarsanız beklemek daha iyi."},{"fr":"Finalement, nous pensons à peu près la même chose.","tgt":"Sonuçta aşağı yukarı aynı şeyi düşünüyoruz."}]},{"title":"Impressions de Balat","phrases":[{"fr":"Ces maisons colorées ressemblent à un tableau.","tgt":"Bu renkli evler bir tablo gibi."},{"fr":"On dirait que le temps s'est arrêté dans cette rue.","tgt":"Bu sokakta sanki zaman durmuş."},{"fr":"Il parle turc comme un vrai Stambouliote.","tgt":"Gerçek bir İstanbullu gibi Türkçe konuşuyor."},{"fr":"J'ai l'impression de connaître cet endroit depuis des années.","tgt":"Burayı sanki yıllardır tanıyorum."},{"fr":"J'ai comme l'impression de rêver.","tgt":"Sanki rüya görüyormuşum gibi hissediyorum."},{"fr":"Ce café est comme une deuxième maison pour nous.","tgt":"Bu kafe bizim için ikinci bir ev gibi."},{"fr":"Comme je vous l'ai dit, le quartier est très ancien.","tgt":"Size söylediğim gibi, mahalle çok eski."},{"fr":"Le vieil homme nous regarde comme s'il nous connaissait.","tgt":"Yaşlı adam bize sanki bizi tanıyormuş gibi bakıyor."},{"fr":"On dirait qu'il va pleuvoir.","tgt":"Yağmur yağacak gibi görünüyor."},{"fr":"Mettez-vous à l'aise, faites comme chez vous.","tgt":"Kendi evinizdeymiş gibi rahat olun."}],"tip":{"title":"« Gibi » et « sanki » : comme, on dirait que","example":"On dirait que le temps s'est arrêté dans cette rue. — Bu sokakta <b>sanki</b> zaman durmuş.","body":"« Gibi » veut dire comme, mais il se place après le mot, à l'inverse du français : « bir tablo gibi », un tableau comme, c'est-à-dire comme un tableau. Il se met aussi après un verbe pour dire on dirait : « yağmur yağacak gibi », la pluie va tomber comme, donc on dirait qu'il va pleuvoir. « Sanki », lui, se place plutôt au début ou au milieu de la phrase et annonce une impression : « sanki zaman durmuş », on dirait que le temps s'est arrêté. Les Turcs aiment combiner les deux, « sanki » au début et « gibi » à la fin, comme deux parenthèses autour de l'impression : « sanki bizi tanıyormuş gibi », comme s'il nous connaissait. Astuce : pensez à « gibi » comme un écho qui vient toujours après, et à « sanki » comme un soupir qui ouvre la phrase.","lit":"cette · rue-dans · comme-si · temps · arrêté-[apparemment]","say":{"Gibi":"Gibi","sanki":"sanki","bir tablo gibi":"bir tablo gibi","yağmur yağacak gibi":"yağmur yağacak gibi","Sanki":"Sanki","sanki zaman durmuş":"sanki zaman durmuş","gibi":"gibi","sanki bizi tanıyormuş gibi":"sanki bizi tanıyormuş gibi"}}},{"title":"Les projets de vie","phrases":[{"fr":"Dans quelques années, j'aimerais passer une partie de l'année à Istanbul.","tgt":"Birkaç yıl sonra yılın bir kısmını İstanbul'da geçirmek istiyorum."},{"fr":"Mon rêve, c'est d'ouvrir une petite librairie.","tgt":"Hayalim küçük bir kitapçı açmak."},{"fr":"Je pense reprendre mes études l'an prochain.","tgt":"Seneye yeniden okumaya başlamayı düşünüyorum."},{"fr":"Avant de prendre une décision, je dois en parler à ma famille.","tgt":"Karar vermeden önce ailemle konuşmam lazım."},{"fr":"Une fois à la retraite, nous parcourrons la Turquie de long en large.","tgt":"Emekli olunca Türkiye'yi baştan başa gezeceğiz."},{"fr":"Ce qui compte pour moi, c'est d'être entouré des gens que j'aime.","tgt":"Benim için önemli olan, sevdiğim insanlarla birlikte olmak."},{"fr":"Je ne sais pas encore où la vie me mènera.","tgt":"Hayatın beni nereye götüreceğini henüz bilmiyorum."},{"fr":"Il ne faut jamais renoncer à ses rêves.","tgt":"İnsan hayallerinden asla vazgeçmemeli."},{"fr":"Et vous, quels sont vos projets pour l'avenir ?","tgt":"Peki sizin gelecek için planlarınız neler?"},{"fr":"J'ai envie d'apprendre à jouer du saz.","tgt":"Saz çalmayı öğrenmek istiyorum."}]},{"title":"Rire ensemble","phrases":[{"fr":"Vous avez vraiment beaucoup d'humour !","tgt":"Çok esprilisiniz!"},{"fr":"Cette histoire m'a fait pleurer de rire.","tgt":"Bu hikâyeye gülmekten gözlerimden yaş geldi."},{"fr":"Je ne comprends pas toujours les blagues en turc.","tgt":"Türkçe fıkraları her zaman anlamıyorum."},{"fr":"Racontez-nous une blague, s'il vous plaît.","tgt":"Bize bir fıkra anlatın lütfen."},{"fr":"Le plus drôle, c'est qu'il ne s'en est même pas rendu compte.","tgt":"İşin en komik yanı, farkına bile varmadı."},{"fr":"Je ris encore chaque fois que j'y repense.","tgt":"Her aklıma geldiğinde hâlâ gülüyorum."},{"fr":"C'était juste une plaisanterie, ne vous fâchez pas.","tgt":"Sadece şakaydı, kızmayın."},{"fr":"Il a le don de faire rire tout le monde.","tgt":"Herkesi güldürmeyi çok iyi biliyor."},{"fr":"On a tellement ri qu'on en avait mal au ventre.","tgt":"Gülmekten karnımıza ağrılar girdi."},{"fr":"Rire ensemble rapproche les gens.","tgt":"Birlikte gülmek insanları yakınlaştırır."}]},{"title":"Les obligations de la vie","phrases":[{"fr":"Malheureusement, je suis obligé de partir tôt ce soir.","tgt":"Maalesef bu akşam erken gitmek zorundayım."},{"fr":"Demain, je dois absolument me lever à six heures.","tgt":"Yarın saat altıda kalkmak zorundayım."},{"fr":"Nous ne sommes pas obligés de tout décider aujourd'hui.","tgt":"Her şeye bugün karar vermek zorunda değiliz."},{"fr":"Vous n'êtes pas obligé de répondre tout de suite.","tgt":"Hemen cevap vermek zorunda değilsiniz."},{"fr":"J'ai dû annuler mon voyage en Cappadoce.","tgt":"Kapadokya gezimi iptal etmek zorunda kaldım."},{"fr":"Avec ces embouteillages, nous avons été obligés de prendre le ferry.","tgt":"Bu trafik yüzünden vapura binmek zorunda kaldık."},{"fr":"Personne ne vous oblige à venir.","tgt":"Kimse sizi gelmeye zorlamıyor."},{"fr":"Est-ce que je suis obligé de réserver à l'avance ?","tgt":"Önceden yer ayırtmak zorunda mıyım?"},{"fr":"Parfois, il faut savoir dire non.","tgt":"Bazen hayır demeyi bilmek gerekir."},{"fr":"Si je n'étais pas obligé de travailler, je resterais une semaine de plus.","tgt":"Çalışmak zorunda olmasam bir hafta daha kalırdım."}],"tip":{"title":"« Gitmek zorundayım » : être obligé de","example":"Malheureusement, je suis obligé de partir tôt ce soir. — Maalesef bu akşam erken <b>gitmek zorundayım</b>.","body":"Pour dire qu'on est obligé de faire quelque chose, le turc prend le verbe à l'infinitif, terminé par « -mek » ou « -mak », puis ajoute « zorunda », dans l'obligation, avec la terminaison de personne. « Gitmek zorundayım » se décompose donc en partir, puis dans l'obligation je suis : je suis obligé de partir. Au passé, on dit « zorunda kaldım », je suis resté dans l'obligation, autrement dit j'ai dû : « iptal etmek zorunda kaldım », j'ai dû annuler. Pour dire qu'on n'est pas obligé, on ajoute simplement « değil » : « zorunda değilsiniz », vous n'êtes pas obligé. Astuce : « zor » veut dire difficile, et l'obligation, c'est justement ce qui nous force un peu la main.","lit":"malheureusement · ce · soir · tôt · partir · obligation-dans-je-suis","say":{"Gitmek zorundayım":"Gitmek zorundayım","zorunda":"zorunda","zorunda kaldım":"zorunda kaldım","iptal etmek zorunda kaldım":"iptal etmek zorunda kaldım","değil":"değil","zorunda değilsiniz":"zorunda değilsiniz","zor":"zor"}}},{"title":"Souvenirs d'école","phrases":[{"fr":"C'est mon institutrice qui m'a donné le goût de la lecture.","tgt":"Okumayı sevmemi ilkokul öğretmenim sağladı."},{"fr":"J'étais un élève plutôt bavard.","tgt":"Oldukça geveze bir öğrenciydim."},{"fr":"Je détestais les mathématiques, mais j'adorais la musique.","tgt":"Matematikten nefret ederdim ama müziğe bayılırdım."},{"fr":"On faisait toujours des bêtises pendant la récréation.","tgt":"Teneffüste hep yaramazlık yapardık."},{"fr":"Mon meilleur ami d'école habite toujours dans le même quartier.","tgt":"Okuldan en yakın arkadaşım hâlâ aynı mahallede oturuyor."},{"fr":"Nous nous sommes revus vingt ans plus tard.","tgt":"Yirmi yıl sonra yeniden görüştük."},{"fr":"Le professeur qui m'a le plus marqué était très sévère.","tgt":"Beni en çok etkileyen öğretmen çok sertti."},{"fr":"Je me rappelle encore le jour où j'ai été puni.","tgt":"Ceza aldığım günü hâlâ hatırlıyorum."},{"fr":"Les années d'école passent tellement vite !","tgt":"Okul yılları ne kadar çabuk geçiyor!"},{"fr":"Si c'était à refaire, je travaillerais davantage.","tgt":"Baştan başlasaydım daha çok çalışırdım."}]},{"title":"Un après-midi dans un café de Balat","phrases":[{"fr":"Retrouvons-nous au café près des escaliers colorés.","tgt":"Rengârenk merdivenlerin yanındaki kafede buluşalım."},{"fr":"Ici, le café turc est servi avec un loukoum.","tgt":"Burada Türk kahvesi lokumla servis ediliyor."},{"fr":"Comment voulez-vous votre café ?","tgt":"Kahveniz nasıl olsun?"},{"fr":"Moyennement sucré, s'il vous plaît.","tgt":"Orta şekerli olsun, lütfen."},{"fr":"Il paraît que ce café était autrefois une épicerie.","tgt":"Bu kafe eskiden bir bakkal dükkânıymış."},{"fr":"Les rues en pente de Balat fatiguent les jambes.","tgt":"Balat'ın yokuşlu sokakları insanı yoruyor."},{"fr":"Un chat s'est installé sur la chaise d'à côté.","tgt":"Yandaki sandalyeye bir kedi yerleşti."},{"fr":"Les chats d'Istanbul sont les vrais maîtres de la ville.","tgt":"İstanbul'un kedileri şehrin gerçek sahipleri."},{"fr":"On pourrait rester assis ici à bavarder pendant des heures.","tgt":"Burada saatlerce oturup sohbet edebiliriz."},{"fr":"Le soleil se couche, il est temps de descendre vers la Corne d'Or.","tgt":"Güneş batıyor, Haliç'e doğru inme vakti."}]},{"title":"L'Istanbul d'autrefois","phrases":[{"fr":"Ma grand-mère dit que la ville était bien plus calme autrefois.","tgt":"Babaannem eskiden şehrin çok daha sakin olduğunu söylüyor."},{"fr":"Jadis, les gens traversaient le Bosphore en barque.","tgt":"Bir zamanlar insanlar Boğaz'ı sandalla geçerdi."},{"fr":"Il n'y avait presque pas de voitures dans les rues.","tgt":"Sokaklarda neredeyse hiç araba yoktu."},{"fr":"Les marchands ambulants criaient sous les fenêtres.","tgt":"Seyyar satıcılar pencerelerin altından bağırırdı."},{"fr":"Dans le quartier, tout le monde se connaissait.","tgt":"Mahallede herkes birbirini tanırdı."},{"fr":"Les voisins partageaient leurs repas entre eux.","tgt":"Komşular yemeklerini birbirleriyle paylaşırdı."},{"fr":"Je regrette un peu de ne pas avoir connu ces jours-là.","tgt":"O günleri göremediğime biraz üzülüyorum."},{"fr":"Mais chaque époque a son charme bien à elle.","tgt":"Ama her dönemin kendine has bir güzelliği var."},{"fr":"Les vieilles photos racontent une tout autre Istanbul.","tgt":"Eski fotoğraflar bambaşka bir İstanbul'u anlatıyor."},{"fr":"La nostalgie embellit souvent le passé.","tgt":"Nostalji geçmişi çoğu zaman olduğundan daha güzel gösterir."}]},{"title":"La sagesse des proverbes","phrases":[{"fr":"Les petites gouttes finissent par former un lac.","tgt":"Damlaya damlaya göl olur."},{"fr":"Une tasse de café laisse quarante ans de souvenir.","tgt":"Bir fincan kahvenin kırk yıl hatırı vardır."},{"fr":"Ne te moque pas de ton voisin, cela pourrait t'arriver aussi.","tgt":"Gülme komşuna, gelir başına."},{"fr":"Garde même la paille, son heure viendra.","tgt":"Sakla samanı, gelir zamanı."},{"fr":"C'est quand l'arbre est jeune qu'on peut le plier.","tgt":"Ağaç yaşken eğilir."},{"fr":"Une parole douce fait sortir le serpent de son trou.","tgt":"Tatlı dil yılanı deliğinden çıkarır."},{"fr":"Même si tu sais mille choses, consulte celui qui en sait une.","tgt":"Bin bilsen de bir bilene danış."},{"fr":"Ma grand-mère avait un proverbe pour chaque situation.","tgt":"Anneannemin her duruma uygun bir atasözü vardı."},{"fr":"Ce proverbe correspond parfaitement à ma façon d'apprendre.","tgt":"Bu atasözü benim öğrenme şeklime tam uyuyor."},{"fr":"Il y a beaucoup de sagesse dans ces vieilles paroles.","tgt":"Bu eski sözlerde çok bilgelik var."}],"tip":{"title":"Les proverbes turcs : « damlaya damlaya göl olur »","example":"Les petites gouttes finissent par former un lac. — <b>Damlaya damlaya</b> göl olur.","body":"Les Turcs glissent volontiers un proverbe dans la conversation, et en placer un au bon moment fait toujours sourire. « Damlaya damlaya göl olur » se décompose en « damlaya damlaya », en gouttant en gouttant, puis « göl olur », cela devient un lac : la répétition imite les gouttes qui tombent une à une. C'est l'équivalent de notre petit à petit, l'oiseau fait son nid, et c'est la devise parfaite pour apprendre une langue. Beaucoup de proverbes utilisent l'aoriste, le temps des vérités générales, comme « ağaç yaşken eğilir », l'arbre se plie quand il est jeune. Astuce : retenez-en deux ou trois avec leur rythme, comme une petite chanson, et ressortez-les au café avec vos amis.","lit":"en-gouttant · en-gouttant · lac · devient","say":{"damlaya damlaya göl olur":"damlaya damlaya göl olur","Damlaya damlaya göl olur":"Damlaya damlaya göl olur","damlaya damlaya":"damlaya damlaya","göl olur":"göl olur","ağaç yaşken eğilir":"ağaç yaşken eğilir"}}},{"title":"Les conseils d'un ancien sur le ferry","phrases":[{"fr":"Sur le ferry, un vieux monsieur a engagé la conversation avec moi.","tgt":"Vapurda yaşlı bir amca benimle sohbet etmeye başladı."},{"fr":"Il m'a demandé depuis combien de temps j'apprenais le turc.","tgt":"Ne zamandır Türkçe öğrendiğimi sordu."},{"fr":"Il m'a conseillé de parler aux gens sans avoir peur.","tgt":"Korkmadan insanlarla konuşmamı tavsiye etti."},{"fr":"Selon lui, les fautes font partie de l'apprentissage.","tgt":"Ona göre hatalar öğrenmenin bir parçası."},{"fr":"Il a été pêcheur sur le Bosphore pendant quarante ans.","tgt":"Kırk yıl Boğaz'da balıkçılık yapmış."},{"fr":"Il connaissait chaque recoin de la côte comme sa poche.","tgt":"Kıyının her köşesini avucunun içi gibi biliyordu."},{"fr":"Il m'a dit de ne jamais me presser dans la vie.","tgt":"Hayatta asla acele etmememi söyledi."},{"fr":"Ses paroles m'ont profondément touché.","tgt":"Sözleri beni derinden etkiledi."},{"fr":"En descendant à Kadıköy, il m'a serré la main.","tgt":"Kadıköy'de inerken elimi sıktı."},{"fr":"Je n'ai même pas eu le temps de lui demander son nom.","tgt":"Adını sormaya bile fırsatım olmadı."}]},{"title":"Un malentendu entre amis","phrases":[{"fr":"Je crois qu'il y a eu un malentendu entre nous.","tgt":"Sanırım aramızda bir yanlış anlaşılma oldu."},{"fr":"Je ne voulais pas vous blesser.","tgt":"Sizi kırmak istemedim."},{"fr":"Je comprends pourquoi vous êtes déçu.","tgt":"Neden hayal kırıklığına uğradığınızı anlıyorum."},{"fr":"Mettons-nous chacun à la place de l'autre.","tgt":"Kendimizi birbirimizin yerine koyalım."},{"fr":"Ce n'est rien, ça arrive à tout le monde.","tgt":"Önemli değil, herkesin başına gelir."},{"fr":"Parlons-en calmement autour d'un thé.","tgt":"Bir çay eşliğinde sakin sakin konuşalım."},{"fr":"J'aurais dû vous prévenir plus tôt.","tgt":"Size daha önce haber vermeliydim."},{"fr":"Je vous présente mes excuses.","tgt":"Sizden özür dilerim."},{"fr":"Oublions cette histoire, d'accord ?","tgt":"Bu meseleyi unutalım, olur mu?"},{"fr":"Notre amitié est plus forte que cette petite dispute.","tgt":"Dostluğumuz bu küçük tartışmadan daha güçlü."}]},{"title":"Raconter une belle mésaventure","phrases":[{"fr":"Il faut que je vous raconte ce qui m'est arrivé hier.","tgt":"Dün başıma geleni size anlatmam lazım."},{"fr":"Je me suis trompé de ferry et je me suis retrouvé aux îles des Princes.","tgt":"Yanlış vapura binmişim, kendimi Adalar'da buldum."},{"fr":"Au début, j'étais un peu inquiet.","tgt":"Başta biraz endişelendim."},{"fr":"Puis j'ai décidé de profiter de la journée.","tgt":"Sonra günün tadını çıkarmaya karar verdim."},{"fr":"J'ai loué un vélo et j'ai fait le tour de l'île.","tgt":"Bisiklet kiralayıp adanın etrafını dolaştım."},{"fr":"Un pêcheur m'a invité à boire un thé avec lui.","tgt":"Bir balıkçı beni çay içmeye davet etti."},{"fr":"Il m'a montré la plus belle crique de l'île.","tgt":"Bana adanın en güzel koyunu gösterdi."},{"fr":"Je suis rentré le soir par le dernier ferry.","tgt":"Akşam son vapurla döndüm."},{"fr":"Au bout du compte, cette erreur a été la plus belle surprise du voyage.","tgt":"Sonunda bu hata gezinin en güzel sürprizi oldu."},{"fr":"Comme quoi, il faut parfois se perdre pour découvrir.","tgt":"Demek ki bazen keşfetmek için kaybolmak gerekiyor."}]},{"title":"Ce qui rend heureux","phrases":[{"fr":"Pour moi, le bonheur se cache dans les petites choses.","tgt":"Bana göre mutluluk küçük şeylerde saklı."},{"fr":"Un verre de thé face au Bosphore me suffit.","tgt":"Boğaz'a karşı bir bardak çay bana yeter."},{"fr":"Être en bonne santé est la plus grande des richesses.","tgt":"Sağlıklı olmak en büyük zenginlik."},{"fr":"Le bonheur ne se mesure pas à l'argent.","tgt":"Mutluluk parayla ölçülmez."},{"fr":"Les gens qui sourient facilement me rendent heureux.","tgt":"Kolay gülümseyen insanlar beni mutlu ediyor."},{"fr":"J'essaie d'apprécier chaque instant à sa juste valeur.","tgt":"Her anın kıymetini bilmeye çalışıyorum."},{"fr":"Un bonheur partagé est un bonheur multiplié par deux.","tgt":"Paylaşılan mutluluk iki katına çıkar."},{"fr":"Il m'a fallu du temps pour comprendre ce qui comptait vraiment.","tgt":"Gerçekten neyin önemli olduğunu anlamam zaman aldı."},{"fr":"Et vous, qu'est-ce qui vous rend heureux ?","tgt":"Peki sizi ne mutlu ediyor?"},{"fr":"Aujourd'hui, je me sens simplement en paix.","tgt":"Bugün kendimi sadece huzurlu hissediyorum."}]},{"title":"Le temps qui passe","phrases":[{"fr":"Le temps file beaucoup trop vite.","tgt":"Zaman çok hızlı akıp gidiyor."},{"fr":"Le jour de mon arrivée ici, c'est comme si c'était hier.","tgt":"Buraya geldiğim gün sanki dün gibi."},{"fr":"Mes enfants ont grandi sans même que je m'en aperçoive.","tgt":"Ben farkına bile varmadan çocuklarım büyüdü."},{"fr":"Avec l'âge, on devient plus patient.","tgt":"Yaş ilerledikçe insan daha sabırlı oluyor."},{"fr":"Je ne regrette rien de ce que j'ai vécu.","tgt":"Yaşadığım hiçbir şeyden pişman değilim."},{"fr":"Chaque ride raconte une histoire.","tgt":"Her kırışıklık bir hikâye anlatır."},{"fr":"Il faut profiter de chaque saison de la vie.","tgt":"Hayatın her mevsiminin tadını çıkarmak lazım."},{"fr":"Mes parents vieillissent, et je veux passer plus de temps avec eux.","tgt":"Annemle babam yaşlanıyor, onlarla daha çok vakit geçirmek istiyorum."},{"fr":"Les amis d'enfance sont un lien précieux avec notre passé.","tgt":"Çocukluk arkadaşları geçmişimizle aramızdaki değerli bir bağdır."},{"fr":"Le plus beau moment, c'est toujours maintenant.","tgt":"En güzel an her zaman şimdidir."}]},{"title":"Dire au revoir à Istanbul","phrases":[{"fr":"Demain, je quitte Istanbul, et j'ai le cœur serré.","tgt":"Yarın İstanbul'dan ayrılıyorum, içim buruk."},{"fr":"J'étais venu pour quelques semaines, et je suis resté des mois.","tgt":"Birkaç haftalığına gelmiştim, aylarca kaldım."},{"fr":"Cette ville m'a beaucoup appris sur moi-même.","tgt":"Bu şehir bana kendimle ilgili çok şey öğretti."},{"fr":"Les cris des mouettes du matin vont me manquer.","tgt":"Sabahları martıların seslerini özleyeceğim."},{"fr":"Merci pour votre hospitalité et votre gentillesse.","tgt":"Misafirperverliğiniz ve nezaketiniz için teşekkür ederim."},{"fr":"En France, ma porte vous sera toujours ouverte.","tgt":"Fransa'da evimin kapısı size her zaman açık."},{"fr":"Ne m'oubliez pas, écrivez-moi de temps en temps.","tgt":"Beni unutmayın, ara sıra yazın."},{"fr":"Je reviendrai, c'est promis.","tgt":"Geri döneceğim, söz veriyorum."},{"fr":"Portez-vous bien, et à la prochaine fois !","tgt":"Hoşça kalın, bir dahaki sefere görüşmek üzere!"},{"fr":"Istanbul restera pour toujours dans mon cœur.","tgt":"İstanbul sonsuza dek kalbimde kalacak."}]},{"title":"Regard en arrière sur le parcours en turc","phrases":[{"fr":"Au début, je ne savais même pas dire bonjour en turc.","tgt":"Başlarda Türkçe merhaba demeyi bile bilmiyordum."},{"fr":"Les suffixes me faisaient peur, maintenant je les adore.","tgt":"Ekler eskiden beni korkuturdu, şimdi onlara bayılıyorum."},{"fr":"J'ai appris le turc surtout pendant mes trajets quotidiens.","tgt":"Türkçeyi en çok her günkü yolculuklarımda öğrendim."},{"fr":"Aujourd'hui, je peux bavarder des heures avec mes amis turcs.","tgt":"Bugün Türk arkadaşlarımla saatlerce sohbet edebiliyorum."},{"fr":"L'harmonie vocalique est devenue presque naturelle pour moi.","tgt":"Ünlü uyumu benim için neredeyse doğal hâle geldi."},{"fr":"Il m'arrive même de rêver en turc.","tgt":"Hatta bazen Türkçe rüya görüyorum."},{"fr":"Chaque erreur m'a rapproché un peu plus de mon but.","tgt":"Her hata beni hedefime biraz daha yaklaştırdı."},{"fr":"Le turc m'a ouvert les portes d'une culture fascinante.","tgt":"Türkçe bana büyüleyici bir kültürün kapılarını açtı."},{"fr":"Quand je repense à mes débuts, je mesure tout le chemin parcouru.","tgt":"İlk günlerimi düşündükçe ne kadar yol aldığımı anlıyorum."},{"fr":"Comme dit le proverbe, goutte après goutte, le lac s'est formé.","tgt":"Atasözünün dediği gibi, damlaya damlaya göl oldu."}]},{"title":"Fin du parcours : un dernier bilan","phrases":[{"fr":"Ce dernier module nous a plongés au cœur des conversations stambouliotes.","tgt":"Bu son modül bizi İstanbul sohbetlerinin tam ortasına götürdü."},{"fr":"Nous avons appris des expressions imagées et de vieux proverbes.","tgt":"Deyimler ve eski atasözleri öğrendik."},{"fr":"Nous savons maintenant remercier, féliciter et souhaiter en turc.","tgt":"Artık Türkçe teşekkür etmeyi, tebrik etmeyi ve iyi dileklerde bulunmayı biliyoruz."},{"fr":"Comparer avec « gibi » et « sanki » nous est devenu naturel.","tgt":"«Gibi» ve «sanki» ile karşılaştırma yapmak artık bize doğal geliyor."},{"fr":"Depuis la toute première leçon, nous avons fait un chemin immense.","tgt":"İlk dersten bu yana çok uzun bir yol kat ettik."},{"fr":"Trois niveaux, neuf modules et des centaines de phrases plus tard, nous voilà.","tgt":"Üç seviye, dokuz modül ve yüzlerce cümle sonra işte buradayız."},{"fr":"Le plus important maintenant, c'est de continuer à parler.","tgt":"Şimdi en önemlisi konuşmaya devam etmek."},{"fr":"N'ayez pas peur de faire des fautes avec vos amis turcs.","tgt":"Türk arkadaşlarınızla konuşurken hata yapmaktan korkmayın."},{"fr":"Bravo pour ce beau parcours, vous l'avez bien mérité.","tgt":"Bu güzel yolculuk için tebrikler, bunu hak ettiniz."},{"fr":"À bientôt, sur les rives du Bosphore ou ailleurs !","tgt":"Boğaz kıyısında ya da başka bir yerde, görüşmek üzere!"}]}]}]}];
